    So_PO: String(row[22] ?? ''),
    so_po: String(row[22] ?? ''),
    Ten_PO: String(row[23] ?? ''),
    po_content: String(row[23] ?? ''),
    content_of_contract_PO: contentVal,
    content_of_contract_po: contentVal,
    content_po: contentVal,
