    phan_tram_chiet_khau_tong_truoc_thue: toNum(row[26], 0),
    phan_tram_chiet_khau: toNum(row[26], 0),
    thue_chenh_lech_gia: toNum(row[27], 0),
    phan_tram_thue_chenh_lech_gia: toNum(row[28], 0),
