let isSyncingFromDrag = false
const draggingGroupKey = ref<string | null>(null)

const QUOTE_GROUP_BY_CAT_STORAGE_KEY = 'nts_quote_group_by_category_v1'
function loadSavedQuoteGroupMode(): boolean {
  try {
    const raw = localStorage.getItem(QUOTE_GROUP_BY_CAT_STORAGE_KEY)
    if (raw === '0' || raw === 'false') return false
    if (raw === '1' || raw === 'true') return true
  } catch {}
  return true
}
const quoteGroupByCategory = ref<boolean>(loadSavedQuoteGroupMode())

const QUOTE_THEME_MODE_STORAGE_KEY = 'nts_quote_theme_mode_v1'
function loadSavedQuoteThemeMode(): 'dark' | 'light' {
  try {
    const raw = localStorage.getItem(QUOTE_THEME_MODE_STORAGE_KEY)
    if (raw === 'light') return 'light'
  } catch {}
  return 'dark'
}
const quoteThemeMode = ref<'dark' | 'light'>(loadSavedQuoteThemeMode())
function setQuoteThemeMode(mode: 'dark' | 'light') {
  quoteThemeMode.value = mode
  try {
    localStorage.setItem(QUOTE_THEME_MODE_STORAGE_KEY, mode)
  } catch {}
}

function consolidateSelectedItemsByCategory() {
  if (selectedItems.value.length <= 1) return
  const result: any[] = []
  const handledCats = new Set<string>()
  for (let i = 0; i < selectedItems.value.length; i++) {
    const it = selectedItems.value[i]
    const catKey = (it.Danh_muc || '').trim().toUpperCase()
    if (!catKey) {
      result.push(it)
      continue
    }
    if (handledCats.has(catKey)) continue
    handledCats.add(catKey)
    for (let j = i; j < selectedItems.value.length; j++) {
      const candidate = selectedItems.value[j]
      if ((candidate.Danh_muc || '').trim().toUpperCase() === catKey) {
        result.push(candidate)
      }
    }
  }
  const changed = result.some((it, idx) => it !== selectedItems.value[idx])
  if (changed) {
    selectedItems.value = result
  }
}

function toggleQuoteGroupByCategory() {
  quoteGroupByCategory.value = !quoteGroupByCategory.value
  try {
    localStorage.setItem(QUOTE_GROUP_BY_CAT_STORAGE_KEY, quoteGroupByCategory.value ? '1' : '0')
  } catch {}
  if (quoteGroupByCategory.value) {
    consolidateSelectedItemsByCategory()
  }
  syncFlatRows()
}

function syncFlatRows() {
  const rows: any[] = []
  let currentGroupKey: string | null = null
  let groupIndex = 0
  let stt = 0
  
  selectedItems.value.forEach((it, idx) => {
    if (!it.uid) it.uid = Math.random().toString(36).substr(2, 9)
    const cat = (it.Danh_muc || '').trim()
    const gKey = cat.toUpperCase()

    if (!quoteGroupByCategory.value) {
      stt++
      rows.push({
        type: 'item',
        item: it,
        idx: idx,
        stt: stt,
        groupKey: '',
        uniqueId: 'item-' + it.uid
      })
      return
    }
    
    if (gKey) {
      if (gKey !== currentGroupKey) {
        currentGroupKey = gKey
        groupIndex++
        stt = 0
        rows.push({
          type: 'group',
          key: gKey,
          title: cat,
          roman: toRoman(groupIndex),
          uniqueId: 'group-' + gKey + '-' + groupIndex
        })
      }
    } else {
      if (currentGroupKey !== '') {
        currentGroupKey = ''
        stt = 0
      }
    }
    
    stt++
    rows.push({
      type: 'item',
      item: it,
      idx: idx,
      stt: stt,
      groupKey: gKey,
      uniqueId: 'item-' + it.uid
    })
  })
  flatQuoteRows.value = rows
}

watch(selectedItems, () => {
  if (!isSyncingFromDrag) {
    syncFlatRows()
  }
}, { deep: true, immediate: true });

function onFlatDragStart(event: any) {
  const r = flatQuoteRows.value[event.oldIndex];
  if (r && r.type === 'group') {
    draggingGroupKey.value = r.key;
  }
}

function hideDragImage(dataTransfer: any) {
  const emptyImage = new Image();
  emptyImage.src = 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==';
  dataTransfer.setDragImage(emptyImage, 0, 0);
}

function onFlatDragEnd(event: any) {
  isSyncingFromDrag = true
  const newItems: any[] = []
  let draggedItemIdx = -1
  
  if (draggingGroupKey.value) {
    const handledGroups = new Set<string>()
    flatQuoteRows.value.forEach(r => {
      if (r.type === 'group' && r.key && !handledGroups.has(r.key)) {
        handledGroups.add(r.key)
        flatQuoteRows.value.forEach(itemRow => {
          if (itemRow.type === 'item' && itemRow.groupKey === r.key) {
            newItems.push(itemRow.item)
          }
        })
      } else if (r.type === 'item' && !r.groupKey) {
        newItems.push(r.item)
      }
    })
  } else {
    flatQuoteRows.value.forEach((r, idxInFlat) => {
      if (r.type === 'item') {
        newItems.push(r.item)
        if (idxInFlat === event.newIndex) {
          draggedItemIdx = newItems.length - 1
        }
      }
    })
  }

  draggingGroupKey.value = null;
  
  setTimeout(() => {
    selectedItems.value = newItems
    syncFlatRows()
    nextTick(() => { 
      isSyncingFromDrag = false 
      if (draggedItemIdx >= 0) {
        scrollToAndHighlightRow(draggedItemIdx, false)
      }
    })
  }, 50)
}

function checkMove(evt: any) {
  if (!quoteGroupByCategory.value) return true;

  const dragged = evt.draggedContext.element;
  const related = evt.relatedContext.element;

  if (!dragged || !related) return true;

  if (dragged.type === 'item') {
    if (related.type === 'group') {
      return false;
    }
    if (related.type === 'item' && dragged.groupKey !== related.groupKey) {
      return false;
    }
  }

  return true;
}
