    id = `${danhMuc}-${ten}`;
  } else if (danhMuc) {
    id = danhMuc;
  } else if (ten) {
    id = ten;
  }

  id = id.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
  id = id.toUpperCase().replace(/\s+/g, '-').replace(/[^A-Z0-9\-]/g, '');
  id = id.replace(/-+/g, '-').replace(/^-+/, '').replace(/-+$/, '');
  
  itemForm.value.Ma_hang = id;
}

