function getSelectedQtyForProduct(p: HangHoa): number {
  if (!p) return 0
  const code = String(p.Ma_hang || '').trim()
  if (!code) return 0
  let sum = 0
  for (const it of selectedItems.value) {
    if (it.Ma_hang === code) {
      sum += Number(it.So_luong) || 0
    }
  }
  return sum
}

