    Tong_loi_nhuan: String(obj.tong_loi_nhuan ?? obj.Tong_loi_nhuan ?? ''),
    Trang_thai: String(obj.trang_thai ?? obj.Trang_thai ?? ''),
    Ghi_chu: String(obj.ghi_chu ?? obj.Ghi_chu ?? ''),
