    cong_no: toNum(obj.cong_no ?? obj.Cong_no, 0),
    last_updated: String(obj.last_updated ?? obj.Last_updated ?? obj.ngay_cap_nhat ?? obj.created_time ?? ''),
    _firebaseKey: fbKey || String(obj.ma_khach_hang ?? obj.Ma_khach_hang ?? '')
