  quoteEditRaw.value._Thue_VAT_goc = Math.max(0, toNum(quoteEditRaw.value._Thue_VAT_goc, 0))
  quoteEditRaw.value._gia_hardware_goc = Math.max(0, toNum(quoteEditRaw.value._gia_hardware_goc, 0))
