function requestExportWithSaveConfirm(format: ExportFormatType) {
  pendingExportFormat.value = format
  showExportSaveConfirmModal.value = true
}

async function executeExportByFormat(format: ExportFormatType) {
  if (format === 'agency_excel') {
    await exportAgencyExcel()
  } else {
    await exportQuoteByPrintTemplate(format)
  }
}

async function handleExportSaveConfirmChoice(choice: 'temp' | 'official' | 'cancel') {
  const format = pendingExportFormat.value
  showExportSaveConfirmModal.value = false
  showSaveModal.value = false
  if (!format) return

  syncCustomerInputsToKhach()

  if (choice === 'cancel') {
    pendingExportFormat.value = null
    pendingSaveFromExport.value = false
    if (format !== 'pdf' && format !== 'agency_excel') {
      showExportExcelModal.value = false
    }
    await executeExportByFormat(format)
    return
  }

  const err = canSaveContractBasic()
  if (err) {
    pendingExportFormat.value = null
    pendingSaveFromExport.value = false
    saveMsg.value = err
    showAsyncError('⚠️ Lỗi', err)
    return
  }

  if (!khach.value.Ma_khach_hang?.trim() || (!khach.value.Ten_khach_hang?.trim() && !khach.value.Ten_cong_ty?.trim())) {
    pendingSaveAction.value = choice
    pendingSaveFromExport.value = true
    showConfirmSaveEmptyCustomer.value = true
    return
  }

  pendingExportFormat.value = null
  pendingSaveFromExport.value = false
  if (format !== 'pdf' && format !== 'agency_excel') {
    showExportExcelModal.value = false
  }

  await executeExportByFormat(format)

  if (choice === 'temp') {
    await saveContractTemp(true)
  } else if (choice === 'official') {
    await saveContractOfficialAndSaleReport(true)
  }
}

async function exportQuoteByPrintTemplate(format: 'excel' | 'word' | 'pdf' | 'png' | 'html') {
  if (!printTemplates.value.length) {
    await loadPrintTemplates().catch(() => {})
  }
  const tpl = activePrintTemplate.value
  const normalFileName = getQuoteDownloadBaseName()

  if (!tpl) {
    if (format === 'excel') {
      await exportQuoteExcel(pendingExportTemplateData.value)
    }
    return
  }

  const ctx = buildCurrentQuoteExportContext()
  try {
    if (format === 'excel') {
      showAsyncLoading(`Đang xuất Excel theo mẫu "${tpl.ten_mau}"...`)
      const blob = await generateExcelBlobFromTemplate(tpl, ctx)
      if (isMobileOrIOSPWA()) {
        asyncResultModal.value.show = false
        await deliverExportedFile(
          blob,
          `${normalFileName}.xlsx`,
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
      } else {
        await deliverExportedFile(
          blob,
          `${normalFileName}.xlsx`,
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
        showAsyncSuccess('Xuất Excel thành công', `Đã tải về theo mẫu "${tpl.ten_mau}".`)
      }
    } else if (format === 'word') {
      showAsyncLoading(`Đang xuất Word (.doc) theo mẫu "${tpl.ten_mau}"...`)
      await exportWordFromTemplate(tpl, ctx, normalFileName)
      if (isMobileOrIOSPWA()) {
        asyncResultModal.value.show = false
      } else {
        showAsyncSuccess('Xuất Word thành công', `Đã tải về file Word (.doc) theo mẫu "${tpl.ten_mau}".`)
      }
    } else if (format === 'pdf') {
      exportPdfOrPrintFromTemplate(tpl, ctx, normalFileName)
    } else if (format === 'png') {
      showAsyncLoading(`Đang kết xuất Ảnh (.png) theo mẫu "${tpl.ten_mau}"...`)
      await exportPngFromTemplate(tpl, ctx, normalFileName)
      if (isMobileOrIOSPWA()) {
        asyncResultModal.value.show = false
      } else {
        showAsyncSuccess('Xuất Ảnh thành công', 'File ảnh (.png) đã được tải về.')
      }
    } else if (format === 'html') {
      await exportHtmlFileFromTemplate(tpl, ctx, normalFileName)
      if (isMobileOrIOSPWA()) {
        asyncResultModal.value.show = false
      } else {
        showAsyncSuccess('Xuất HTML thành công', 'File .html đã được tải về.')
      }
    }
  } catch (e: any) {
    console.error('Lỗi xuất báo giá theo mẫu in:', e)
    showAsyncError('Xuất báo giá thất bại', String(e?.message || e))
  }
}

