<div v-if="showLoadPipelineModal" class="modal load-invoice-modal-overlay modal-fullscreen-overlay" @click.self="showLoadPipelineModal = false">
  <div class="modal-card load-invoice-modal modal-fullscreen-card" @scroll.passive="onLoadPipelineGridScroll">
    <div class="modal-head">
      <h3><i class="lucide-folder-input"></i> Load PO-DXMH-DR-Báo giá</h3>
      <button class="x" @click="showLoadPipelineModal = false">×</button>
    </div>
    
    <div class="load-invoice-search" style="padding: 16px 24px 8px; flex-shrink: 0;">
       <input v-model="loadPipelineSearch" placeholder="Tìm kiếm theo Số PO, Tên dự án, Mã Hợp đồng..." class="search-input" style="width: 100%; padding: 12px 16px; border-radius: 8px; border: 1px solid #334155; background: #1e293b; color: #f8fafc; font-size: 15px;" />
    </div>

    <div class="load-invoice-grid" @scroll.passive="onLoadPipelineGridScroll" style="flex: 1; min-height: 0; overflow-y: auto; padding: 8px 24px 16px; display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); gap: 16px; align-content: start;">
      
      <template v-if="pipelineListState === 'loading'">
        <div class="skeleton-card" v-for="n in 6" :key="'sk-pl-'+n">
          <div style="display: flex; justify-content: space-between; margin-bottom: 12px;">
            <div class="skeleton-line" style="width: 120px; height: 18px;"></div>
            <div class="skeleton-line" style="width: 80px; height: 14px;"></div>
          </div>
          <div class="skeleton-line" style="width: 60%; height: 20px; margin-bottom: 12px;"></div>
          <div class="skeleton-line" style="width: 100%; height: 1px; margin-bottom: 12px;"></div>
          <div class="skeleton-line" style="width: 70%; height: 16px; margin-bottom: 8px;"></div>
          <div class="skeleton-line" style="width: 50%; height: 16px; margin-bottom: 16px;"></div>
          <div style="display: flex; justify-content: space-between; margin-bottom: 8px;">
            <div class="skeleton-line" style="width: 40%; height: 14px;"></div>
            <div class="skeleton-line" style="width: 20%; height: 14px;"></div>
          </div>
          <div style="display: flex; justify-content: space-between;">
            <div class="skeleton-line" style="width: 30%; height: 14px;"></div>
            <div class="skeleton-line" style="width: 25%; height: 14px;"></div>
          </div>
        </div>
      </template>

      <template v-else>
        <div v-for="po in filteredPoDxmhList" :key="po.ma_hop_dong" 
             class="invoice-card"
             :class="{ 'selected': loadPipelineFilter === (po.so_po + ' - ' + po.ma_hop_dong) }"
             @click="loadPipelineFilter = (po.so_po + ' - ' + po.ma_hop_dong)"
             @dblclick="loadPipelineFilter = (po.so_po + ' - ' + po.ma_hop_dong); loadPipelineToFE()">
          
          <div class="invoice-card-header">
            <span class="invoice-ma-hd"><i class="lucide-file-text" style="width: 14px; height: 14px;"></i> {{ po.ma_hop_dong || 'N/A' }}</span>
            <span class="invoice-date">{{ po.created_time || '' }}</span>
          </div>
          <div class="invoice-card-body">
            <p class="invoice-po" style="font-size: 15px; font-weight: 700; color: #60a5fa;">PO: {{ po.so_po || 'N/A' }}</p>
            
            <hr class="invoice-divider" />
            
            <p class="invoice-text" v-if="po.company"><i class="ri-building-line" style="margin-right: 4px; color: #64748b;"></i>{{ po.company }}</p>
            <p class="invoice-text" v-if="po.contact"><i class="ri-user-line" style="margin-right: 4px; color: #64748b;"></i>{{ po.contact }}</p>
            
            <div class="invoice-totals" v-if="po.hang_hoa_list && po.hang_hoa_list.length > 0">
              <div v-for="(hh, idx) in po.hang_hoa_list" :key="idx" style="display: flex; justify-content: space-between; align-items: baseline; gap: 8px;">
                <span style="flex: 1; color: #cbd5e1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">{{ hh.ten }}</span>
                <span style="color: #94a3b8; white-space: nowrap; font-size: 12px;">x{{ hh.sl }}</span>
                <span style="color: #10b981; white-space: nowrap; font-weight: 600;">${{ parseFloat(Number(hh.listPrice).toFixed(3)) }}</span>
              </div>
            </div>
            <p v-else class="invoice-text" style="color: #475569; font-style: italic;">Chưa có hàng hóa</p>
          </div>
        </div>

        <div
          v-if="loadPipelineDisplayLimit < filteredPoDxmhRows.length"
          ref="pipelineLazySentinelRef"
          style="grid-column: 1 / -1; height: 24px; width: 100%; flex-shrink: 0;"
        ></div>
        
        <div v-if="filteredPoDxmhRows.length === 0" class="no-results" style="grid-column: 1 / -1; text-align: center; padding: 32px; color: #94a3b8; font-style: italic;">
          Không tìm thấy Pipeline nào phù hợp.
        </div>
      </template>
    </div>
      
    <p v-if="loadPipelineMsg" class="muted" style="text-align: center; margin: 8px 0; padding: 0 16px;" :style="{color: loadPipelineMsg.includes('Lỗi') || loadPipelineMsg.includes('Đã') ? 'red' : 'green'}">
      {{ loadPipelineMsg }}
    </p>

    <div class="modal-actions" style="justify-content: center; padding: 14px 24px; margin-top: 0; border-top: 1px solid #334155; flex-shrink: 0;">
      <button @click="showLoadPipelineModal = false" style="padding: 10px 32px;">Đóng</button>
      <button class="btn-load-fe" :disabled="loadingPipeline || !loadPipelineFilter" @click="loadPipelineToFE">
        {{ loadingPipeline ? 'Đang nạp...' : 'Nạp dữ liệu' }}
      </button>
    </div>
  </div>
</div>

    <!-- ================== MODAL: LOAD HÓA ĐƠN / HỢP ĐỒNG ================== -->
<div v-if="showLoadInvoiceModal" class="modal load-invoice-modal-overlay modal-fullscreen-overlay" @click.self="showLoadInvoiceModal = false">
  <div class="modal-card load-invoice-modal modal-fullscreen-card" @scroll.passive="onLoadInvoiceGridScroll">
    <div class="modal-head">
      <h3><i class="lucide-download"></i> Load hóa đơn / hợp đồng</h3>
      <button class="x" @click="showLoadInvoiceModal = false">✕</button>
    </div>

    <div class="load-invoice-search" style="padding: 16px 24px 8px; flex-shrink: 0;">
       <input v-model="loadSearchQuery" placeholder="Tìm kiếm theo Số HĐ, Mã HĐ, Số PO, Tên khách hàng, Tên công ty..." class="search-input" style="width: 100%; padding: 12px 16px; border-radius: 8px; border: 1px solid #334155; background: #1e293b; color: #f8fafc; font-size: 15px;" />
    </div>

    <div class="load-invoice-filters" style="display: flex; gap: 12px; padding: 0 24px 12px; align-items: center; justify-content: flex-start; flex-wrap: wrap; flex-shrink: 0;">
      <div style="display: flex; align-items: center; gap: 8px;">
        <label style="color: #94a3b8; font-size: 13px; white-space: nowrap;">Từ:</label>
        <input type="date" v-model="loadFromDate" class="filter-input" />
      </div>
      <div style="display: flex; align-items: center; gap: 8px;">
        <label style="color: #94a3b8; font-size: 13px; white-space: nowrap;">Đến:</label>
        <input type="date" v-model="loadToDate" class="filter-input" />
      </div>
      <select v-model="loadStatusFilter" class="filter-select" style="min-width: 150px;">
        <option value="">Tất cả trạng thái</option>
        <option value="Tạm">Tạm</option>
        <option value="Chính thức">Chính thức</option>
      </select>
      <select v-model="loadSortBy" class="filter-select" style="min-width: 160px;">
        <option value="desc">Mới nhất ➔ Cũ nhất</option>
        <option value="asc">Cũ nhất ➔ Mới nhất</option>
      </select>
    </div>

    <div class="load-invoice-grid" @scroll.passive="onLoadInvoiceGridScroll" style="flex: 1; min-height: 0; overflow-y: auto; padding: 0 24px 16px; display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); gap: 16px; align-content: start;">
      <template v-if="invoiceListState === 'loading'">
        <div class="skeleton-card" v-for="n in 6" :key="'sk-iv-'+n">
          <div style="display: flex; justify-content: space-between; margin-bottom: 12px;">
            <div class="skeleton-line" style="width: 140px; height: 18px;"></div>
            <div class="skeleton-line" style="width: 80px; height: 14px;"></div>
          </div>
          <div class="skeleton-line" style="width: 50%; height: 16px; margin-bottom: 8px;"></div>
          <div class="skeleton-line" style="width: 70%; height: 16px; margin-bottom: 12px;"></div>
          <div class="skeleton-line" style="width: 100%; height: 1px; margin-bottom: 12px;"></div>
          <div class="skeleton-line" style="width: 80%; height: 16px; margin-bottom: 8px;"></div>
          <div class="skeleton-line" style="width: 60%; height: 16px; margin-bottom: 16px;"></div>
          <div style="display: flex; flex-direction: column; gap: 8px;">
            <div class="skeleton-line" style="width: 100%; height: 16px;"></div>
            <div class="skeleton-line" style="width: 90%; height: 16px;"></div>
            <div class="skeleton-line" style="width: 95%; height: 16px;"></div>
          </div>
        </div>
      </template>

      <template v-else>
      <div 
        v-for="r in contractCards" 
        :key="r.maHD" 
        class="invoice-card"
        :class="{ 'selected': loadMode === 'MA' && loadKey === r.maHD }"
        @click="loadMode = 'MA'; loadKey = r.maHD;"
        @dblclick="loadMode = 'MA'; loadKey = r.maHD; loadInvoiceToFE()"
      >
        <div class="invoice-card-header">
          <span class="invoice-ma-hd"><i class="lucide-file-text" style="width: 14px; height: 14px;"></i> {{ r.maHD || 'Chưa có Mã HĐ' }}</span>
          <span class="invoice-date">{{ r.ngay }}</span>
        </div>
        <div class="invoice-card-body">
          <p v-if="r.soPO" class="invoice-po">Số PO: {{ r.soPO }}</p>
          <p class="invoice-status">Trạng thái hợp đồng: <span class="status-badge" :class="{'badge-temp': r.trangThai === 'Tạm', 'badge-official': r.trangThai === 'Chính thức'}">{{ r.trangThai }}</span></p>
          
          <hr class="invoice-divider" />
          
          <p v-if="r.mst" class="invoice-text">MST: {{ r.mst }}</p>
          <p v-if="r.tenCongTy" class="invoice-text">Tên công ty: {{ r.tenCongTy }}</p>
          <p class="invoice-customer">Tên khách hàng: {{ r.tenKH }}</p>
          
          <div class="invoice-totals">
            <p style="color: #ef4444;">Tổng giá thực tế: <span>{{ formatVND(r.tongGiaThucTe) }}</span></p>
            <p>Tổng tiền trước thuế: <span>{{ formatVND(r.truocThue) }}</span></p>
            <p class="highlight" style="border-bottom: 1px dashed rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 4px;">Tổng tiền sau thuế: <span>{{ formatVND(r.sauThue) }}</span></p>
            <p>Chênh lệch giá: <span style="color: #10b981">{{ r.chenhLechGia > 0 ? '+' : '' }}{{ formatVND(r.chenhLechGia) }}</span></p>
            <p>Còn lại: <span>{{ formatVND(r.conLai) }}</span></p>
            <p style="color: #eab308; margin-top: 4px; padding-top: 8px; border-top: 1px dashed rgba(255,255,255,0.2);">Tổng chiết khấu: <span>{{ formatVND(r.tongChietKhau) }}</span></p>
          </div>
        </div>
      </div>

      <div
        v-if="loadInvoiceDisplayLimit < filteredContractRowsForCards.length"
        ref="invoiceLazySentinelRef"
        style="grid-column: 1 / -1; height: 24px; width: 100%; flex-shrink: 0;"
      ></div>

      <div v-if="filteredContractRowsForCards.length === 0" class="no-results" style="grid-column: 1 / -1; text-align: center; padding: 32px; color: #94a3b8; font-style: italic;">
        Không tìm thấy hợp đồng/hóa đơn nào phù hợp.
      </div>
      </template>
    </div>

    <p v-if="loadMsg" class="muted" style="text-align: center; margin: 8px 0;">{{ loadMsg }}</p>

    <div class="modal-actions" style="justify-content: center; padding: 14px 24px; margin-top: 0; border-top: 1px solid #334155; gap: 12px; display: flex; flex-shrink: 0;">
      <button @click="showLoadInvoiceModal = false" style="padding: 10px 32px; background: rgba(255,255,255,0.05); color: #f1f5f9; border: 1px solid rgba(255,255,255,0.1); border-radius: 8px;">Đóng</button>
      <button class="btn-load-fe" :disabled="loadingInvoice || !loadKey" @click="cloneInvoiceToFE" style="background: linear-gradient(135deg, #10b981 0%, #059669 100%);">
        {{ loadingInvoice ? 'Đang nhân bản...' : 'Nhân bản' }}
      </button>
      <button class="btn-load-fe" :disabled="loadingInvoice || !loadKey" @click="loadInvoiceToFE" style="background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);">
        {{ loadingInvoice ? 'Đang load...' : 'Chỉnh sửa báo giá' }}
      </button>
    </div>
  </div>
</div>


<!-- ================== MODAL: CHỌN SỐ HỢP ĐỒNG SO SÁNH ================== -->
<div v-if="showPickCompareModal" class="modal" @click.self="showPickCompareModal = false">
  <div class="modal-card" style="width:min(520px,96vw)">
    <div class="modal-head">
      <h3><i class="lucide-bar-chart-3"></i> Chọn SỐ hợp đồng để so sánh</h3>
      <button class="x" @click="showPickCompareModal = false">✕</button>
    </div>

    <label>Số hợp đồng</label>
    <input
      v-model="pickCompareSo"
      list="dl-compare-so"
      placeholder="VD: HĐ9"
    />

    <datalist id="dl-compare-so">
      <option
        v-for="r in filteredContractsForLoad"
        :key="'cmp-' + r[1]"
        :value="String(r?.[1] ?? '').trim()"
      >
        {{ String(r?.[1] ?? '').trim() }}
        -
        {{ String(r?.[0] ?? '').trim() }}
        -
        {{ String(r?.[IDX_TIME] ?? '').trim() }}
      </option>
    </datalist>

    <div class="modal-actions">
      <button
        class="primary"
        :disabled="!pickCompareSo"
        @click="
          compareSoHopDong = pickCompareSo;
          loadCompareBySoHopDong(pickCompareSo);
          showPickCompareModal = false;
          showCompareModal = true;
        "
      >
        So sánh
      </button>
      <button @click="showPickCompareModal = false">Hủy</button>
    </div>
  </div>
</div>

<!-- ================== MODAL: BẢNG SO SÁNH ================== -->
<div v-if="showCompareModal" class="modal" @click.self="showCompareModal = false">
  <div class="modal-card modal-wide">
    <div class="modal-head">
      <h3><i class="lucide-bar-chart-3"></i> So sánh hợp đồng – {{ compareSoHopDong }}</h3>
      <button class="x" @click="showCompareModal = false">✕</button>
    </div>

    <!-- ===== TỔNG HÓA ĐƠN ===== -->
   <h4>🔹 So sánh tổng hóa đơn (theo mã hợp đồng)</h4>

<table>
  <thead>
    <tr>
      <th>Mã hợp đồng</th>
      <th class="right">Tổng trước thuế</th>
      <th class="right">Tổng tiêu chuẩn</th>
      <th class="right">Chênh lệch</th>
      <th class="right">%</th>
    </tr>
  </thead>

  <tbody>
    <tr v-for="r in compareByContract" :key="r.Ma_hop_dong">
      <td>{{ r.Ma_hop_dong }}</td>

      <td class="right">{{ formatVND(r.truoc) }}</td>
      <td class="right">{{ formatVND(r.tieuChuan) }}</td>

      <td
        class="right"
        :style="{ color: r.diff >= 0 ? 'green' : 'red' }"
      >
        {{ formatVND(r.diff) }}
      </td>

      <td class="right">{{ r.pct.toFixed(2) }}%</td>
    </tr>
  </tbody>
</table>




    <hr />

    <!-- ===== THEO MÃ HÀNG ===== -->
   
   <h4>🔹 So sánh mã hàng </h4>

<table>
  <thead>
    <tr>
      <th>Mã hàng</th>
      <th>Tên hàng</th>
      <th v-for="maHD in compareMaHopDongs" :key="maHD">
        {{ maHD }}
      </th>
    </tr>
  </thead>

  <tbody>
    <tr v-for="r in compareMatrix" :key="r.Ma_hang">
      <td>{{ r.Ma_hang }}</td>
      <td>{{ r.Ten_hang }}</td>

      <td
        v-for="maHD in compareMaHopDongs"
        :key="maHD"
        class="right"
        :style="{
          color: r.byHD[maHD]?.diff >= 0 ? 'green' : 'red'
        }"
      >
        <template v-if="r.byHD[maHD]">
          {{ formatVND(r.byHD[maHD].diff) }}
          <span class="muted">
            ({{ r.byHD[maHD].pct.toFixed(2) }}%)
          </span>
        </template>
        <template v-else>—</template>
      </td>
    </tr>
  </tbody>
</table>


    <div class="modal-actions">
      <button class="primary" @click="showCompareModal = false">Đóng</button>
    </div>
  </div>
</div>

    <!-- ================== MODAL: CHỌN KIỂU LƯU HỢP ĐỒNG (FULLSCREEN) ================== -->
    <div v-if="showSaveModal || showExportSaveConfirmModal" class="modal vip-modal-overlay modal-fullscreen-overlay" style="z-index: 10005;" @click.self="showSaveModal = false; showExportSaveConfirmModal = false; pendingExportFormat = null">
      <div class="modal-card modal-wide vip-modal-card modal-fullscreen-card save-export-cust-modal">
        <div class="modal-head modal-head-themed" style="justify-content: center; position: relative; padding: 14px 24px; border-bottom: none; border-radius: 0; flex-shrink: 0;">
          <div class="save-modal-head-title" style="color: #fff; text-transform: uppercase; font-weight: 900; font-size: 16px; letter-spacing: 0.5px;">
            {{ showExportSaveConfirmModal ? 'BẠN CÓ MUỐN LƯU BÁO GIÁ KHÔNG ? — THÔNG TIN KHÁCH HÀNG & LƯU BÁO GIÁ' : 'CHỌN KHÁCH HÀNG • LƯU & XUẤT BÁO GIÁ' }}
          </div>
          <button class="x" @click="showSaveModal = false; showExportSaveConfirmModal = false; pendingExportFormat = null" style="color: #fff; position: absolute; right: 18px; top: 50%; transform: translateY(-50%); background: rgba(0,0,0,0.15); border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border: none; cursor: pointer;">✕</button>
        </div>

        <!-- TOP QUICK ACTION TOOLBAR -->
        <div class="cust-top-toolbar" style="padding: 12px 32px; border-bottom: 1px solid rgba(148,163,184,0.16); background: rgba(15,23,42,0.35); display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; flex-shrink: 0;">
          <div class="cust-toolbar-status-row" style="display: flex; align-items: center; gap: 10px; flex-wrap: wrap;">
            <span
              class="cust-db-badge"
              :style="{
                padding: '5px 12px',
                borderRadius: '999px',
                fontSize: '11px',
                fontWeight: '800',
                letterSpacing: '0.5px',
                textTransform: 'uppercase',
                background: isCustomerInDB ? 'rgba(16,185,129,0.16)' : 'rgba(245,158,11,0.16)',
                color: isCustomerInDB ? '#10b981' : '#f59e0b',
                border: isCustomerInDB ? '1px solid rgba(16,185,129,0.4)' : '1px solid rgba(245,158,11,0.4)'
              }"
            >
              {{ isCustomerInDB ? 'ĐÃ CÓ TRONG DB' : 'KHÁCH HÀNG MỚI' }}
            </span>
            <span v-if="maKHInput || khach.Ma_khach_hang" class="cust-meta-chip" style="font-size: 12px; font-weight: 700; opacity: 0.85;">
              Mã KH: <strong style="color: #38bdf8;">{{ maKHInput || khach.Ma_khach_hang }}</strong>
            </span>
            <span v-if="khach.Ma_cong_ty || khach.Ten_cong_ty" class="cust-meta-chip" style="font-size: 12px; font-weight: 700; opacity: 0.85;">
              • Mã CT: <strong style="color: #34d399;">{{ khach.Ma_cong_ty || genMaCT(khach.Ten_cong_ty) }}</strong>
            </span>
            <span class="cust-last-updated-inline" style="font-size: 12px; font-weight: 700; opacity: 0.9; display: inline-flex; align-items: center; gap: 4px;">
              • Cập nhật cuối: <strong style="color: #0284c7;">{{ formatLastUpdated(getCustomerLastUpdated(khach)) }}</strong>
            </span>

            <!-- Nút Lưu DB & Reset nhỏ gọn nằm cùng hàng trạng thái trên Mobile -->
            <div class="cust-mobile-mini-actions">
              <button v-if="showSaveToDBBtn" type="button" class="cust-mini-btn save-db" @click="saveCustomerToDB(false)" :disabled="savingCustomer">
                {{ savingCustomer ? '...' : (isCustomerInDB ? 'Lưu DB' : '+ DB') }}
              </button>
              <button type="button" class="cust-mini-btn reset" @click="resetCustomer" title="Xóa trắng thông tin khách hàng">
                Reset
              </button>
            </div>
          </div>

          <div class="cust-toolbar-import-row" style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <button type="button" class="cust-import-btn dxmh" @click="triggerCustomerFileInput" style="padding: 7px 12px; border-radius: 7px; font-size: 11px; font-weight: 800; text-transform: uppercase; background: #2563eb; color: #ffffff; border: none; cursor: pointer; white-space: nowrap; width: fit-content; flex-shrink: 0; line-height: 1; display: inline-flex; align-items: center; gap: 5px; box-shadow: 0 2px 6px rgba(37,99,235,0.3); margin: 0;">
              <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="17 8 12 3 7 8"></polyline><line x1="12" y1="3" x2="12" y2="15"></line></svg>
              <span class="dt-lbl">Import khách hàng (File DXMH)</span>
              <span class="mb-lbl">File DXMH</span>
            </button>
            <button type="button" class="cust-import-btn bg" @click="triggerCustomerQuoteFileInput" style="padding: 7px 12px; border-radius: 7px; font-size: 11px; font-weight: 800; text-transform: uppercase; background: #7c3aed; color: #ffffff; border: none; cursor: pointer; white-space: nowrap; width: fit-content; flex-shrink: 0; line-height: 1; display: inline-flex; align-items: center; gap: 5px; box-shadow: 0 2px 6px rgba(124,58,237,0.3); margin: 0;">
              <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg>
              <span class="dt-lbl">Import khách hàng (File Báo Giá)</span>
              <span class="mb-lbl">File Báo Giá</span>
            </button>
            <button type="button" class="cust-import-btn tax" @click="showUploadTaxModal = true" style="padding: 7px 12px; border-radius: 7px; font-size: 11px; font-weight: 800; text-transform: uppercase; background: #0ea5e9; color: #ffffff; border: none; cursor: pointer; white-space: nowrap; width: fit-content; flex-shrink: 0; line-height: 1; display: inline-flex; align-items: center; gap: 5px; box-shadow: 0 2px 6px rgba(14,165,233,0.3); margin: 0;">
              <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><circle cx="8.5" cy="8.5" r="1.5"></circle><polyline points="21 15 16 10 5 21"></polyline></svg>
              <span class="dt-lbl">Import Ảnh Thuế</span>
              <span class="mb-lbl">Ảnh Thuế</span>
            </button>
            <button v-if="showSaveToDBBtn" type="button" class="cust-dt-only-btn" @click="saveCustomerToDB(false)" :disabled="savingCustomer" style="padding: 7px 12px; border-radius: 7px; font-size: 11px; font-weight: 800; text-transform: uppercase; background: #10b981; color: #ffffff; border: none; cursor: pointer; white-space: nowrap; width: fit-content; flex-shrink: 0; line-height: 1; box-shadow: 0 2px 6px rgba(16,185,129,0.3); margin: 0;">
              {{ savingCustomer ? 'Đang lưu...' : (isCustomerInDB ? 'Lưu khách hàng' : 'Thêm vào DB') }}
            </button>
            <button type="button" class="cust-dt-only-btn" @click="resetCustomer" style="padding: 7px 12px; border-radius: 7px; font-size: 11px; font-weight: 800; text-transform: uppercase; background: #ef4444; color: #ffffff; border: none; cursor: pointer; white-space: nowrap; width: fit-content; flex-shrink: 0; line-height: 1; box-shadow: 0 2px 6px rgba(239,68,68,0.3); margin: 0;">
              Reset
            </button>
          </div>
        </div>

        <div class="save-modal-body-scroll" style="padding: 20px 32px; overflow-y: auto; flex: 1; display: flex; flex-direction: column; gap: 18px;">
          <div class="save-modal-top-grid" style="display: grid; grid-template-columns: 1fr 1.15fr; gap: 20px; align-items: stretch; flex: 1;">
            <!-- LEFT COLUMN: NGƯỜI LIÊN HỆ CHÍNH + KHÁCH HÀNG PHỤ -->
            <div style="display: flex; flex-direction: column; gap: 16px; height: 100%;">
              <!-- 1. NGƯỜI LIÊN HỆ CHÍNH -->
              <div class="cust-group-box cust-group-main" style="background: rgba(16,185,129,0.04); border: 1px solid rgba(16,185,129,0.14); border-radius: 10px; padding: 20px 22px; display: flex; flex-direction: column; justify-content: space-between; gap: 14px; flex: 1;">
                <div style="font-size: 12px; text-transform: uppercase; font-weight: 800; color: #10b981; letter-spacing: 0.8px;">THÔNG TIN NGƯỜI LIÊN HỆ CHÍNH</div>
                <div style="display: grid; grid-template-columns: 1fr 1.4fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Mã KH</label>
                    <div class="input-with-picker">
                      <input v-model="maKHInput" placeholder="Tự động tạo hoặc nhập Mã KH" @change="fillCustomerByMa(maKHInput)" @blur="onBlurMaKH" style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;" />
                      <button type="button" class="inline-picker-btn" @click="openCustomerPicker('ma_kh')">Chọn</button>
                    </div>
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Tên người liên hệ</label>
                    <div class="input-with-picker">
                      <input v-model="tenKHInput" placeholder="Tên người liên hệ" @change="fillCustomerByTen(tenKHInput)" @blur="onBlurTenKH" style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;" />
                      <button type="button" class="inline-picker-btn" @click="openCustomerPicker('ten_kh')">Chọn</button>
                    </div>
                  </div>
                </div>
                <div style="display: grid; grid-template-columns: 1fr 1.4fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">SĐT cá nhân</label>
                    <input v-model="khach.So_dien_thoai_ca_nhan" placeholder="Số điện thoại liên hệ" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Email cá nhân</label>
                    <input v-model="khach.Email_ca_nhan" placeholder="Email cá nhân" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                </div>
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Ghi chú khách hàng</label>
                  <input v-model="khach.Ghi_chu" placeholder="Ghi chú thêm về khách hàng..." style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                </div>
              </div>

              <!-- NÚT MỞ RỘNG MỤC PHỤ TRÊN MOBILE -->
              <button
                type="button"
                class="mobile-cust-accordion-btn"
                @click="showMobileCustSubSection = !showMobileCustSubSection"
              >
                <span>Khách hàng phụ &amp; Đơn hàng PO (Tiếng Anh)</span>
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" :style="{ transform: showMobileCustSubSection ? 'rotate(180deg)' : 'rotate(0deg)', transition: 'transform 0.2s ease' }">
                  <polyline points="6 9 12 15 18 9"></polyline>
                </svg>
              </button>

              <!-- 2. KHÁCH HÀNG PHỤ (NGƯỜI NHẬN HÀNG) -->
              <div class="cust-group-box cust-group-sub cust-collapsible-sub" :class="{ 'is-mobile-open': showMobileCustSubSection }" style="background: rgba(148,163,184,0.04); border: 1px solid rgba(148,163,184,0.14); border-radius: 10px; padding: 18px 22px; display: flex; flex-direction: column; justify-content: space-between; gap: 12px;">
                <div class="cust-group-title-sub" style="font-size: 11px; text-transform: uppercase; font-weight: 800; color: #ffffff; letter-spacing: 0.8px;">KHÁCH HÀNG PHỤ (NGƯỜI NHẬN HÀNG)</div>
                <div style="display: grid; grid-template-columns: 1.1fr 0.9fr 1.2fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Tên KH phụ</label>
                    <input v-model="khach.Ten_khach_hang_phu" placeholder="Tên người nhận phụ" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">SĐT phụ</label>
                    <input v-model="khach.So_dien_thoai_ca_nhan_phu" placeholder="SĐT phụ" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Email phụ</label>
                    <input v-model="khach.Email_ca_nhan_phu" placeholder="Email phụ" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                </div>
              </div>
            </div>

            <!-- RIGHT COLUMN: THÔNG TIN CÔNG TY + PO TIẾNG ANH -->
            <div style="display: flex; flex-direction: column; gap: 16px; height: 100%;">
              <!-- 1. THÔNG TIN CÔNG TY & THUẾ -->
              <div class="cust-group-box cust-group-company" style="background: rgba(56,189,248,0.04); border: 1px solid rgba(56,189,248,0.14); border-radius: 10px; padding: 20px 22px; display: flex; flex-direction: column; justify-content: space-between; gap: 14px; flex: 1;">
                <div style="font-size: 12px; text-transform: uppercase; font-weight: 800; color: #0284c7; letter-spacing: 0.8px;">THÔNG TIN CÔNG TY &amp; PHÁP LÝ</div>
                <div style="display: grid; grid-template-columns: 2.2fr 1fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Tên công ty</label>
                    <div class="input-with-picker">
                      <input v-model="khach.Ten_cong_ty" placeholder="Tên công ty đầy đủ" @change="fillCustomerByCongTy(khach.Ten_cong_ty)" @blur="onBlurCongTy" style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;" />
                      <button type="button" class="inline-picker-btn" @click="openCustomerPicker('ten_cong_ty')">Chọn</button>
                    </div>
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Mã số thuế (MST)</label>
                    <div class="input-with-picker">
                      <input v-model="khach.MST" @change="onMSTChange" placeholder="Mã số thuế" style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;" />
                      <button type="button" class="inline-picker-btn" @click="openCustomerPicker('mst')">Chọn</button>
                    </div>
                  </div>
                </div>
                <div style="display: grid; grid-template-columns: 2.2fr 1fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Địa chỉ xuất hóa đơn</label>
                    <input v-model="khach.Dia_chi_cong_ty" placeholder="Địa chỉ trụ sở / xuất hóa đơn" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Website</label>
                    <input v-model="khach.Website_cong_ty" placeholder="Website công ty" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                </div>
                <div style="display: grid; grid-template-columns: 1fr 1.2fr 1.2fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">SĐT công ty</label>
                    <input v-model="khach.So_dien_thoai_cong_ty" placeholder="SĐT bàn / công ty" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Email công ty / nhận HĐ</label>
                    <input v-model="khach.Email_cong_ty" placeholder="Email nhận hóa đơn" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Ngành nghề kinh doanh</label>
                    <input v-model="khach.Nganh_nghe_cong_ty" placeholder="Ngành nghề chính" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                </div>
              </div>

              <!-- 2. THÔNG TIN GIAO DỊCH PO / TIẾNG ANH -->
              <div class="cust-group-box cust-group-sub cust-collapsible-sub" :class="{ 'is-mobile-open': showMobileCustSubSection }" style="background: rgba(148,163,184,0.04); border: 1px solid rgba(148,163,184,0.14); border-radius: 10px; padding: 18px 22px; display: flex; flex-direction: column; justify-content: space-between; gap: 12px;">
                <div class="cust-group-title-sub" style="font-size: 11px; text-transform: uppercase; font-weight: 800; color: #ffffff; letter-spacing: 0.8px;">THÔNG TIN ĐƠN HÀNG PO / TIẾNG ANH (COMPANY • ADDRESS • TEL • FAX)</div>
                <div style="display: grid; grid-template-columns: 1.5fr 0.8fr 0.8fr 1.8fr; gap: 12px;">
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">COMPANY</label>
                    <input v-model="khach.COMPANY" placeholder="Tên công ty trên PO" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">TEL</label>
                    <input v-model="khach.TEL" placeholder="TEL" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">Fax</label>
                    <input v-model="khach.So_fax_cong_ty" placeholder="Số Fax" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                  <div style="display: flex; flex-direction: column; gap: 5px;">
                    <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600;">ADDRESS</label>
                    <input v-model="khach.ADDRESS" placeholder="Địa chỉ Tiếng Anh trên PO" style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- NÚT MỞ RỘNG CÔNG NỢ & GHI CHÚ HỢP ĐỒNG TRÊN MOBILE -->
          <button
            type="button"
            class="mobile-cust-accordion-btn"
            @click="showMobileCustDebtSection = !showMobileCustDebtSection"
          >
            <span>Công nợ KH ({{ formatVND(getCustomerDebtSummary(khach).congNo) || '0' }} đ) &amp; Ghi chú HĐ</span>
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" :style="{ transform: showMobileCustDebtSection ? 'rotate(180deg)' : 'rotate(0deg)', transition: 'transform 0.2s ease' }">
              <polyline points="6 9 12 15 18 9"></polyline>
            </svg>
          </button>

          <!-- BOTTOM FULL-WIDTH: CÔNG NỢ + CONTENT OF CONTRACT / PO -->
          <div class="save-modal-bottom-grid cust-collapsible-debt" :class="{ 'is-mobile-open': showMobileCustDebtSection }" style="display: grid; grid-template-columns: 1.15fr 1fr; gap: 20px; align-items: stretch;">
            <!-- CÔNG NỢ & TIẾN ĐỘ TRẢ NỢ -->
            <div class="cust-group-box cust-debt-box" style="padding: 16px 22px; background: rgba(15, 23, 42, 0.55); border: 1px solid rgba(56, 189, 248, 0.28); border-radius: 10px; display: flex; flex-direction: column; justify-content: space-between; gap: 10px;">
              <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;">
                <div>
                  <div style="font-size: 11px; font-weight: 800; text-transform: uppercase; color: #0284c7; letter-spacing: 0.6px; margin-bottom: 3px;">Công Nợ Hiện Tại Của Khách Hàng</div>
                  <div
                    style="font-size: 20px; font-weight: 900;"
                    :style="{ color: getCustomerDebtSummary(khach).congNo > 0 ? '#ef4444' : '#10b981' }"
                  >
                    {{ formatVND(getCustomerDebtSummary(khach).congNo) || '0' }} đ
                  </div>
                </div>
                <button
                  type="button"
                  @click="openCustomerDebtModal(khach)"
                  style="background: linear-gradient(135deg, rgba(16, 185, 129, 0.18), rgba(56, 189, 248, 0.22)); color: #0284c7; border: 1px solid rgba(56, 189, 248, 0.45); border-radius: 8px; padding: 9px 14px; font-size: 12px; font-weight: 800; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; width: fit-content; transition: all 0.2s;"
                  class="cust-debt-btn"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg>
                  <span>Xem Tiến Độ Trả Nợ &amp; Lịch Sử TT ({{ getCustomerPaymentHistoryCount(khach) }})</span>
                </button>
              </div>
              <div>
                <div style="display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 6px; flex-wrap: wrap; gap: 6px;">
                  <span>Đã thanh toán: <strong style="color: #10b981;">{{ formatVND(getCustomerDebtSummary(khach).daThanhToan) || '0' }} đ</strong></span>
                  <span>Tổng phải thu ({{ getCustomerDebtSummary(khach).poCount }} PO): <strong style="color: #0284c7;">{{ formatVND(getCustomerDebtSummary(khach).tongSauVat) || '0' }} đ</strong> ({{ getCustomerDebtSummary(khach).progressPct }}%)</span>
                </div>
                <div style="width: 100%; height: 8px; background: rgba(148, 163, 184, 0.25); border-radius: 999px; overflow: hidden;">
                  <div
                    :style="{
                      width: getCustomerDebtSummary(khach).progressPct + '%',
                      height: '100%',
                      background: getCustomerDebtSummary(khach).congNo <= 0 ? '#10b981' : 'linear-gradient(90deg, #38bdf8, #10b981)',
                      borderRadius: '999px',
                      transition: 'width 0.3s ease'
                    }"
                  ></div>
                </div>
              </div>
            </div>

            <!-- CONTENT OF CONTRACT / PO, GHI CHÚ HỢP ĐỒNG & TÊN FILE XUẤT -->
            <div class="cust-group-box cust-group-sub" style="background: rgba(148,163,184,0.04); border: 1px solid rgba(148,163,184,0.14); border-radius: 10px; padding: 16px 22px; display: flex; flex-direction: column; justify-content: space-between; gap: 10px;">
              <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #d97706; font-weight: 700;">Content of Contract / PO (tùy chọn)</label>
                  <input v-model="contentOfContractPO" placeholder="Nhập nội dung Contract/PO (nếu có)..." style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                </div>
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 700;">Ghi chú hợp đồng</label>
                  <input v-model="ghiChuHopDong" placeholder="Nhập ghi chú hợp đồng (nếu có)..." style="padding: 10px 12px; border-radius: 8px; font-size: 13px;" />
                </div>
              </div>
              <div style="padding: 10px 12px; border-radius: 8px; background: rgba(16,185,129,0.1); border: 1px dashed rgba(16,185,129,0.45); font-size: 12px;">
                Tên file xuất: <b style="color: #10b981; word-break: break-all;">{{ exportFileNamePreview }}.xlsx</b>
              </div>
            </div>
          </div>
        </div>
        <!-- ACTIONS -->
        <div v-if="showExportSaveConfirmModal" class="save-modal-actions cust-modal-footer fullscreen-modal-footer" style="padding: 16px 32px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: grid; grid-template-columns: 1fr 1fr 0.6fr; gap: 12px; flex-shrink: 0; border-radius: 0 !important;">
          <button @click="handleExportSaveConfirmChoice('temp')" style="padding: 12px 20px; border-radius: 8px; font-weight: 700; font-size: 14px; color: #fff; background: linear-gradient(135deg, #3b82f6, #2563eb); border: none; cursor: pointer; transition: all 0.25s; letter-spacing: 0.3px; box-shadow: 0 2px 8px rgba(59,130,246,0.25);" onmouseover="this.style.boxShadow='0 4px 16px rgba(59,130,246,0.4)'; this.style.transform='translateY(-1px)'" onmouseout="this.style.boxShadow='0 2px 8px rgba(59,130,246,0.25)'; this.style.transform='translateY(0)'">Lưu tạm & chờ duyệt</button>
          <button @click="handleExportSaveConfirmChoice('official')" style="padding: 12px 20px; border-radius: 8px; font-weight: 800; font-size: 14px; text-transform: uppercase; color: #fff; background: linear-gradient(135deg, #10b981, #059669); border: none; cursor: pointer; transition: all 0.25s; letter-spacing: 0.5px; box-shadow: 0 2px 8px rgba(16,185,129,0.28);" onmouseover="this.style.boxShadow='0 4px 16px rgba(16,185,129,0.45)'; this.style.transform='translateY(-1px)'" onmouseout="this.style.boxShadow='0 2px 8px rgba(16,185,129,0.28)'; this.style.transform='translateY(0)'">CHỐT DEAL & CẬP NHẬT SALE REPORT</button>
          <button class="modal-btn-secondary" @click="handleExportSaveConfirmChoice('cancel')" style="padding: 12px 20px; border-radius: 8px; font-weight: 700; font-size: 14px; color: #f8fafc; background: #334155; border: 1px solid rgba(255,255,255,0.15); cursor: pointer; transition: all 0.25s; letter-spacing: 0.3px;">Hủy (Chỉ xuất file)</button>
        </div>
        <div v-else class="save-modal-actions save-modal-actions-3btn cust-modal-footer fullscreen-modal-footer" style="padding: 16px 32px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: grid; grid-template-columns: 1fr 1.15fr 1fr; gap: 12px; flex-shrink: 0; border-radius: 0 !important;">
          <button class="btn-save-temp" @click="() => { showSaveModal = false; saveContractTemp(); }" style="padding: 12px 16px; border-radius: 8px; font-weight: 700; font-size: 13.5px; color: #fff; background: linear-gradient(135deg, #3b82f6, #2563eb); border: none; cursor: pointer; transition: all 0.25s; letter-spacing: 0.3px; box-shadow: 0 2px 8px rgba(59,130,246,0.25); display: inline-flex; align-items: center; justify-content: center; gap: 6px;">
            <i class="lucide-save" style="font-size: 14px;"></i>
            <span>Lưu tạm &amp; chờ duyệt</span>
          </button>
          <button class="btn-save-deal" @click="() => { showSaveModal = false; saveContractOfficialAndSaleReport(); }" style="padding: 12px 16px; border-radius: 8px; font-weight: 800; font-size: 13.5px; text-transform: uppercase; color: #fff; background: linear-gradient(135deg, #10b981, #059669); border: none; cursor: pointer; transition: all 0.25s; letter-spacing: 0.4px; box-shadow: 0 2px 8px rgba(16,185,129,0.28); display: inline-flex; align-items: center; justify-content: center; gap: 6px;">
            <i class="lucide-check-circle" style="font-size: 14px;"></i>
            <span>CHỐT DEAL &amp; SALE REPORT</span>
          </button>
          <button class="btn-save-export" @click="() => { showSaveModal = false; showExportInfoModal = true; }" style="padding: 12px 16px; border-radius: 8px; font-weight: 800; font-size: 13.5px; text-transform: uppercase; color: #fff; background: linear-gradient(135deg, #0ea5e9, #0284c7); border: none; cursor: pointer; transition: all 0.25s; letter-spacing: 0.4px; box-shadow: 0 2px 8px rgba(14,165,233,0.28); display: inline-flex; align-items: center; justify-content: center; gap: 6px;">
            <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="6 9 6 2 18 2 18 9"></polyline>
              <path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path>
              <rect x="6" y="14" width="12" height="8"></rect>
            </svg>
            <span>XUẤT &amp; IN BÁO GIÁ</span>
          </button>
        </div>
      </div>
    </div>

    <!-- ================== MODAL: CHỌN MẪU IN & XUẤT BÁO GIÁ ĐA ĐỊNH DẠNG ================== -->
    <div v-if="showExportExcelModal" class="modal vip-modal-overlay modal-fullscreen-overlay" @click.self="showExportExcelModal = false">
      <div class="modal-card modal-wide vip-modal-card modal-fullscreen-card export-multi-format-modal">
        <div class="modal-head modal-head-themed export-multi-head" style="justify-content: center; position: relative; margin-bottom: 0; padding: 14px 24px; border-bottom: none; border-radius: 0; flex-shrink: 0;">
          <div class="export-multi-head-title" style="color: #ffffff; text-transform: uppercase; font-weight: 900; font-size: 16px; letter-spacing: 0.5px; display: flex; align-items: center; gap: 8px;">
            <i class="lucide-file-spreadsheet"></i>
            <span class="dt-lbl">CHỌN MẪU IN, KHÁCH HÀNG &amp; XUẤT BÁO GIÁ</span>
            <span class="mb-lbl">CHỌN MẪU IN &amp; XUẤT BÁO GIÁ</span>
          </div>
          <button class="x" @click="showExportExcelModal = false" style="color: #fff; position: absolute; right: 18px; top: 50%; transform: translateY(-50%); background: rgba(0,0,0,0.15); border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border: none; cursor: pointer;">✕</button>
        </div>

        <!-- TOP QUICK ACTION TOOLBAR -->
        <div class="cust-top-toolbar export-multi-top-toolbar" style="padding: 12px 32px; border-bottom: 1px solid rgba(148,163,184,0.16); background: rgba(15,23,42,0.35); display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; flex-shrink: 0;">
          <div class="export-multi-tpl-left" style="display: flex; align-items: center; gap: 12px; flex: 1; min-width: 320px; flex-wrap: wrap;">
            <div class="export-multi-tpl-head-row">
              <span class="export-multi-tpl-label" style="font-size: 12px; font-weight: 800; text-transform: uppercase; color: #10b981; white-space: nowrap; letter-spacing: 0.4px;">Mẫu in áp dụng:</span>
              <button
                type="button"
                class="export-multi-setup-mobile-btn"
                @click="showExportExcelModal = false; router.push('/mau-in-firebase')"
              >
                + Tạo / Sửa mẫu
              </button>
            </div>
            <select
              v-model="selectedPrintTemplateId"
              class="export-multi-tpl-select"
              style="min-width: 260px; max-width: 420px; padding: 8px 12px; border-radius: 8px; border: 1px solid rgba(16, 185, 129, 0.5); font-weight: 700; font-size: 13px; cursor: pointer; margin: 0;"
            >
              <option v-for="pt in printTemplates" :key="pt.id" :value="pt.id">
                {{ pt.mac_dinh ? '[Mặc định] ' : '' }}{{ pt.ten_mau }} ({{ pt.cau_hinh_trang?.kho_giay || 'A4' }} - {{ pt.cau_hinh_trang?.huong_giay === 'portrait' ? 'Dọc' : 'Ngang' }})
              </option>
            </select>
            <span class="export-multi-filename-note" style="font-size: 12px; font-weight: 700; opacity: 0.9; display: inline-flex; align-items: center; gap: 5px;">
              • Tên file xuất: <strong style="color: #0284c7; word-break: break-all;">{{ exportFileNamePreview }}{{ currentPreviewFormatInfo.badge }}</strong>
            </span>
          </div>

          <div class="export-multi-dt-btns" style="display: flex; gap: 8px; align-items: center; flex-wrap: wrap;">
            <button
              type="button"
              @click="showPrintPreviewInModal = !showPrintPreviewInModal"
              style="padding: 8px 14px; border-radius: 7px; border: none; background: #0284c7; color: #ffffff; font-weight: 800; font-size: 11.5px; text-transform: uppercase; cursor: pointer; width: fit-content; margin: 0; box-shadow: 0 2px 6px rgba(2,132,199,0.28);"
            >
              {{ showPrintPreviewInModal ? 'Ẩn xem trước mẫu in' : 'Hiện xem trước mẫu in' }}
            </button>
            <button
              type="button"
              @click="showExportExcelModal = false; router.push('/mau-in-firebase')"
              style="padding: 8px 14px; border-radius: 7px; border: none; background: #2563eb; color: #ffffff; font-weight: 800; font-size: 11.5px; text-transform: uppercase; cursor: pointer; width: fit-content; margin: 0; box-shadow: 0 2px 6px rgba(37,99,235,0.28);"
            >
              Thiết lập / Tạo mẫu in
            </button>
          </div>

          <!-- THANH CHUYỂN 2 TAB TRÊN MOBILE (THÔNG TIN & ĐIỀU KHOẢN | XEM TRƯỚC BẢN IN) -->
          <div class="export-multi-mobile-tabs">
            <button
              type="button"
              class="export-multi-mob-tab"
              :class="{ active: mobileExportModalTab === 'info' }"
              @click="mobileExportModalTab = 'info'"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
              <span>Thông tin &amp; Điều khoản</span>
            </button>
            <button
              type="button"
              class="export-multi-mob-tab"
              :class="{ active: mobileExportModalTab === 'preview' }"
              @click="showPrintPreviewInModal = true; mobileExportModalTab = 'preview'"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg>
              <span>Xem trước &amp; Sửa bản in</span>
            </button>
          </div>
        </div>

        <!-- MAIN 2-COLUMN WORKSPACE (HỖ TRỢ KÉO ĐỘ RỘNG KHUNG TRÁI / PHẢI) -->
        <div
          class="export-preview-split-workspace"
          :class="['mob-tab-' + mobileExportModalTab]"
          style="padding: 16px 24px; overflow-y: auto; flex: 1; min-height: 0; display: grid; align-items: stretch;"
          :style="{
            gridTemplateColumns: showPrintPreviewInModal
              ? `minmax(340px, ${previewSplitLeftPct}fr) 12px minmax(480px, ${100 - previewSplitLeftPct}fr)`
              : '1fr',
            gap: showPrintPreviewInModal ? '0px' : '20px'
          }"
        >
          <!-- LEFT COLUMN: THÔNG TIN KHÁCH HÀNG & ĐIỀU KHOẢN THƯƠNG MẠI -->
          <div class="export-multi-left-col" style="display: flex; flex-direction: column; gap: 14px; min-height: 0; min-width: 0; padding-right: 4px;">
            <!-- THẺ 1: THÔNG TIN KHÁCH HÀNG & HỢP ĐỒNG TRÊN BẢN IN -->
            <div class="cust-group-box cust-group-company" style="background: rgba(56,189,248,0.04); border: 1px solid rgba(56,189,248,0.14); border-radius: 10px; padding: 16px 20px; display: flex; flex-direction: column; gap: 12px;">
              <div style="font-size: 12px; text-transform: uppercase; font-weight: 800; color: #0284c7; letter-spacing: 0.8px;">THÔNG TIN KHÁCH HÀNG &amp; ĐƠN HÀNG TRÊN BẢN IN</div>

              <div style="display: grid; grid-template-columns: 1fr 1.4fr; gap: 12px;">
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Mã khách hàng</label>
                  <div class="input-with-picker">
                    <input
                      v-model="maKHInput"
                      placeholder="Chọn / nhập mã KH"
                      @change="fillCustomerByMa(maKHInput)"
                      @blur="onBlurMaKH"
                      style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;"
                    />
                    <button type="button" class="inline-picker-btn" @click="openCustomerPicker('ma_kh')">Chọn</button>
                  </div>
                </div>
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Người nhận (Tên khách hàng)</label>
                  <div class="input-with-picker">
                    <input
                      v-model="tenKHInput"
                      placeholder="Chọn / nhập tên người nhận"
                      @change="fillCustomerByTen(tenKHInput)"
                      @blur="onBlurTenKH"
                      style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;"
                    />
                    <button type="button" class="inline-picker-btn" @click="openCustomerPicker('ten_kh')">Chọn</button>
                  </div>
                </div>
              </div>

              <div style="display: grid; grid-template-columns: 1.2fr 1.2fr; gap: 12px;">
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Kính gởi (Tên công ty)</label>
                  <div class="input-with-picker">
                    <input
                      v-model="khach.Ten_cong_ty"
                      placeholder="Chọn / nhập tên công ty"
                      @change="fillCustomerByCongTy(khach.Ten_cong_ty)"
                      @blur="onBlurCongTy"
                      style="width: 100%; padding: 10px 60px 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;"
                    />
                    <button type="button" class="inline-picker-btn" @click="openCustomerPicker('ten_cong_ty')">Chọn</button>
                  </div>
                </div>
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Địa chỉ hiển thị trên báo giá</label>
                  <input
                    v-model="khach.Dia_chi_cong_ty"
                    placeholder="Địa chỉ công ty..."
                    style="padding: 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;"
                  />
                </div>
              </div>

              <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Content of Contract / PO (nếu có)</label>
                  <input
                    v-model="contentOfContractPO"
                    placeholder="Nhập nội dung Contract/PO..."
                    style="padding: 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;"
                  />
                </div>
                <div style="display: flex; flex-direction: column; gap: 5px;">
                  <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Ghi chú hợp đồng</label>
                  <input
                    v-model="ghiChuHopDong"
                    placeholder="Nhập ghi chú hợp đồng..."
                    style="padding: 10px 12px; border-radius: 8px; font-size: 13px; margin: 0;"
                  />
                </div>
              </div>
            </div>

            <!-- THẺ 2: ĐIỀU KHOẢN THƯƠNG MẠI -->
            <div class="cust-group-box cust-group-main" style="background: rgba(16,185,129,0.04); border: 1px solid rgba(16,185,129,0.14); border-radius: 10px; padding: 16px 20px; display: flex; flex-direction: column; gap: 12px; flex: 1; min-height: 240px;">
              <div style="display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap;">
                <div style="font-size: 12px; text-transform: uppercase; font-weight: 800; color: #10b981; letter-spacing: 0.8px;">ĐIỀU KHOẢN THƯƠNG MẠI (TERMS &amp; CONDITIONS)</div>
              </div>

              <div style="display: flex; flex-direction: column; gap: 5px;">
                <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Chọn mẫu điều khoản</label>
                <select v-model="selectedTermId" style="width: 100%; padding: 10px 12px; border-radius: 8px; font-size: 13px; font-weight: 600; margin: 0; cursor: pointer;">
                  <option value="">-- Không chèn điều khoản (chỉ giữ tiêu đề) --</option>
                  <option value="custom_import" v-if="importedTermsHtml">-- Điều khoản từ file Import --</option>
                  <option v-for="t in contractTerms" :key="t.id" :value="t.id">
                    {{ t.mau ? `[${t.mau}] ${t.tenCT || t.tenKH || 'Mẫu chung'}` : (t.tenCT || t.tenKH || 'Điều khoản chưa đặt tên') }}
                  </option>
                </select>
              </div>

              <div v-if="selectedTermId" style="flex: 1; display: flex; flex-direction: column; gap: 6px; min-height: 0;">
                <label style="font-size: 10px; text-transform: uppercase; color: #ffffff; font-weight: 600; margin: 0;">Chỉnh sửa nội dung điều khoản (chỉ cho báo giá này)</label>
                <ExcelEditor ref="previewEditor" v-model="editableTermContent" class="preview-editor" style="flex: 1;" />
              </div>
              <div v-else style="flex: 1; display: flex; align-items: center; justify-content: center; border: 1px dashed rgba(148,163,184,0.3); border-radius: 8px; padding: 20px; text-align: center; font-size: 12.5px; color: #64748b;">
                Chọn một mẫu Điều khoản thương mại ở trên nếu bạn muốn đính kèm và chỉnh sửa điều khoản cho bản xuất này.
              </div>
            </div>
          </div>

          <!-- THANH KÉO CHIA ĐỘ RỘNG TRÁI / PHẢI -->
          <div
            v-if="showPrintPreviewInModal"
            class="preview-split-resizer"
            :class="{ 'is-dragging': isResizingPreviewSplit }"
            title="Giữ chuột kéo sang trái/phải để mở rộng vùng Xem trước &amp; Chỉnh sửa bản in"
            @mousedown="startPreviewSplitResize"
          >
            <div class="preview-split-resizer-grip"></div>
          </div>

          <!-- RIGHT COLUMN: KHUNG XEM TRƯỚC BẢN IN THEO ĐỊNH DẠNG & CHỈNH SỬA TRỰC TIẾP -->
          <div
            v-if="showPrintPreviewInModal"
            class="cust-group-box cust-group-sub preview-live-panel export-multi-right-col"
            style="background: rgba(148,163,184,0.04); border: 1px solid rgba(148,163,184,0.14); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; min-height: 0; min-width: 0; overflow: hidden;"
          >
            <!-- THANH 1: 5 TAB ĐỊNH DẠNG XEM TRƯỚC + NÚT SỬA TRỰC TIẾP + PHÓNG TO -->
            <div class="pv-topbar-unified">
              <div class="pv-format-tabs-list">
                <button
                  v-for="ft in previewFormatTabs"
                  :key="ft.id"
                  type="button"
                  class="pv-format-tab-btn"
                  :class="[`fmt-${ft.id}`, { active: previewFormatMode === ft.id }]"
                  :title="ft.desc"
                  @click="previewFormatMode = ft.id"
                >
                  <span class="pv-fmt-name">{{ ft.label }}</span>
                  <span class="pv-fmt-ext">{{ ft.badge }}</span>
                </button>
              </div>

              <div class="pv-topbar-actions">
                <button
                  type="button"
                  class="pv-mode-toggle-btn"
                  :class="{ active: isPreviewDirectEditMode }"
                  @click="isPreviewDirectEditMode = !isPreviewDirectEditMode"
                  title="Bật/Tắt chế độ click vào ô bất kỳ để sửa nội dung và kéo rộng cột / cao dòng"
                >
                  <span class="dt-lbl">{{ isPreviewDirectEditMode ? 'Sửa trực tiếp: BẬT' : 'Sửa trực tiếp: TẮT' }}</span>
                  <span class="mb-lbl">{{ isPreviewDirectEditMode ? 'Sửa: BẬT' : 'Sửa: TẮT' }}</span>
                </button>
                <button
                  v-if="previewOverrideCount > 0"
                  type="button"
                  class="pv-reset-btn"
                  @click="resetAllPreviewOverrides"
                  title="Khôi phục toàn bộ nội dung, độ rộng cột &amp; chiều cao dòng về dữ liệu gốc"
                >
                  Khôi phục ({{ previewOverrideCount }})
                </button>
                <button
                  type="button"
                  class="pv-zoom-open-btn"
                  title="Phóng to toàn màn hình để xem và chỉnh sửa chi tiết bản in"
                  @click="openPrintPreviewZoomModal()"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>
                  <span>Phóng to</span>
                </button>
              </div>
            </div>

            <!-- THANH 2: CÔNG CỤ ĐỊNH DẠNG Ô & KÉO / NHẬP RỘNG CỘT - CAO DÒNG -->
            <div v-if="isPreviewDirectEditMode" class="pv-wysiwyg-toolbar">
              <div class="pv-cell-badge" :title="activePreviewCellKey || 'Click vào một ô trên bản xem trước để sửa'">
                <span>{{ activePreviewCellAddr ? `Ô ${activePreviewCellAddr}` : 'Click ô để sửa' }}</span>
              </div>

              <div class="pv-tool-group">
                <button type="button" class="pv-tool-btn" title="In đậm (Bold)" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('bold')"><strong>B</strong></button>
                <button type="button" class="pv-tool-btn" title="In nghiêng (Italic)" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('italic')"><em>I</em></button>
                <button type="button" class="pv-tool-btn" title="Gạch chân (Underline)" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('underline')"><span style="text-decoration: underline;">U</span></button>
              </div>

              <div class="pv-tool-group">
                <button type="button" class="pv-tool-btn" title="Căn trái" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('align-left')">Trái</button>
                <button type="button" class="pv-tool-btn" title="Căn giữa" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('align-center')">Giữa</button>
                <button type="button" class="pv-tool-btn" title="Căn phải" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('align-right')">Phải</button>
              </div>

              <div class="pv-tool-group">
                <button type="button" class="pv-tool-btn" title="Giảm cỡ chữ" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('font-dec')">A-</button>
                <button type="button" class="pv-tool-btn" title="Tăng cỡ chữ" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('font-inc')">A+</button>
              </div>

              <div class="pv-tool-group">
                <label class="pv-color-picker-label" title="Đổi màu chữ ô đang chọn">
                  <span>Chữ</span>
                  <input type="color" :value="activePreviewCellColor" :disabled="!activePreviewCellKey" @input="applyStyleToActivePreviewCell('color', ($event.target as HTMLInputElement).value)" />
                </label>
                <label class="pv-color-picker-label" title="Đổi màu nền ô đang chọn">
                  <span>Nền</span>
                  <input type="color" :value="activePreviewCellBgColor" :disabled="!activePreviewCellKey" @input="applyStyleToActivePreviewCell('bg', ($event.target as HTMLInputElement).value)" />
                </label>
              </div>

              <div class="pv-tool-group pv-size-inputs-group">
                <div class="pv-size-input-label" title="Chiều rộng cột đang chọn (px) — Bấm -/+, nhập số hoặc kéo vạch biên phải của cột A, B, C...">
                  <span>Rộng {{ activePreviewColIndex ? excelColLetterFromNumber(activePreviewColIndex) : 'cột' }}:</span>
                  <button type="button" class="pv-size-step-btn" title="Giảm độ rộng cột (-4px)" @click="stepActivePreviewColWidth(-4)">-</button>
                  <input
                    type="number"
                    min="24"
                    max="900"
                    step="2"
                    class="pv-size-number-input"
                    :value="activePreviewColWidth || ''"
                    placeholder="px"
                    @input="onActivePreviewColWidthInput(Number(($event.target as HTMLInputElement).value))"
                  />
                  <button type="button" class="pv-size-step-btn" title="Tăng độ rộng cột (+4px)" @click="stepActivePreviewColWidth(4)">+</button>
                </div>
                <div class="pv-size-input-label pv-row-height-box" title="Chiều cao hàng đang chọn (px) — Bấm -/+, nhập số hoặc kéo thước hàng 1, 2, 3... bên trái trang in">
                  <span>Cao {{ activePreviewExcelRow ? `hàng ${activePreviewExcelRow}` : 'hàng' }}:</span>
                  <button type="button" class="pv-size-step-btn" title="Giảm chiều cao hàng (-2px)" @click="stepActivePreviewRowHeight(-2)">-</button>
                  <input
                    type="number"
                    min="8"
                    max="400"
                    step="2"
                    class="pv-size-number-input"
                    :value="activePreviewRowHeight || ''"
                    placeholder="px"
                    @input="onActivePreviewRowHeightInput(Number(($event.target as HTMLInputElement).value))"
                  />
                  <button type="button" class="pv-size-step-btn" title="Tăng chiều cao hàng (+2px)" @click="stepActivePreviewRowHeight(2)">+</button>
                </div>
              </div>

              <button
                v-if="activePreviewCellKey || activePreviewExcelRow"
                type="button"
                class="pv-tool-btn pv-cell-restore-btn"
                title="Khôi phục ô / cột / hàng đang chọn về mặc định"
                @click="resetActivePreviewCellOverride"
              >
                Khôi phục ô/hàng
              </button>
            </div>

            <!-- THANH CÔNG THỨC EXCEL (HIỂN THỊ KHI CHỌN TAB EXCEL HOẶC Ô CÓ CÔNG THỨC) -->
            <div v-if="previewFormatMode === 'excel' || activePreviewCellFormula" class="pv-excel-formula-bar">
              <div class="pv-excel-addr-box">{{ activePreviewCellAddr || (activePreviewExcelRow ? `Hàng ${activePreviewExcelRow}` : 'A1') }}</div>
              <div class="pv-excel-fx-tag" :title="activePreviewCellFormula ? `Công thức gốc: =${activePreviewCellFormula}` : 'Giá trị văn bản / số'">
                fx
              </div>
              <input
                type="text"
                class="pv-excel-formula-input"
                :disabled="!activePreviewCellKey"
                :value="activePreviewCellText"
                :placeholder="activePreviewCellKey ? 'Nhập nội dung hiển thị cho ô đang chọn...' : 'Click vào một ô trên bảng bên dưới để chỉnh sửa...'"
                @input="onFormulaBarTextInput(($event.target as HTMLInputElement).value)"
              />
              <span v-if="activePreviewCellFormula" class="pv-excel-formula-chip" title="Khi xuất Excel, công thức tự động vẫn được bảo toàn nếu bạn không ghi đè giá trị tĩnh">
                ={{ activePreviewCellFormula }}
              </span>
            </div>

            <!-- VÙNG HIỂN THỊ TRANG BẢN IN THEO ĐỊNH DẠNG (CĂN KHỚP CỘT A,B,C & HÀNG 1,2,3 1:1) -->
            <div
              class="pv-viewport-stage"
              :class="`stage-${previewFormatMode}`"
              style="flex: 1; min-height: 0; overflow: auto; border: 1px solid rgba(148,163,184,0.25); border-radius: 8px; padding: 14px;"
            >
              <div
                class="pv-paper-frame"
                :style="{
                  width: previewSheetCustomWidth
                    ? `${previewSheetCustomWidth}px`
                    : (activePrintTemplate?.cau_hinh_trang?.huong_giay === 'landscape' ? '1146px' : '846px'),
                  maxWidth: previewSheetCustomWidth ? 'none' : '100%',
                  margin: '0 auto',
                  position: 'relative'
                }"
              >
                <!-- THƯỚC KÉO ĐỘ RỘNG CỘT (A, B, C... CĂN KHỚP VỚI THƯỚC HÀNG 26PX + PADDING TRANG) -->
                <div
                  class="pv-col-ruler-wrap"
                  :style="{
                    paddingLeft: `${26 + previewSheetPaddingPx}px`,
                    paddingRight: `${previewSheetPaddingPx}px`
                  }"
                >
                  <div class="pv-ruler-corner-box" title="Thước cột (A, B, C...) &amp; Thước hàng (1, 2, 3...)"></div>
                  <div class="pv-col-header-row" title="Kéo vạch ngăn cách giữa các cột A, B, C... để điều chỉnh chiều rộng cột">
                    <div
                      v-for="col in previewGridColHeaders"
                      :key="col.colIdx"
                      v-show="col.widthPx > 0"
                      class="pv-col-header-cell"
                      :class="{ 'is-active-col': activePreviewColIndex === col.colIdx }"
                      :style="{ width: col.pct + '%' }"
                      :title="`Cột ${col.letter} (${col.widthPx}px) — Kéo vạch bên phải để thay đổi độ rộng`"
                    >
                      <span class="pv-col-letter">{{ col.letter }}</span>
                      <div
                        class="pv-col-resizer"
                        @mousedown="startPreviewColResize($event, col.colIdx)"
                      ></div>
                    </div>
                  </div>
                </div>

                <!-- THƯỚC ĐO LỀ TRANG WORD (KHI CHỌN TAB WORD) -->
                <div v-if="previewFormatMode === 'word'" class="pv-word-ruler" style="padding-left: 40px;">
                  <span v-for="cm in 20" :key="cm" class="pv-word-ruler-mark">{{ cm }}</span>
                </div>

                <!-- THANH ĐỊA CHỈ GIẢ LẬP TRÌNH DUYỆT (KHI CHỌN TAB HTML) -->
                <div v-if="previewFormatMode === 'html'" class="pv-html-browser-chrome">
                  <div class="pv-browser-dots">
                    <span></span><span></span><span></span>
                  </div>
                  <div class="pv-browser-url">file:///{{ exportFileNamePreview }}.html</div>
                  <div class="pv-browser-tag">HTML5</div>
                </div>

                <!-- KHUNG THÂN GIẤY: THƯỚC HÀNG 1, 2, 3... (BÊN TRÁI) + TỜ BẢN IN (BÊN PHẢI) -->
                <div class="pv-paper-body-row">
                  <div
                    class="pv-row-ruler-wrap"
                    :style="{ paddingTop: `${previewTableTopOffsetPx}px` }"
                    title="Thước chiều cao hàng (1, 2, 3...) — Click chọn hàng hoặc kéo vạch ngang dưới mỗi số để tăng/giảm chiều cao hàng"
                  >
                    <div
                      v-for="row in previewGridRowHeaders"
                      :key="row.excelRow"
                      class="pv-row-header-cell"
                      :class="{ 'is-active-row': activePreviewExcelRow === row.excelRow }"
                      :style="{ height: `${row.heightPx}px` }"
                      :title="`Hàng ${row.excelRow} (Cao: ${row.heightPx}px) — Kéo cạnh dưới để điều chỉnh chiều cao hàng`"
                      @click="selectPreviewRowFromRuler(row.excelRow)"
                    >
                      <span class="pv-row-num">{{ row.excelRow }}</span>
                      <div
                        class="pv-row-resizer"
                        title="Giữ chuột kéo lên/xuống để thay đổi chiều cao hàng này"
                        @mousedown="startPreviewRowResize($event, row.excelRow)"
                      ></div>
                    </div>
                  </div>

                  <!-- TỜ BẢN IN TƯƠNG TÁC -->
                  <div
                    ref="modalPrintPreviewRef"
                    class="print-preview-sheet"
                    :class="[
                      `fmt-sheet-${previewFormatMode}`,
                      { 'is-direct-editable': isPreviewDirectEditMode }
                    ]"
                    :style="{
                      background: '#ffffff',
                      borderRadius: '0 0 6px 0',
                      overflow: 'hidden',
                      position: 'relative',
                      flex: '1',
                      minWidth: '0',
                      minHeight: previewSheetCustomHeight ? `${previewSheetCustomHeight}px` : undefined,
                      boxShadow: '0 4px 16px rgba(0, 0, 0, 0.2)'
                    }"
                    @mousemove="handlePreviewSheetMouseMove"
                    @mousedown="handlePreviewSheetMouseDown"
                    @click="handlePreviewSheetClick"
                    @focusin="handlePreviewSheetFocusIn"
                    @input="handlePreviewSheetInput"
                    @blur.capture="handlePreviewSheetBlur"
                    v-html="livePrintPreviewHtml"
                  ></div>
                </div>

                <!-- TAY NẮM KÉO RỘNG / CAO KHUNG TRANG BẢN IN -->
                <div
                  class="pv-paper-edge-right"
                  title="Giữ chuột kéo sang trái/phải để thay đổi chiều rộng trang bản in"
                  @mousedown="startPreviewSheetSizeResize($event, 'width', modalPrintPreviewRef)"
                ></div>
                <div
                  class="pv-paper-edge-bottom"
                  title="Giữ chuột kéo lên/xuống để thay đổi chiều cao trang bản in"
                  @mousedown="startPreviewSheetSizeResize($event, 'height', modalPrintPreviewRef)"
                >
                  <span class="pv-edge-bottom-pill">Kéo chỉnh chiều cao trang {{ previewSheetCustomHeight ? `(${previewSheetCustomHeight}px)` : '' }}</span>
                </div>
                <div
                  class="pv-paper-corner-grip"
                  title="Giữ chuột kéo chéo để thay đổi cả chiều rộng và chiều cao trang bản in"
                  @mousedown="startPreviewSheetSizeResize($event, 'both', modalPrintPreviewRef)"
                ></div>
              </div>
            </div>
          </div>
        </div>

        <!-- FOOTER ACTIONS -->
        <div class="cust-modal-footer fullscreen-modal-footer export-multi-footer" style="padding: 12px 28px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; flex-wrap: wrap; gap: 10px; justify-content: space-between; align-items: center; margin-top: 0; flex-shrink: 0; border-radius: 0 !important;">
          <div class="export-multi-footer-left" style="display: flex; align-items: center; gap: 10px; flex-wrap: wrap;">
            <button
              type="button"
              class="modal-btn-secondary"
              @click="showExportExcelModal = false"
              style="padding: 10px 20px; border-radius: 8px; font-weight: 700; font-size: 13px; color: #fff; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); cursor: pointer; width: fit-content; margin: 0;"
            >
              Đóng
            </button>
            <span v-if="previewOverrideCount > 0" style="font-size: 11.5px; font-weight: 700; color: #38bdf8; background: rgba(56,189,248,0.12); border: 1px solid rgba(56,189,248,0.3); padding: 5px 11px; border-radius: 7px;">
              Đã chỉnh sửa {{ previewOverrideCount }} mục trên bản in (Tự động đồng bộ khi xuất file)
            </span>
          </div>

          <div class="export-multi-footer-btns" style="display: flex; flex-wrap: wrap; gap: 8px; align-items: center;">
            <button
              type="button"
              class="pv-export-action-btn fmt-export-excel"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'excel',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'excel',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'excel'
              }"
              @click="requestExportWithSaveConfirm('excel')"
            >
              Xuất Excel (.xlsx)
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-word"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'word',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'word',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'word'
              }"
              @click="requestExportWithSaveConfirm('word')"
            >
              Xuất Word (.doc)
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-pdf"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'pdf',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'pdf',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'pdf'
              }"
              @click="requestExportWithSaveConfirm('pdf')"
            >
              In / Xuất PDF
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-png"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'png',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'png',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'png'
              }"
              @click="requestExportWithSaveConfirm('png')"
            >
              Xuất Ảnh (.png)
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-html"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'html',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'html',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'html'
              }"
              @click="requestExportWithSaveConfirm('html')"
            >
              Xuất HTML (.html)
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- ================== MODAL: PHÓNG TO XEM TRƯỚC & CHỈNH SỬA BẢN IN ================== -->
    <div v-if="showPrintPreviewZoomModal" class="modal vip-modal-overlay modal-fullscreen-overlay" style="z-index: 10045;" @click.self="showPrintPreviewZoomModal = false">
      <div class="modal-card modal-wide vip-modal-card export-vip-modal modal-fullscreen-card export-zoom-preview-modal">
        <div class="modal-head modal-head-themed export-zoom-head" style="justify-content: space-between; position: relative; margin-bottom: 0; padding: 10px 24px; border-bottom: none; border-radius: 0; flex-shrink: 0;">
          <div class="export-zoom-title-wrap" style="color: #ffffff; text-transform: uppercase; font-weight: 900; font-size: 14px; letter-spacing: 0.5px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap;">
            <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>
            <span class="dt-lbl">XEM TRƯỚC &amp; CHỈNH SỬA BẢN IN — {{ activePrintTemplate?.ten_mau || 'Mẫu chuẩn' }} (Khổ {{ activePrintTemplate?.cau_hinh_trang?.kho_giay || 'A4' }} • {{ activePrintTemplate?.cau_hinh_trang?.huong_giay === 'portrait' ? 'Dọc' : 'Ngang' }})</span>
            <span class="mb-lbl">XEM TRƯỚC ({{ activePrintTemplate?.cau_hinh_trang?.kho_giay || 'A4' }} {{ activePrintTemplate?.cau_hinh_trang?.huong_giay === 'portrait' ? 'Dọc' : 'Ngang' }})</span>
          </div>

          <div class="export-zoom-head-controls" style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <button
              type="button"
              class="pv-mode-toggle-btn"
              :class="{ active: isPreviewDirectEditMode }"
              @click="isPreviewDirectEditMode = !isPreviewDirectEditMode"
            >
              <span class="dt-lbl">{{ isPreviewDirectEditMode ? 'Sửa trực tiếp: BẬT' : 'Sửa trực tiếp: TẮT' }}</span>
              <span class="mb-lbl">{{ isPreviewDirectEditMode ? 'Sửa: BẬT' : 'Sửa: TẮT' }}</span>
            </button>
            <button
              v-if="previewOverrideCount > 0"
              type="button"
              class="pv-reset-btn"
              @click="resetAllPreviewOverrides"
            >
              <span class="dt-lbl">Khôi phục ({{ previewOverrideCount }})</span>
              <span class="mb-lbl">Reset ({{ previewOverrideCount }})</span>
            </button>
            <button
              type="button"
              class="export-zoom-step-btn"
              @click="printPreviewZoomScale = Math.max(35, printPreviewZoomScale - 15)"
              style="padding: 4px 10px !important; height: 28px !important; border-radius: 6px !important; background: rgba(0,0,0,0.22) !important; color: #ffffff !important; border: 1px solid rgba(255,255,255,0.25) !important; font-weight: 800 !important; font-size: 13px !important; cursor: pointer !important; width: auto !important; margin: 0 !important;"
              title="Thu nhỏ"
            >
              -
            </button>
            <button
              type="button"
              class="export-zoom-step-btn pct"
              @click="printPreviewZoomScale = (typeof window !== 'undefined' && window.innerWidth <= 1100) ? 50 : 100"
              style="padding: 4px 10px !important; height: 28px !important; border-radius: 6px !important; background: rgba(0,0,0,0.22) !important; color: #ffffff !important; border: 1px solid rgba(255,255,255,0.25) !important; font-weight: 800 !important; font-size: 12px !important; cursor: pointer !important; width: auto !important; margin: 0 !important;"
              title="Đặt lại tỷ lệ"
            >
              {{ printPreviewZoomScale }}%
            </button>
            <button
              type="button"
              class="export-zoom-step-btn"
              @click="printPreviewZoomScale = Math.min(200, printPreviewZoomScale + 15)"
              style="padding: 4px 10px !important; height: 28px !important; border-radius: 6px !important; background: rgba(0,0,0,0.22) !important; color: #ffffff !important; border: 1px solid rgba(255,255,255,0.25) !important; font-weight: 800 !important; font-size: 13px !important; cursor: pointer !important; width: auto !important; margin: 0 !important;"
              title="Phóng to"
            >
              +
            </button>
            <button class="x" @click="showPrintPreviewZoomModal = false" style="margin-left: 6px;">✕</button>
          </div>
        </div>

        <!-- THANH TAB ĐỊNH DẠNG + TOOLBAR TRONG MODAL PHÓNG TO -->
        <div class="preview-zoom-toolbar-strip">
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap;">
            <div class="pv-format-tabs-list">
              <button
                v-for="ft in previewFormatTabs"
                :key="ft.id"
                type="button"
                class="pv-format-tab-btn"
                :class="[`fmt-${ft.id}`, { active: previewFormatMode === ft.id }]"
                :title="ft.desc"
                @click="previewFormatMode = ft.id"
              >
                <span class="pv-fmt-name">{{ ft.label }}</span>
                <span class="pv-fmt-ext">{{ ft.badge }}</span>
              </button>
            </div>

            <div v-if="isPreviewDirectEditMode" class="pv-wysiwyg-toolbar" style="margin: 0;">
              <div class="pv-cell-badge">
                <span>{{ activePreviewCellAddr ? `Ô ${activePreviewCellAddr}` : 'Click ô để sửa' }}</span>
              </div>
              <div class="pv-tool-group">
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('bold')"><strong>B</strong></button>
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('italic')"><em>I</em></button>
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('underline')"><span style="text-decoration: underline;">U</span></button>
              </div>
              <div class="pv-tool-group">
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('align-left')">Trái</button>
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('align-center')">Giữa</button>
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('align-right')">Phải</button>
              </div>
              <div class="pv-tool-group">
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('font-dec')">A-</button>
                <button type="button" class="pv-tool-btn" :disabled="!activePreviewCellKey" @click="applyStyleToActivePreviewCell('font-inc')">A+</button>
              </div>
              <div class="pv-tool-group">
                <label class="pv-color-picker-label">
                  <span>Chữ</span>
                  <input type="color" :value="activePreviewCellColor" :disabled="!activePreviewCellKey" @input="applyStyleToActivePreviewCell('color', ($event.target as HTMLInputElement).value)" />
                </label>
                <label class="pv-color-picker-label">
                  <span>Nền</span>
                  <input type="color" :value="activePreviewCellBgColor" :disabled="!activePreviewCellKey" @input="applyStyleToActivePreviewCell('bg', ($event.target as HTMLInputElement).value)" />
                </label>
              </div>
              <div class="pv-tool-group pv-size-inputs-group">
                <div class="pv-size-input-label">
                  <span>Rộng {{ activePreviewColIndex ? excelColLetterFromNumber(activePreviewColIndex) : 'cột' }}:</span>
                  <button type="button" class="pv-size-step-btn" title="Giảm độ rộng cột (-4px)" @click="stepActivePreviewColWidth(-4)">-</button>
                  <input
                    type="number"
                    min="24"
                    max="900"
                    step="2"
                    class="pv-size-number-input"
                    :value="activePreviewColWidth || ''"
                    placeholder="px"
                    @input="onActivePreviewColWidthInput(Number(($event.target as HTMLInputElement).value))"
                  />
                  <button type="button" class="pv-size-step-btn" title="Tăng độ rộng cột (+4px)" @click="stepActivePreviewColWidth(4)">+</button>
                </div>
                <div class="pv-size-input-label pv-row-height-box">
                  <span>Cao {{ activePreviewExcelRow ? `hàng ${activePreviewExcelRow}` : 'hàng' }}:</span>
                  <button type="button" class="pv-size-step-btn" title="Giảm chiều cao hàng (-2px)" @click="stepActivePreviewRowHeight(-2)">-</button>
                  <input
                    type="number"
                    min="8"
                    max="400"
                    step="2"
                    class="pv-size-number-input"
                    :value="activePreviewRowHeight || ''"
                    placeholder="px"
                    @input="onActivePreviewRowHeightInput(Number(($event.target as HTMLInputElement).value))"
                  />
                  <button type="button" class="pv-size-step-btn" title="Tăng chiều cao hàng (+2px)" @click="stepActivePreviewRowHeight(2)">+</button>
                </div>
              </div>
              <button
                v-if="activePreviewCellKey || activePreviewExcelRow"
                type="button"
                class="pv-tool-btn pv-cell-restore-btn"
                @click="resetActivePreviewCellOverride"
              >
                Khôi phục ô/hàng
              </button>
            </div>
          </div>

          <div v-if="previewFormatMode === 'excel' || activePreviewCellFormula" class="pv-excel-formula-bar">
            <div class="pv-excel-addr-box">{{ activePreviewCellAddr || (activePreviewExcelRow ? `Hàng ${activePreviewExcelRow}` : 'A1') }}</div>
            <div class="pv-excel-fx-tag">fx</div>
            <input
              type="text"
              class="pv-excel-formula-input"
              :disabled="!activePreviewCellKey"
              :value="activePreviewCellText"
              placeholder="Click vào một ô trên bản xem trước để sửa nội dung..."
              @input="onFormulaBarTextInput(($event.target as HTMLInputElement).value)"
            />
            <span v-if="activePreviewCellFormula" class="pv-excel-formula-chip">={{ activePreviewCellFormula }}</span>
          </div>
        </div>

        <div
          class="pv-viewport-stage"
          :class="`stage-${previewFormatMode}`"
          style="flex: 1; min-height: 0; overflow: auto; padding: 24px; display: flex; flex-direction: column; align-items: center;"
        >
          <div
            class="pv-paper-frame"
            :style="{
              width: previewSheetCustomWidth
                ? `${previewSheetCustomWidth}px`
                : (activePrintTemplate?.cau_hinh_trang?.huong_giay === 'landscape' ? '1206px' : '886px'),
              position: 'relative',
              zoom: (printPreviewZoomScale / 100)
            }"
          >
            <!-- THƯỚC KÉO CỘT A, B, C... TRONG MODAL PHÓNG TO -->
            <div
              class="pv-col-ruler-wrap"
              :style="{
                paddingLeft: `${26 + previewSheetPaddingPx}px`,
                paddingRight: `${previewSheetPaddingPx}px`
              }"
            >
              <div class="pv-ruler-corner-box" title="Thước cột (A, B, C...) &amp; Thước hàng (1, 2, 3...)"></div>
              <div class="pv-col-header-row">
                <div
                  v-for="col in previewGridColHeaders"
                  :key="col.colIdx"
                  v-show="col.widthPx > 0"
                  class="pv-col-header-cell"
                  :class="{ 'is-active-col': activePreviewColIndex === col.colIdx }"
                  :style="{ width: col.pct + '%' }"
                  :title="`Cột ${col.letter} (${col.widthPx}px) — Kéo vạch bên phải để thay đổi độ rộng`"
                >
                  <span class="pv-col-letter">{{ col.letter }}</span>
                  <div
                    class="pv-col-resizer"
                    @mousedown="startPreviewColResize($event, col.colIdx)"
                  ></div>
                </div>
              </div>
            </div>

            <div class="pv-paper-body-row">
              <div
                class="pv-row-ruler-wrap"
                :style="{ paddingTop: `${previewTableTopOffsetPx}px` }"
                title="Thước chiều cao hàng (1, 2, 3...) — Click chọn hàng hoặc kéo vạch ngang dưới mỗi số để tăng/giảm chiều cao hàng"
              >
                <div
                  v-for="row in previewGridRowHeaders"
                  :key="row.excelRow"
                  class="pv-row-header-cell"
                  :class="{ 'is-active-row': activePreviewExcelRow === row.excelRow }"
                  :style="{ height: `${row.heightPx}px` }"
                  :title="`Hàng ${row.excelRow} (Cao: ${row.heightPx}px) — Kéo cạnh dưới để điều chỉnh chiều cao hàng`"
                  @click="selectPreviewRowFromRuler(row.excelRow)"
                >
                  <span class="pv-row-num">{{ row.excelRow }}</span>
                  <div
                    class="pv-row-resizer"
                    title="Giữ chuột kéo lên/xuống để thay đổi chiều cao hàng này"
                    @mousedown="startPreviewRowResize($event, row.excelRow)"
                  ></div>
                </div>
              </div>

              <div
                ref="zoomModalPrintPreviewRef"
                class="print-preview-sheet"
                :class="[
                  `fmt-sheet-${previewFormatMode}`,
                  { 'is-direct-editable': isPreviewDirectEditMode }
                ]"
                :style="{
                  background: '#ffffff',
                  borderRadius: '0 0 6px 0',
                  overflow: 'hidden',
                  flex: '1',
                  minWidth: '0',
                  minHeight: previewSheetCustomHeight ? `${previewSheetCustomHeight}px` : undefined,
                  maxWidth: 'none',
                  boxShadow: '0 10px 30px rgba(0, 0, 0, 0.28)'
                }"
                @mousemove="handlePreviewSheetMouseMove"
                @mousedown="handlePreviewSheetMouseDown"
                @click="handlePreviewSheetClick"
                @focusin="handlePreviewSheetFocusIn"
                @input="handlePreviewSheetInput"
                @blur.capture="handlePreviewSheetBlur"
                v-html="livePrintPreviewHtml"
              ></div>
            </div>

            <div
              class="pv-paper-edge-right"
              title="Giữ chuột kéo sang trái/phải để thay đổi chiều rộng trang bản in"
              @mousedown="startPreviewSheetSizeResize($event, 'width', zoomModalPrintPreviewRef)"
            ></div>
            <div
              class="pv-paper-edge-bottom"
              title="Giữ chuột kéo lên/xuống để thay đổi chiều cao trang bản in"
              @mousedown="startPreviewSheetSizeResize($event, 'height', zoomModalPrintPreviewRef)"
            >
              <span class="pv-edge-bottom-pill">Kéo chỉnh chiều cao trang {{ previewSheetCustomHeight ? `(${previewSheetCustomHeight}px)` : '' }}</span>
            </div>
            <div
              class="pv-paper-corner-grip"
              title="Giữ chuột kéo chéo để thay đổi cả chiều rộng và chiều cao trang bản in"
              @mousedown="startPreviewSheetSizeResize($event, 'both', zoomModalPrintPreviewRef)"
            ></div>
          </div>
        </div>

        <div class="cust-modal-footer fullscreen-modal-footer export-zoom-footer" style="padding: 12px 24px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; flex-shrink: 0; border-radius: 0 !important;">
          <button
            type="button"
            class="modal-btn-secondary export-zoom-back-btn"
            @click="showPrintPreviewZoomModal = false"
            style="padding: 10px 24px; border-radius: 8px; font-weight: 700; font-size: 13.5px; color: #fff; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); cursor: pointer; width: fit-content; margin: 0;"
          >
            Thu nhỏ / Quay lại
          </button>

          <div class="export-zoom-footer-btns" style="display: flex; flex-wrap: wrap; gap: 8px; align-items: center;">
            <button
              type="button"
              class="pv-export-action-btn fmt-export-excel"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'excel',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'excel',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'excel'
              }"
              @click="showPrintPreviewZoomModal = false; requestExportWithSaveConfirm('excel')"
            >
              Xuất Excel (.xlsx)
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-word"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'word',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'word',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'word'
              }"
              @click="showPrintPreviewZoomModal = false; requestExportWithSaveConfirm('word')"
            >
              Xuất Word (.doc)
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-pdf"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'pdf',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'pdf',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'pdf'
              }"
              @click="showPrintPreviewZoomModal = false; requestExportWithSaveConfirm('pdf')"
            >
              In / Xuất PDF
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-png"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'png',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'png',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'png'
              }"
              @click="showPrintPreviewZoomModal = false; requestExportWithSaveConfirm('png')"
            >
              Xuất Ảnh (.png)
            </button>
            <button
              type="button"
              class="pv-export-action-btn fmt-export-html"
              :class="{
                'is-active-fmt': !isPreviewDirectEditMode || previewFormatMode === 'html',
                'is-focused-fmt': isPreviewDirectEditMode && previewFormatMode === 'html',
                'is-dimmed-fmt': isPreviewDirectEditMode && previewFormatMode !== 'html'
              }"
              @click="showPrintPreviewZoomModal = false; requestExportWithSaveConfirm('html')"
            >
              Xuất HTML (.html)
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- ================== MODAL CHỌN KHÁCH HÀNG (showCustomerPickerModal) ================== -->
    <div
      v-if="showCustomerPickerModal"
      class="modal"
      style="z-index: 100025;"
      @click.self="showCustomerPickerModal = false"
    >
      <div class="modal-card picker-modal-card" style="width: 680px; max-width: 94vw; height: 74vh; max-height: 680px; border-radius: 14px; display: flex; flex-direction: column; padding: 0; overflow: hidden;">
        <!-- HEADER -->
        <div class="modal-head" style="padding: 14px 20px; border-bottom: 1px solid rgba(255,255,255,0.08); position: relative; flex-shrink: 0;">
          <h3 style="margin: 0; font-size: 15px; font-weight: 800; color: #ffffff !important; letter-spacing: 0.4px; text-transform: uppercase;">
            {{ customerPickerTitle }}
          </h3>
          <button class="x" @click="showCustomerPickerModal = false">✕</button>
        </div>

        <!-- TOP SEARCH TOOLBAR -->
        <div class="cust-top-toolbar" style="padding: 12px 20px; border-bottom: 1px solid rgba(148,163,184,0.16); background: rgba(15,23,42,0.35); display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; flex-shrink: 0;">
          <div style="display: flex; align-items: center; gap: 8px; flex: 1; min-width: 240px;">
            <input
              v-model="customerPickerSearch"
              type="text"
              :placeholder="'Tìm kiếm ' + customerPickerColumnLabel + '...'"
              style="flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 13px; font-weight: 600; margin: 0;"
            />
            <button
              v-if="customerPickerSearch"
              type="button"
              @click="customerPickerSearch = ''"
              style="padding: 8px 12px; border-radius: 7px; font-size: 12px; font-weight: 700; background: #64748b; color: #ffffff !important; border: none; cursor: pointer; width: fit-content; margin: 0;"
            >
              Xóa
            </button>
          </div>
          <span style="font-size: 12px; font-weight: 700; white-space: nowrap;">
            Hiển thị <strong style="color: #0284c7;">{{ visibleCustomerPickerList.length }}</strong> / {{ filteredCustomerPickerList.length }}
          </span>
        </div>

        <!-- TABLE WORKSPACE (LAZY LOADING 20 HÀNG) -->
        <div style="padding: 14px 20px; flex: 1; min-height: 0; overflow: hidden; display: flex; flex-direction: column;">
          <div
            class="picker-table-box"
            style="flex: 1; min-height: 0; overflow: auto; border-radius: 10px; border: 1px solid rgba(148,163,184,0.2);"
            @scroll="onCustomerPickerScroll"
          >
            <table class="picker-data-table" style="width: 100%; border-collapse: collapse; font-size: 13px;">
              <thead>
                <tr>
                  <th style="width: 56px; text-align: center;">STT</th>
                  <th style="text-align: left;">{{ customerPickerColumnLabel }}</th>
                  <th style="width: 100px; text-align: center;">Thao tác</th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="filteredCustomerPickerList.length === 0">
                  <td colspan="3" style="padding: 36px 16px; text-align: center; font-weight: 600; opacity: 0.75;">
                    Không tìm thấy dữ liệu phù hợp với từ khóa "{{ customerPickerSearch }}".
                  </td>
                </tr>
                <tr
                  v-for="(cus, idx) in visibleCustomerPickerList"
                  :key="(cus.Ma_khach_hang || '') + '_' + idx"
                  class="picker-row"
                  :class="{ 'picker-row-selected': isCustomerRowSelected(cus) }"
                  @click="selectCustomerFromPicker(cus)"
                >
                  <td style="text-align: center; font-weight: 700; opacity: 0.75;">{{ idx + 1 }}</td>
                  <td style="font-weight: 700;">{{ getCustomerPickerValue(cus) }}</td>
                  <td style="text-align: center;" @click.stop>
                    <button
                      type="button"
                      class="picker-select-action-btn"
                      @click="selectCustomerFromPicker(cus)"
                    >
                      {{ isCustomerRowSelected(cus) ? 'Đang chọn' : 'Chọn' }}
                    </button>
                  </td>
                </tr>
                <tr
                  v-if="visibleCustomerPickerList.length < filteredCustomerPickerList.length"
                  style="cursor: pointer;"
                  @click="customerPickerVisibleCount += 20"
                >
                  <td colspan="3" style="padding: 12px; text-align: center; font-weight: 700; color: #0284c7; font-size: 12px;">
                    Đang hiển thị {{ visibleCustomerPickerList.length }} / {{ filteredCustomerPickerList.length }} dòng — Cuộn xuống hoặc bấm để tải thêm 20 dòng...
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <!-- FOOTER -->
        <div class="cust-modal-footer" style="padding: 10px 20px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; justify-content: flex-end; align-items: center; gap: 10px; flex-shrink: 0;">
          <button
            type="button"
            class="modal-btn-secondary"
            @click="showCustomerPickerModal = false"
            style="padding: 8px 20px; border-radius: 8px; font-weight: 700; font-size: 13px; color: #fff; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); cursor: pointer; width: fit-content; margin: 0;"
          >
            Đóng
          </button>
        </div>
      </div>
    </div>

    <!-- ================== MODAL CHỌN HÀNG HÓA (showProductPickerModal) ================== -->
    <div
      v-if="showProductPickerModal"
      class="modal"
      style="z-index: 100025;"
      @click.self="showProductPickerModal = false"
    >
      <div class="modal-card picker-modal-card" style="width: 680px; max-width: 94vw; height: 74vh; max-height: 680px; border-radius: 14px; display: flex; flex-direction: column; padding: 0; overflow: hidden;">
        <!-- HEADER -->
        <div class="modal-head" style="padding: 14px 20px; border-bottom: 1px solid rgba(255,255,255,0.08); position: relative; flex-shrink: 0;">
          <h3 style="margin: 0; font-size: 15px; font-weight: 800; color: #ffffff !important; letter-spacing: 0.4px; text-transform: uppercase;">
            {{ productPickerTitle }}
          </h3>
          <button class="x" @click="showProductPickerModal = false">✕</button>
        </div>

        <!-- TOP SEARCH TOOLBAR -->
        <div class="cust-top-toolbar" style="padding: 12px 20px; border-bottom: 1px solid rgba(148,163,184,0.16); background: rgba(15,23,42,0.35); display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; flex-shrink: 0;">
          <div style="display: flex; align-items: center; gap: 8px; flex: 1; min-width: 240px;">
            <input
              v-model="productPickerSearch"
              type="text"
              :placeholder="'Tìm kiếm ' + productPickerColumnLabel + '...'"
              style="flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 13px; font-weight: 600; margin: 0;"
            />
            <button
              v-if="productPickerSearch"
              type="button"
              @click="productPickerSearch = ''"
              style="padding: 8px 12px; border-radius: 7px; font-size: 12px; font-weight: 700; background: #64748b; color: #ffffff !important; border: none; cursor: pointer; width: fit-content; margin: 0;"
            >
              Xóa
            </button>
          </div>
          <span style="font-size: 12px; font-weight: 700; white-space: nowrap;">
            Hiển thị <strong style="color: #0284c7;">{{ visibleProductPickerList.length }}</strong> / {{ filteredProductPickerList.length }}
          </span>
        </div>

        <!-- TABLE WORKSPACE (LAZY LOADING 20 HÀNG) -->
        <div style="padding: 14px 20px; flex: 1; min-height: 0; overflow: hidden; display: flex; flex-direction: column;">
          <div
            class="picker-table-box"
            style="flex: 1; min-height: 0; overflow: auto; border-radius: 10px; border: 1px solid rgba(148,163,184,0.2);"
            @scroll="onProductPickerScroll"
          >
            <table class="picker-data-table" style="width: 100%; border-collapse: collapse; font-size: 13px;">
              <thead>
                <tr>
                  <th style="width: 56px; text-align: center;">STT</th>
                  <th style="text-align: left;">{{ productPickerColumnLabel }}</th>
                  <th style="width: 100px; text-align: center;">Thao tác</th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="filteredProductPickerList.length === 0">
                  <td colspan="3" style="padding: 36px 16px; text-align: center; font-weight: 600; opacity: 0.75;">
                    Không tìm thấy dữ liệu phù hợp với từ khóa "{{ productPickerSearch }}".
                  </td>
                </tr>
                <tr
                  v-for="(entry, idx) in visibleProductPickerList"
                  :key="entry.value + '_' + idx"
                  class="picker-row"
                  :class="{ 'picker-row-selected': isProductRowSelected(entry) }"
                  @click="selectProductFromPicker(entry)"
                >
                  <td style="text-align: center; font-weight: 700; opacity: 0.75;">{{ idx + 1 }}</td>
                  <td style="font-weight: 700;">{{ entry.value }}</td>
                  <td style="text-align: center;" @click.stop>
                    <button
                      type="button"
                      class="picker-select-action-btn"
                      @click="selectProductFromPicker(entry)"
                    >
                      {{ isProductRowSelected(entry) ? 'Đang chọn' : 'Chọn' }}
                    </button>
                  </td>
                </tr>
                <tr
                  v-if="visibleProductPickerList.length < filteredProductPickerList.length"
                  style="cursor: pointer;"
                  @click="productPickerVisibleCount += 20"
                >
                  <td colspan="3" style="padding: 12px; text-align: center; font-weight: 700; color: #0284c7; font-size: 12px;">
                    Đang hiển thị {{ visibleProductPickerList.length }} / {{ filteredProductPickerList.length }} dòng — Cuộn xuống hoặc bấm để tải thêm 20 dòng...
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <!-- FOOTER -->
        <div class="cust-modal-footer" style="padding: 10px 20px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; justify-content: flex-end; align-items: center; gap: 10px; flex-shrink: 0;">
          <button
            type="button"
            class="modal-btn-secondary"
            @click="showProductPickerModal = false"
            style="padding: 8px 20px; border-radius: 8px; font-weight: 700; font-size: 13px; color: #fff; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); cursor: pointer; width: fit-content; margin: 0;"
          >
            Đóng
          </button>
        </div>
      </div>
    </div>

    <!-- ================== MODAL: ĐIỀU CHỈNH GIÁ LIC (VIP) ================== -->
    <div v-if="adjustPriceModal.show" class="modal" @click.self="adjustPriceModal.show = false">
      <div class="modal-card" :style="{ width: '460px', padding: '0', background: '#0f172a', border: '1px solid ' + (adjustPriceModal.isNormalEdit ? 'rgba(59,130,246,0.25)' : 'rgba(16,185,129,0.25)'), boxShadow: '0 25px 50px -12px rgba(0,0,0,0.7), 0 0 0 1px ' + (adjustPriceModal.isNormalEdit ? 'rgba(59,130,246,0.1)' : 'rgba(16,185,129,0.1)'), borderRadius: '20px', overflow: 'hidden', animation: 'popIn 0.3s cubic-bezier(0.16, 1, 0.3, 1)' }">
        
        <!-- Header -->
        <div class="modal-head" :style="{ background: 'linear-gradient(135deg, ' + (adjustPriceModal.isNormalEdit ? 'rgba(59,130,246,0.12)' : 'rgba(16,185,129,0.12)') + ' 0%, rgba(15,23,42,0.95) 100%)', padding: '20px 24px', borderBottom: '1px solid ' + (adjustPriceModal.isNormalEdit ? 'rgba(59,130,246,0.15)' : 'rgba(16,185,129,0.15)'), display: 'flex', justifyContent: 'space-between', alignItems: 'center' }">
          <h3 style="color: #fff; font-size: 17px; font-weight: 700; display: flex; align-items: center; gap: 12px; margin: 0; letter-spacing: 0.3px;">
            <div :style="{ width: '36px', height: '36px', borderRadius: '10px', background: adjustPriceModal.isNormalEdit ? 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)' : 'linear-gradient(135deg, #10b981 0%, #059669 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 4px 15px ' + (adjustPriceModal.isNormalEdit ? 'rgba(59,130,246,0.4)' : 'rgba(16,185,129,0.4)') }">
              <i :class="adjustPriceModal.isNormalEdit ? 'ri-edit-line' : 'ri-arrow-up-down-fill'" style="color: #fff; font-size: 18px;"></i>
            </div>
            {{ adjustPriceModal.isNormalEdit ? 'Sửa Thường' : 'Điều Chỉnh Giá' }}
          </h3>
          <button class="x" @click="adjustPriceModal.show = false" style="background: rgba(255,255,255,0.05); color: #94a3b8; border: 1px solid rgba(255,255,255,0.1); border-radius: 10px; width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s; font-size: 16px;">✕</button>
        </div>
        
        <div style="padding: 24px;">
          <!-- Note giải thích -->
          <div v-if="adjustPriceModal.isNormalEdit" style="display: flex; align-items: center; gap: 10px; padding: 10px 14px; margin-bottom: 16px; border-radius: 10px; background: rgba(59,130,246,0.08); border: 1px solid rgba(59,130,246,0.2);">
            <i class="ri-information-line" style="color: #3b82f6; font-size: 16px; flex-shrink: 0;"></i>
            <span style="font-size: 12px; color: #93c5fd; line-height: 1.5;">Sửa thường sẽ cập nhật <b>giá thực tế</b>, không tạo chênh lệch giá hay chiết khấu.</span>
          </div>
          <div v-else-if="adjustPriceModal.mode === 'field'" style="display: flex; align-items: center; gap: 10px; padding: 10px 14px; margin-bottom: 16px; border-radius: 10px; background: rgba(16,185,129,0.08); border: 1px solid rgba(16,185,129,0.2);">
            <i class="ri-information-line" style="color: #10b981; font-size: 16px; flex-shrink: 0;"></i>
            <span style="font-size: 12px; color: #6ee7b7; line-height: 1.5;">Điều chỉnh sẽ tạo <b>chênh lệch giá</b> (giá bán thay đổi, giá thực tế giữ nguyên).</span>
          </div>
          <!-- Target Info Card -->
          <div style="background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.08); border-radius: 14px; padding: 16px; margin-bottom: 24px; position: relative; overflow: hidden;">
            <div style="position: absolute; top: 0; left: 0; right: 0; height: 2px; background: linear-gradient(90deg, transparent, #10b981, transparent); opacity: 0.5;"></div>
            <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px;">
              <span style="color: #64748b; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;">Phạm vi áp dụng</span>
              <span style="color: #e2e8f0; font-weight: 700; font-size: 14px; text-align: right; max-width: 60%; line-height: 1.4;">{{ adjustPriceModal.targetName || (adjustPriceModal.mode === 'all' ? 'Toàn bộ báo giá' : '') }}</span>
            </div>
            <div style="display: flex; justify-content: space-between; align-items: center;">
              <span style="color: #64748b; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;">Giá trị gốc</span>
              <span style="color: #10b981; font-weight: 800; font-size: 20px; text-shadow: 0 0 15px rgba(16,185,129,0.25);">{{ formatVND(adjustPriceModal.currentTotal) }} <span style="font-size: 16px;">₫</span></span>
            </div>
          </div>
          
          <!-- Segmented Control -->
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin-bottom: 24px; background: rgba(0,0,0,0.4); padding: 4px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.05); position: relative;">
            <button 
              :style="{ 
                borderRadius: '10px', padding: '10px', fontWeight: '700', fontSize: '13px', textAlign: 'center', transition: 'all 0.3s ease', border: 'none', 
                background: adjustPriceModal.adjustType === 'percent' ? 'rgba(16,185,129,0.15)' : 'transparent', 
                color: adjustPriceModal.adjustType === 'percent' ? '#10b981' : '#64748b', 
                cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px',
                boxShadow: adjustPriceModal.adjustType === 'percent' ? '0 2px 10px rgba(0,0,0,0.2), inset 0 1px 0 rgba(16,185,129,0.2)' : 'none'
              }" 
              @click="adjustPriceModal.adjustType = 'percent'"
            >
              <i class="ri-percent-line" style="font-size: 16px;"></i> Tăng/Giảm theo %
            </button>
            <button 
              :style="{ 
                borderRadius: '10px', padding: '10px', fontWeight: '700', fontSize: '13px', textAlign: 'center', transition: 'all 0.3s ease', border: 'none', 
                background: adjustPriceModal.adjustType === 'number' ? 'rgba(16,185,129,0.15)' : 'transparent', 
                color: adjustPriceModal.adjustType === 'number' ? '#10b981' : '#64748b', 
                cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px',
                boxShadow: adjustPriceModal.adjustType === 'number' ? '0 2px 10px rgba(0,0,0,0.2), inset 0 1px 0 rgba(16,185,129,0.2)' : 'none'
              }" 
              @click="adjustPriceModal.adjustType = 'number'"
            >
              <i class="ri-money-dollar-circle-line" style="font-size: 16px;"></i> Nhập giá trị
            </button>
          </div>
          
          <!-- Input Area -->
          <div style="margin-bottom: 32px;">
            <div v-if="adjustPriceModal.adjustType === 'percent'" style="animation: fadeIn 0.3s ease;">
              <label style="display: block; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; margin-bottom: 10px; letter-spacing: 0.5px;">Mức Điều Chỉnh (VD: 10 Tăng, -5 Giảm)</label>
              <div style="position: relative;">
                <FormattedInput v-model="adjustPriceModal.percentValue" placeholder="0" style="width: 100%; padding: 14px 16px; padding-right: 48px; border-radius: 12px; background: rgba(15,23,42,0.8); border: 2px solid rgba(16,185,129,0.2); color: #fff; font-size: 18px; font-weight: 800; outline: none; transition: all 0.3s; box-shadow: inset 0 2px 4px rgba(0,0,0,0.2);" />
                <div style="position: absolute; right: 12px; top: 50%; transform: translateY(-50%); width: 28px; height: 28px; background: rgba(16,185,129,0.1); border-radius: 6px; display: flex; align-items: center; justify-content: center; color: #10b981; font-weight: 800; font-size: 14px; pointer-events: none;">%</div>
              </div>
              <div style="margin-top: 16px; display: flex; justify-content: space-between; align-items: center; padding: 14px 16px; background: linear-gradient(90deg, rgba(16,185,129,0.1) 0%, rgba(16,185,129,0.02) 100%); border-radius: 10px; border-left: 3px solid #10b981;">
                <span style="color: #cbd5e1; font-size: 13px; font-weight: 600;">Dự kiến mới:</span>
                <span style="color: #10b981; font-weight: 800; font-size: 16px; letter-spacing: 0.5px;">{{ formatVND(adjustPriceModal.currentTotal * (1 + (adjustPriceModal.percentValue || 0) / 100)) }} ₫</span>
              </div>
            </div>
            
            <div v-else style="animation: fadeIn 0.3s ease;">
              <label style="display: block; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; margin-bottom: 10px; letter-spacing: 0.5px;">Nhập Giá Trị Mong Muốn</label>
              <div style="position: relative;">
                <FormattedInput v-model="adjustPriceModal.numberValue" :decimals="quoteCurrency === 'USD' ? 2 : 0" placeholder="Nhập số tiền..." style="width: 100%; padding: 14px 16px; padding-right: 48px; border-radius: 12px; background: rgba(15,23,42,0.8); border: 2px solid rgba(16,185,129,0.2); color: #fff; font-size: 18px; font-weight: 800; outline: none; transition: all 0.3s; box-shadow: inset 0 2px 4px rgba(0,0,0,0.2);" />
                <div style="position: absolute; right: 12px; top: 50%; transform: translateY(-50%); width: 28px; height: 28px; background: rgba(16,185,129,0.1); border-radius: 6px; display: flex; align-items: center; justify-content: center; color: #10b981; font-weight: 800; font-size: 14px; pointer-events: none;">₫</div>
              </div>
            </div>
          </div>
          
          <!-- Actions -->
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
            <button @click.prevent="adjustPriceModal.show = false" style="padding: 14px; border-radius: 12px; font-weight: 700; font-size: 14px; background: rgba(255,255,255,0.05); color: #94a3b8; border: 1px solid rgba(255,255,255,0.1); cursor: pointer; transition: all 0.2s;">Hủy Bỏ</button>
            <button @click.prevent="applyAdjustPrice()" :style="{ padding: '14px', borderRadius: '12px', fontWeight: '700', fontSize: '15px', background: adjustPriceModal.isNormalEdit ? 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)' : 'linear-gradient(135deg, #10b981 0%, #059669 100%)', color: '#fff', border: 'none', cursor: 'pointer', boxShadow: adjustPriceModal.isNormalEdit ? '0 4px 15px rgba(59,130,246,0.3)' : '0 4px 15px rgba(16,185,129,0.3)', transition: 'all 0.2s', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px' }">
              <i class="lucide-check"></i> Xác Nhận
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- ================== MODAL: LỊCH SỬ THAY ĐỔI ================== -->
    <div v-if="showHistoryModal" class="modal modal-fullscreen-overlay" @click.self="showHistoryModal = false">
      <div class="modal-card history-modal-card modal-fullscreen-card">
        <!-- Header -->
        <div class="history-modal-header" style="flex-shrink: 0; border-radius: 0;">
          <div class="history-modal-header-left">
            <div class="history-modal-icon-wrap">
              <i class="lucide-clock" style="font-size: 20px;"></i>
            </div>
            <div>
              <h3 class="history-modal-title">Lịch sử thay đổi</h3>
              <p class="history-modal-subtitle">{{ historyTitle }}</p>
            </div>
          </div>
          <button class="x" @click="showHistoryModal = false">✕</button>
        </div>

        <!-- Summary Stats -->
        <div v-if="currentHistory.length" class="history-summary">
          <div class="history-stat">
            <span class="history-stat-label">Tổng thay đổi</span>
            <span class="history-stat-value">{{ currentHistory.length }} lần</span>
          </div>
          <div class="history-stat">
            <span class="history-stat-label">Giá trị hiện tại</span>
            <span class="history-stat-value" style="color: #2563eb; font-size: 15px;">{{ formatVND(currentHistory[0]?.newVal ?? 0) }}</span>
          </div>
          <div class="history-stat">
            <span class="history-stat-label">Giá trị ban đầu</span>
            <span class="history-stat-value" style="color: #ffffff;">{{ formatVND(currentHistory[currentHistory.length - 1]?.oldVal ?? 0) }}</span>
          </div>
        </div>

        <!-- Table -->
        <div class="history-table-wrap">
          <table v-if="currentHistory.length" class="history-table">
            <thead>
              <tr>
                <th style="width: 40px; text-align: center;">#</th>
                <th style="width: 110px; text-align: center;">Thời gian</th>
                <th style="text-align: left;">Nội dung thay đổi</th>
                <th style="text-align: right;">Giá trị cũ</th>
                <th style="width: 40px; text-align: center;"></th>
                <th style="text-align: right;">Giá trị mới</th>
                <th style="text-align: right;">Chênh lệch</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(h, i) in currentHistory" :key="i" class="history-row">
                <td style="text-align: center; color: #94a3b8; font-size: 12px; font-weight: 600;">{{ i + 1 }}</td>
                <td style="text-align: center;">
                  <span class="history-time-badge">{{ h.time }}</span>
                </td>
                <td style="text-align: left; font-size: 13px; color: #ffffff; line-height: 1.4;">
                  <template v-if="isGlobalHistory && h.reason">
                    {{ h.reason }}
                  </template>
                  <template v-else>
                    <b>{{ h.metric || historyTitle }}</b> thay đổi từ <span style="color: #ef4444; font-weight: 500;">{{ formatVND(h.oldVal) }}</span> → <b>{{ formatVND(h.newVal) }}</b>
                  </template>
                </td>
                <td style="text-align: right;">
                  <span class="history-old-val">{{ formatVND(h.oldVal) }}</span>
                </td>
                <td style="text-align: center;">
                  <span
                    class="history-arrow"
                    :class="h.newVal > h.oldVal ? 'arrow-up' : h.newVal < h.oldVal ? 'arrow-down' : 'arrow-same'"
                  >
                    {{ h.newVal > h.oldVal ? '▲' : h.newVal < h.oldVal ? '▼' : '━' }}
                  </span>
                </td>
                <td style="text-align: right;">
                  <span
                    class="history-new-val"
                    :class="h.newVal > h.oldVal ? 'val-up' : h.newVal < h.oldVal ? 'val-down' : ''"
                  >{{ formatVND(h.newVal) }}</span>
                </td>
                <td style="text-align: right;">
                  <span
                    class="history-diff"
                    :class="h.newVal - h.oldVal > 0 ? 'diff-up' : h.newVal - h.oldVal < 0 ? 'diff-down' : ''"
                  >
                    {{ h.newVal - h.oldVal > 0 ? '+' : '' }}{{ formatVND(h.newVal - h.oldVal) }}
                    <span style="font-size: 11px; opacity: 0.85; margin-left: 3px; font-weight: 600;">
                      ({{ h.oldVal ? ((h.newVal - h.oldVal) / h.oldVal * 100).toFixed(1) : 100 }}%)
                    </span>
                  </span>
                </td>
              </tr>
            </tbody>
          </table>

          <!-- Empty state -->
          <div v-else class="history-empty">
            <div class="history-empty-icon">📋</div>
            <p class="history-empty-title">Chưa có thay đổi</p>
            <p class="history-empty-desc">Khi giá trị thay đổi, lịch sử sẽ được ghi nhận tại đây.</p>
          </div>
        </div>

        <!-- Footer -->
        <div class="history-modal-footer fullscreen-modal-footer" style="flex-shrink: 0;">
          <button class="ghost modal-btn-secondary" @click="showHistoryModal = false">Đóng</button>
        </div>
      </div>
    </div>

    <!-- VÙNG ẨN DÙNG CHUYÊN CHO IN PDF -->
    <div class="print-only">
      <table class="pdf-table">
        <thead>
          <tr>
            <th style="width: 5%">STT</th>
            <th style="width: 15%">TÊN HÀNG HÓA</th>
            <th style="width: 25%">DIỄN GIẢI</th>
            <th style="width: 5%">DVT</th>
            <th style="width: 5%">S.L</th>
            <th style="width: 10%">ĐƠN GIÁ (VND)</th>
            <th style="width: 11%">THÀNH TIỀN TRƯỚC THUẾ</th>
            <th style="width: 9%">THUẾ VAT</th>
            <th style="width: 15%">THÀNH TIỀN SAU THUẾ</th>
          </tr>
        </thead>
        <tbody>
          <template v-for="(r, idx) in quoteRowsWithSTT" :key="idx">
            <tr v-if="r.type === 'group'" class="pdf-group-row">
              <td></td>
              <td colspan="8" class="text-left"><strong>{{ r.title.toUpperCase() }}</strong></td>
            </tr>
            <tr v-else>
              <td class="text-center">{{ r.stt }}</td>
              <td><strong>{{ r.item.Ten_hang }}</strong></td>
              <td style="white-space: pre-wrap;" class="text-left" v-html="[r.item.Mo_ta_chung, r.item.Mo_ta_chi_tiet, r.item.Features].filter(Boolean).join('<br>')"></td>
              <td class="text-center">{{ r.item.DVT }}</td>
              <td class="text-center">{{ r.item.So_luong }}</td>
              <td class="text-right">{{ formatVND(unitPrice(r.item)).replace(' ₫', '') }}</td>
              <td class="text-right">{{ formatVND(lineTruocThue(r.item)).replace(' ₫', '') }}</td>
              <td class="text-right">{{ formatVND(lineVAT(r.item)).replace(' ₫', '') }}</td>
              <td class="text-right">{{ formatVND(lineSauThue(r.item)).replace(' ₫', '') }}</td>
            </tr>
          </template>
          
          <tr class="pdf-total-row">
            <td colspan="6" class="text-center"><strong>TỔNG CỘNG + THUẾ</strong></td>
            <td class="text-right"><strong>{{ formatVND(totals.truoc).replace(' ₫', '') }}</strong></td>
            <td class="text-right"><strong>{{ formatVND(totals.vat).replace(' ₫', '') }}</strong></td>
            <td class="text-right"><strong>{{ formatVND(totals.sau).replace(' ₫', '') }}</strong></td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- SELECT CUSTOMER MODAL FOR PIPELINE -->
    <div v-if="showSelectCustomerModal" class="modal" @click.self="showSelectCustomerModal = false">
    <div class="modal-card" style="max-width: 550px;">
      <div class="modal-head">
        <h3><i class="lucide-users"></i> Chọn khách hàng cho Pipeline</h3>
        <button class="x" @click="showSelectCustomerModal = false">✕</button>
      </div>
      <div class="modal-body" style="padding-top: 10px;">
        <label style="font-size: 0.85rem; font-weight: 600; color: #475569; display: block; margin-bottom: 8px;">Khách hàng hiện tại hoặc tìm kiếm:</label>
        <div style="position: relative;">
          <i class="lucide-search" style="position: absolute; left: 12px; top: 50%; transform: translateY(-50%); color: #94a3b8; font-size: 16px;"></i>
          <input 
            type="text" 
            v-model="pipelineSearchStr"
            placeholder="Nhập mã hoặc tên khách hàng..." 
            style="width: 100%; padding: 12px 12px 12px 36px; border: 1px solid #cbd5e1; border-radius: 8px; font-size: 0.95rem; box-sizing: border-box;"
          />
        </div>
        
        <div style="margin-top: 16px; height: 260px; overflow-y: auto; border: 1px solid #e2e8f0; border-radius: 8px; background: #f8fafc;">
          <template v-if="filteredPipelineCustomers.length > 0">
            <div 
              v-for="c in filteredPipelineCustomers" 
              :key="c.Ma_khach_hang"
              @click="triggerToast(`Đã chọn: ${c.Ten_khach_hang}`); selectedPipelineKhach = c"
              style="padding: 10px 14px; cursor: pointer; border-bottom: 1px solid #e2e8f0; display: flex; flex-direction: column; gap: 4px; transition: background 0.15s;"
              :style="{ background: selectedPipelineKhach?.Ma_khach_hang === c.Ma_khach_hang ? '#e0e7ff' : (filteredPipelineCustomers.length === 1 && pipelineSearchStr && !selectedPipelineKhach ? '#f1f5f9' : 'transparent') }"
            >
              <div style="font-weight: 600; color: #0f172a; font-size: 0.9rem;">{{ c.Ten_khach_hang }}</div>
              <div style="font-size: 0.75rem; color: #64748b;">Mã: {{ c.Ma_khach_hang }} • MST: {{ c.MST || '---' }}</div>
            </div>
          </template>
          <div v-else style="padding: 20px; text-align: center; color: #64748b; font-size: 0.85rem;">
            Không tìm thấy khách hàng nào.
          </div>
        </div>

        <div style="display: flex; gap: 12px; margin-top: 20px;">
          <button 
            class="ghost" 
            style="flex: 1; padding: 12px; font-size: 1rem; border-radius: 8px;"
            @click="handleAddNewPipelineCustomer"
          >
            <i class="lucide-user-plus" style="margin-right: 6px;"></i>
            Thêm mới KH
          </button>
          <button 
            class="primary" 
            style="flex: 1; padding: 12px; font-size: 1rem; border-radius: 8px;"
            @click="handleContinuePipeline"
          >
            Tiếp tục
            <i class="lucide-arrow-right" style="margin-left: 6px;"></i>
          </button>
        </div>
      </div>
    </div>
  </div>



  <PipelinePreviewModal 
    v-if="showPipelineModal" 
    :useFirebase="true"
    @close="showPipelineModal = false"
    @saved="onPipelineSaved"
    :khach="selectedPipelineKhach || khach"
    :excelMappingConfig="excelMappingConfig"
    :customers="customers"
    :soHopDong="soHopDong"
    :maHopDong="maHopDong"
    :maHopDongCu="loadedMaHopDong || ''"
    :maHopDongGoc="loadedMaHopDongGoc || ''"
    :selectedItems="selectedItems"
    :ghiChuHopDong="ghiChuHopDong"
    :contentOfContractPO="contentOfContractPO"
    :exchangeRate="pipelineExchangeRate"
    :loadedData="loadedPipelineExtraData"
    :excelBlob="pipelineExcelBlob"
    :quoteTotals="totals"
    :quoteTongGiaThucTe="tongGiaThucTe"
    :quoteFinancials="{
      chietKhauTruocThue: chietKhauTruocThue,
      chietKhauTruocThuePct: chietKhauTruocThuePct,
      thueChenhLech: thueChenhLech,
      thueChenhLechPct: thueChenhLechPct,
      chenhLechGia: chenhLechGia,
      conLai: conLai,
      tongChietKhau: tongChietKhau
    }"
  />

  <Transition name="toast-slide">
    <div v-if="showToast" class="success-toast">
      <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
        <polyline points="22 4 12 14.01 9 11.01"></polyline>
      </svg>
      <span>{{ toastMsg }}</span>
    </div>
  </Transition>

  <!-- ASYNC RESULT MODAL -->
  <Transition name="async-modal">
    <div v-if="asyncResultModal.show" class="async-overlay" @click.self="asyncResultModal.type !== 'loading' && (asyncResultModal.show = false)">
      <div class="async-card" :class="'async-' + asyncResultModal.type">
        <!-- LOADING -->
        <template v-if="asyncResultModal.type === 'loading'">
          <div class="async-spinner-wrap">
            <svg class="async-spinner" viewBox="0 0 50 50">
              <defs>
                <linearGradient id="async-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stop-color="#38bdf8"/>
                  <stop offset="50%" stop-color="#a78bfa"/>
                  <stop offset="100%" stop-color="#38bdf8"/>
                </linearGradient>
              </defs>
              <circle cx="25" cy="25" r="20" fill="none" stroke-width="4" stroke-linecap="round" stroke="url(#async-gradient)"/>
            </svg>
          </div>
          <div class="async-title">{{ asyncResultModal.title }}</div>
          <div class="async-subtitle">Vui lòng đợi trong giây lát...</div>
        </template>
        <!-- SUCCESS -->
        <template v-else-if="asyncResultModal.type === 'success'">
          <div class="async-icon-wrap async-icon-success">
            <svg viewBox="0 0 52 52" class="async-checkmark">
              <circle cx="26" cy="26" r="25" fill="none"/>
              <path fill="none" d="M14.1 27.2l7.1 7.2 16.7-16.8"/>
            </svg>
          </div>
          <div class="async-title">{{ asyncResultModal.title }}</div>
          <div v-if="asyncResultModal.msg" class="async-subtitle">{{ asyncResultModal.msg }}</div>
        </template>
        <!-- ERROR -->
        <template v-else>
          <div class="async-icon-wrap async-icon-error">
            <svg viewBox="0 0 52 52" class="async-xmark">
              <circle cx="26" cy="26" r="25" fill="none"/>
              <path fill="none" d="M16 16 36 36 M36 16 16 36"/>
            </svg>
          </div>
          <div class="async-title">{{ asyncResultModal.title }}</div>
          <div v-if="asyncResultModal.msg" class="async-subtitle">{{ asyncResultModal.msg }}</div>
          <button class="async-close-btn" @click="asyncResultModal.show = false">Đóng</button>
        </template>
      </div>
    </div>
  </Transition>

  <!-- MODAL XÁC NHẬN LƯU KHÁCH TRỐNG -->
  <div v-if="showConfirmSaveEmptyCustomer" class="modal modal-overlay" style="z-index: 10010; display: flex; align-items: center; justify-content: center;" @click.self="showConfirmSaveEmptyCustomer = false">
    <div class="modal-card" style="width: min(400px, 90vw); text-align: center; padding: 24px; border-radius: 12px; background: #1e293b; box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.3);">
      <div style="width: 64px; height: 64px; border-radius: 50%; background: rgba(245, 158, 11, 0.1); display: flex; align-items: center; justify-content: center; margin: 0 auto 16px;">
        <i class="lucide-alert-triangle" style="width: 32px; height: 32px; color: #f59e0b;"></i>
      </div>
      <h3 style="margin-bottom: 12px; color: #f8fafc; font-size: 18px; font-weight: 700;">Thiếu thông tin khách hàng!</h3>
      <p style="color: #94a3b8; font-size: 14.5px; margin-bottom: 24px; line-height: 1.5;">
        Bạn chưa nhập thông tin khách hàng. Bạn có chắc chắn muốn tiếp tục lưu báo giá với thông tin khách hàng để trống không?
      </p>
      <div style="display: flex; gap: 12px; justify-content: center;">
        <button style="flex: 1; padding: 10px 16px; border-radius: 8px; background: #334155; color: #f8fafc; border: none; font-weight: 600; cursor: pointer;" @click="showConfirmSaveEmptyCustomer = false">Huỷ</button>
        <button style="flex: 1; padding: 10px 16px; border-radius: 8px; background: #f59e0b; color: #fff; border: none; font-weight: 600; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 6px;" @click="confirmSaveEmptyCustomer()">
          <i class="lucide-check" style="width: 16px; height: 16px;"></i> Tiếp tục lưu
        </button>
      </div>
    </div>
  </div>

  <datalist id="category-list">
    <option v-for="cat in existingCategories" :key="cat" :value="cat"></option>
  </datalist>

  <datalist id="dvt-options">
    <option value="CÁI"></option>
    <option value="BẢN QUYỀN"></option>
    <option value="BỘ"></option>
    <option value="GÓI"></option>
    <option value="CHIẾC"></option>
  </datalist>



    <!-- ================== MODAL: IMAGE KIT ================== -->
    <div v-if="showImageKitModal" class="modal-overlay" @click.self="showImageKitModal = false" style="z-index: 9999;">
      <div class="modal-content" style="max-width: 1200px; width: 95vw; border-radius: 16px; overflow: hidden; display: flex; flex-direction: column; max-height: 90vh; background: #f8fafc;">
        <div class="modal-header" style="background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); padding: 16px 24px; display: flex; justify-content: space-between; align-items: center;">
          <h3 style="color: #fff; margin: 0; font-size: 18px; font-weight: 600; font-family: 'Inter', sans-serif;">Bộ Kit Cấu Hình Báo Giá</h3>
          <button class="modal-close" @click="showImageKitModal = false" style="background: rgba(255,255,255,0.1); border: none; border-radius: 50%; width: 32px; height: 32px; color: #fff; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: background 0.2s;">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
          </button>
        </div>
        
        <div style="display: flex; flex: 1; overflow: hidden;">
          <!-- Left: Controls -->
          <div style="width: 350px; background: #ffffff; border-right: 1px solid #e2e8f0; padding: 24px; overflow-y: auto;">
            <h4 style="margin: 0 0 20px 0; font-size: 16px; color: #334155;">Tùy chỉnh thông số</h4>
            
            <div style="margin-bottom: 20px;">
              <label style="display: flex; justify-content: space-between; margin-bottom: 8px; font-weight: 600; color: #475569; font-size: 14px;">
                <span>Cỡ chữ bảng (px)</span>
                <span style="color: #3b82f6;">{{ kitOptions.fontSize }}px</span>
              </label>
              <input type="range" v-model.number="kitOptions.fontSize" min="10" max="20" step="1" style="width: 100%; cursor: pointer;" />
            </div>

            <div style="margin-bottom: 20px;">
              <label style="display: flex; justify-content: space-between; margin-bottom: 8px; font-weight: 600; color: #475569; font-size: 14px;">
                <span>Khoảng cách lề (px)</span>
                <span style="color: #3b82f6;">{{ kitOptions.padding }}px</span>
              </label>
              <input type="range" v-model.number="kitOptions.padding" min="0" max="80" step="4" style="width: 100%; cursor: pointer;" />
            </div>

            <div style="margin-bottom: 20px;">
              <label style="display: flex; justify-content: space-between; margin-bottom: 8px; font-weight: 600; color: #475569; font-size: 14px;">
                <span>Độ lớn Logo (%)</span>
                <span style="color: #3b82f6;">{{ kitOptions.logoScale }}%</span>
              </label>
              <input type="range" v-model.number="kitOptions.logoScale" min="50" max="150" step="5" style="width: 100%; cursor: pointer;" />
            </div>

            <div style="margin-bottom: 20px;">
              <label style="display: flex; justify-content: space-between; margin-bottom: 8px; font-weight: 600; color: #475569; font-size: 14px;">
                <span>Khoảng cách dưới bảng (px)</span>
                <span style="color: #3b82f6;">{{ kitOptions.tableMarginBottom }}px</span>
              </label>
              <input type="range" v-model.number="kitOptions.tableMarginBottom" min="0" max="100" step="5" style="width: 100%; cursor: pointer;" />
            </div>
            
            <div style="margin-top: 40px; padding: 15px; background: #eff6ff; border-radius: 8px; border: 1px solid #bfdbfe;">
              <p style="margin: 0; font-size: 13px; color: #1e3a8a; line-height: 1.5;">
                <strong style="display: block; margin-bottom: 4px;">Lưu ý:</strong>
                Sau khi điều chỉnh cấu trúc ưng ý, bấm <strong>"Chụp & Sửa Ảnh"</strong> để chụp lại giao diện này và chuyển sang không gian vẽ, cắt xén, thêm chữ.
              </p>
            </div>
          </div>
          
          <!-- Right: Preview Container -->
          <div style="flex: 1; background: #e2e8f0; display: flex; justify-content: center; align-items: flex-start; padding: 20px; overflow: hidden; position: relative;">
            <div style="width: 100%; height: 100%; overflow: auto; display: flex; justify-content: center;">
              <!-- Mini Preview Wrapper -->
              <div style="transform-origin: top center; transform: scale(0.65); transition: transform 0.2s;">
                <!-- We duplicate the output visually, or we could just use a portal. 
                     Since exportImageContainer is already v-show="showImageKitModal" but positioned off-screen,
                     we can't easily show the real one here unless we move it. 
                     Wait, actually moving it breaks html2canvas. Let's just mirror the HTML structure here. -->
                <div style="background: #fff; width: 1100px; padding: 40px; box-shadow: 0 10px 30px rgba(0,0,0,0.1); color: #000; font-family: Arial, sans-serif;" :style="{ padding: kitOptions.padding + 'px' }">
                  <div style="display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 5px;">
                    <div style="width: 70%; transform-origin: bottom left;" :style="{ transform: `scale(${kitOptions.logoScale / 100})` }"><img src="/logo1.png" style="max-width: 100%; height: auto;" /></div>
                    <div style="width: 25%; text-align: right; transform-origin: bottom right;" :style="{ transform: `scale(${kitOptions.logoScale / 100})` }"><img src="/logo2.png" style="max-width: 100%; height: auto;" /></div>
                  </div>
                  <div style="display: flex; height: 3px; width: 100%; margin-bottom: 20px;">
                    <div style="width: 15%; background: #0070c0;"></div>
                    <div style="width: 85%; background: #ed7d31;"></div>
                  </div>
                  <table style="width: 100%; border: none; margin-bottom: 25px; border-collapse: collapse; color: #000;" :style="{ fontSize: (kitOptions.fontSize + 2) + 'px' }">
                    <tr><td style="padding: 4px 0;"><strong>Kính gởi: <span style="text-transform: uppercase;">{{ khach.Ten_cong_ty }}</span></strong></td><td style="text-align: right; font-style: italic; padding: 4px 0;">Ngày : {{ new Date().toLocaleDateString('vi-VN', {day: '2-digit', month: '2-digit', year: 'numeric'}) }}</td></tr>
                    <tr><td colspan="2" style="font-style: italic; padding: 4px 0;">Địa chỉ: {{ khach.Dia_chi_cong_ty || khach.ADDRESS || '' }}</td></tr>
                    <tr><td colspan="2" style="font-style: italic; padding: 4px 0;">Người nhận: {{ khach.Ten_khach_hang }}</td></tr>
                  </table>
                  <div style="text-align: center; margin-bottom: 8px;"><h2 style="color: #0000ff; font-weight: bold; margin: 0;" :style="{ fontSize: (kitOptions.fontSize + 5) + 'px' }">BẢNG BÁO GIÁ</h2></div>
                  <div style="margin-bottom: 8px;" :style="{ fontSize: kitOptions.fontSize + 'px' }">Công ty Nam Trường Sơn trân trọng gởi đến Quý khách hàng bảng báo giá như sau:</div>
                  <table style="width: 100%; border-collapse: collapse; table-layout: auto; color: #000;" :style="{ fontSize: kitOptions.fontSize + 'px', marginBottom: kitOptions.tableMarginBottom + 'px' }">
                    <tbody>
                      <tr style="background: #c6e0b4; font-weight: bold; text-align: center;">
                        <td v-for="(col, i) in excelMappingConfig" :key="'pimg_h' + i" style="border: 1px solid #000; padding: 6px 4px; color: #000;">{{ col.header }}</td>
                      </tr>
                      <tr v-for="r in quoteRowsWithSTT.slice(0, 5)" :key="'pimg' + r.idx" :style="r.type === 'group' ? 'background: #ffff00; font-weight: bold;' : 'background: #fff;'">
                        <td v-for="(col, i) in excelMappingConfig" :key="'pimg_c' + col.field + i" :style="{ border: '1px solid #000', padding: '6px 4px', textAlign: r.type === 'group' ? (col.field === 'stt' ? 'center' : 'left') : (['stt', 'so_luong'].includes(col.field) ? 'center' : (['don_gia', 'don_gia_kh', 'truoc_thue', 'vat', 'sau_thue', 'gia_tieu_chuan', 'don_gia_nhap'].includes(col.field) ? 'right' : 'left')), whiteSpace: 'pre-wrap' }">
                          <template v-if="r.type === 'group'">
                            <template v-if="col.field === 'stt'">{{ r.roman }}</template>
                            <template v-else-if="i === 1">{{ String(r.title).toUpperCase() }}</template>
                          </template>
                          <template v-else>
                            <div v-if="col.field === 'description' || col.field === 'features'" v-html="getPreviewCellValue(r, col.field)"></div>
                            <template v-else>{{ getPreviewCellValue(r, col.field) }}</template>
                          </template>
                        </td>
                      </tr>
                      <tr><td :colspan="excelMappingConfig.length" style="text-align: center; font-style: italic; border: 1px solid #000; padding: 10px;">(Hiển thị minh họa 5 dòng đầu...)</td></tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
        
        <div style="padding: 16px 24px; background: #fff; border-top: 1px solid #e2e8f0; display: flex; justify-content: flex-end; gap: 12px;">
          <button @click="showImageKitModal = false" style="padding: 10px 20px; font-weight: 600; border-radius: 8px; background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.background='#e2e8f0';" onmouseout="this.style.background='#f1f5f9';">Đóng</button>
          
          <button @click="exportToImage" style="padding: 10px 20px; font-weight: 600; border-radius: 8px; background: #10b981; color: #fff; border: none; cursor: pointer; display: flex; align-items: center; gap: 8px; box-shadow: 0 4px 6px -1px rgba(16, 185, 129, 0.2); transition: all 0.2s;" onmouseover="this.style.background='#059669';" onmouseout="this.style.background='#10b981';">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polygon points="16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76"></polygon></svg>
            Chụp & Sửa Ảnh
          </button>
        </div>
      </div>
    </div>

    <!-- KASPERSKY CALCULATOR MODAL -->
    <div v-if="showKasperskyCalculatorModal" class="modal-overlay" @click.self="showKasperskyCalculatorModal = false" style="z-index: 1000000; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; padding: 20px;">
      <div class="modal-content" style="max-width: 1300px; max-height: 95vh; width: 100%; border-radius: 12px; padding: 0; display: flex; flex-direction: column; background: #1e293b; border: 1px solid #334155; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.5); overflow: hidden;">
        <div style="padding: 16px 20px; border-bottom: 1px solid #334155; display: flex; justify-content: space-between; align-items: center; background: #0f172a;">
          <h3 style="margin: 0; font-size: 16px; color: #fff; font-weight: 600;">Tra cứu & Tính toán % OFF Hãng</h3>
          <button style="background: none; border: none; color: #94a3b8; cursor: pointer; font-size: 16px;" @click="showKasperskyCalculatorModal = false"><i class="fas fa-times"></i></button>
        </div>
        
        <div class="kasp-modal-body" style="display: flex; flex: 1; min-height: 450px;">
          <!-- Cột 1: Options -->
          <div class="kasp-modal-col-1" style="flex: 1; padding: 24px; border-right: 1px solid #334155; display: flex; flex-direction: column; gap: 16px; max-width: 400px; overflow-y: auto;">
            <div>
              <label style="display: block; color: #cbd5e1; font-size: 13px; margin-bottom: 8px; font-weight: 500;">Bảng giá / Option (Tên file)</label>
              <select v-model="selectedFileGiaOffIndex" style="width: 100%; padding: 10px 14px; border-radius: 8px; border: 1px solid #334155; background: #0f172a; color: #fff; outline: none; font-size: 14px;">
                <option v-for="(file, idx) in listFileGiaOff" :key="idx" :value="idx">{{ file[2] }} ({{ String(file[1]).substring(0, 10) }})</option>
              </select>
            </div>
            <div style="height: 1px; background: #334155; margin: 8px 0;"></div>
            <div>
              <label style="display: block; color: #cbd5e1; font-size: 13px; margin-bottom: 8px; font-weight: 500;">Product</label>
              <select v-model="kaspProduct" style="width: 100%; padding: 10px 14px; border-radius: 8px; border: 1px solid #334155; background: #0f172a; color: #fff; outline: none; font-size: 14px;">
                <option value="" disabled>-- Chọn Product --</option>
                <option value="NEXT Foundations / EDR Optimum">NEXT Foundations / EDR Optimum</option>
                <option value="XDR Optimum">XDR Optimum</option>
              </select>
            </div>
            <div>
              <label style="display: block; color: #cbd5e1; font-size: 13px; margin-bottom: 8px; font-weight: 500;">License Type</label>
              <select v-model="kaspLicenseType" style="width: 100%; padding: 10px 14px; border-radius: 8px; border: 1px solid #334155; background: #0f172a; color: #fff; outline: none; font-size: 14px;">
                <option value="" disabled>-- Chọn License Type --</option>
                <option value="Base Plus">Base Plus</option>
                <option value="Renewal Plus">Renewal Plus</option>
              </select>
            </div>
            <div>
              <label style="display: block; color: #cbd5e1; font-size: 13px; margin-bottom: 8px; font-weight: 500;">User (Số lượng người dùng)</label>
              <input type="number" v-model="kaspUsersStr" placeholder="Nhập số lượng user..." style="width: 100%; padding: 10px 14px; border-radius: 8px; border: 1px solid #334155; background: #0f172a; color: #fff; outline: none; font-size: 14px;" />
            </div>
            <div style="margin-bottom: auto;">
              <label style="display: block; color: #cbd5e1; font-size: 13px; margin-bottom: 8px; font-weight: 500;">Thời hạn (Năm)</label>
              <select v-model.number="kaspDuration" style="width: 100%; padding: 10px 14px; border-radius: 8px; border: 1px solid #334155; background: #0f172a; color: #fff; outline: none; font-size: 14px;">
                <option value="" disabled>-- Chọn thời hạn --</option>
                <option value="1">1 Năm (+0%)</option>
                <option value="2">2 Năm (+2%)</option>
                <option value="3">3 Năm (+3%)</option>
                <option value="4">4 Năm (+3%)</option>
                <option value="5">5 Năm (+3%)</option>
              </select>
            </div>
            
            <div style="padding: 16px; background: rgba(139,92,246,0.1); border-radius: 10px; border: 1px solid rgba(139,92,246,0.3); text-align: center;">
              <div style="font-size: 13px; color: #a78bfa; margin-bottom: 6px; font-weight: 500;">Kết quả % Off Hãng:</div>
              <div style="font-size: 32px; font-weight: 800; color: #fff;">{{ kaspCalculatedOff !== null ? kaspCalculatedOff + ' %' : '--' }}</div>
            </div>
          </div>
          
          <!-- Cột 2: Preview -->
          <div class="kasp-modal-col-2" style="flex: 2; padding: 24px; background: #0f172a; display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden;">
            <div style="color: #94a3b8; margin-bottom: 12px; font-size: 14px; font-weight: 500; align-self: flex-start;">Ảnh minh họa bảng giá</div>
            <div class="kasp-preview-box" style="width: 100%; height: 100%; min-height: 600px; border: 1px solid #334155; border-radius: 12px; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #64748b; background: rgba(0,0,0,0.2); overflow: auto;">
              <img v-if="previewImageLink" :src="previewImageLink" @click="showKasperskyImageFullscreen = true" style="max-width: 100%; display: block; cursor: pointer; transition: transform 0.2s;" onmouseover="this.style.transform='scale(1.02)';" onmouseout="this.style.transform='scale(1)';" alt="Preview" title="Nhấn để phóng to" />
              <div v-else style="text-align: center;">
                <i class="fas fa-image" style="font-size: 48px; opacity: 0.5; margin-bottom: 12px;"></i>
                <div style="font-size: 13px; opacity: 0.7;">Vui lòng chọn bảng giá ở cột bên</div>
              </div>
            </div>
          </div>
        </div>
        
        <div style="padding: 16px 24px; border-top: 1px solid #334155; display: flex; justify-content: flex-end; gap: 12px; background: #0f172a;">
          <button style="padding: 10px 20px; border-radius: 8px; border: 1px solid #334155; background: transparent; color: #cbd5e1; cursor: pointer; font-weight: 500; font-size: 14px;" @click="showKasperskyCalculatorModal = false">Hủy</button>
          <button :disabled="kaspCalculatedOff === null" :style="{ opacity: kaspCalculatedOff === null ? 0.5 : 1, cursor: kaspCalculatedOff === null ? 'not-allowed' : 'pointer', padding: '10px 20px', borderRadius: '8px', border: 'none', background: '#8b5cf6', color: '#fff', fontWeight: '600', fontSize: '14px' }" @click="applyKaspOff">Áp dụng ({{ kaspCalculatedOff !== null ? kaspCalculatedOff + '%' : '--' }})</button>
        </div>
      </div>
    </div>

    <!-- IMPORT CONFIRM MODAL (FULLSCREEN 2-COLUMN + 5-COLUMN COMPARISON TABLE) -->
    <div
      v-if="showImportConfirmModal"
      class="modal vip-modal-overlay modal-fullscreen-overlay"
      style="z-index: 10005;"
      @click.self="showImportConfirmModal = false; pendingImportItems = []"
    >
      <div class="modal-card modal-wide vip-modal-card modal-fullscreen-card import-confirm-fullscreen-card">
        <!-- HEADER -->
        <div
          class="modal-head modal-head-themed"
          style="justify-content: center; position: relative; padding: 14px 24px; border-bottom: none; border-radius: 0; flex-shrink: 0;"
        >
          <div style="color: #ffffff; text-transform: uppercase; font-weight: 900; font-size: 16px; letter-spacing: 0.5px;">
            {{
              importConfirmMode === 'mua_hang'
                ? 'KIỂM TRA HÀNG HÓA (FILE MUA HÀNG) & XÁC NHẬN LƯU DATABASE'
                : 'KIỂM TRA FILE BÁO GIÁ (KHÁCH HÀNG & HÀNG HÓA) & XÁC NHẬN LƯU DATABASE'
            }}
          </div>
          <button
            class="x"
            @click="showImportConfirmModal = false; pendingImportItems = []"
            style="color: #fff; position: absolute; right: 18px; top: 50%; transform: translateY(-50%); background: rgba(0,0,0,0.15); border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border: none; cursor: pointer;"
          >
            ✕
          </button>
        </div>

        <!-- TOP TOOLBAR: FILTER TABS + BULK ACTIONS -->
        <div
          class="cust-top-toolbar import-confirm-toolbar"
          style="padding: 10px 28px; border-bottom: 1px solid rgba(148,163,184,0.18); background: rgba(15,23,42,0.45); display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; flex-shrink: 0;"
        >
          <!-- Filter Tabs by Status -->
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <button
              type="button"
              class="import-filter-tab"
              :class="{ active: importItemFilterTab === 'all' }"
              @click="importItemFilterTab = 'all'"
            >
              <span>Tất cả</span>
              <span class="import-filter-count">{{ importConfirmStats.total }}</span>
            </button>

            <button
              type="button"
              class="import-filter-tab tab-new"
              :class="{ active: importItemFilterTab === 'new' }"
              @click="importItemFilterTab = 'new'"
            >
              <span>Hàng mới</span>
              <span class="import-filter-count">{{ importConfirmStats.newCount }}</span>
            </button>

            <button
              type="button"
              class="import-filter-tab tab-existing"
              :class="{ active: importItemFilterTab === 'existing' }"
              @click="importItemFilterTab = 'existing'"
            >
              <span>Đã có trong DB</span>
              <span class="import-filter-count">{{ importConfirmStats.existingCount }}</span>
            </button>

            <button
              type="button"
              class="import-filter-tab tab-diff"
              :class="{ active: importItemFilterTab === 'price_diff' }"
              @click="importItemFilterTab = 'price_diff'"
            >
              <span>Lệch giá DB</span>
              <span class="import-filter-count">{{ importConfirmStats.priceDiffCount }}</span>
            </button>

            <span
              v-if="importConfirmStats.existingCount > 0"
              class="import-stat-match-pill"
            >
              Khớp giá: <strong>{{ importConfirmStats.priceMatchCount }}</strong>
            </span>
          </div>

          <!-- Right Controls: Bulk Price Markup (Mua hang) + Selection Actions -->
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <!-- Bulk Markup in Mua Hang mode -->
            <div
              v-if="importConfirmMode === 'mua_hang'"
              class="import-bulk-markup-bar"
              style="display: flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 8px; background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.3);"
            >
              <span style="font-size: 11.5px; font-weight: 800; color: #10b981; white-space: nowrap;">Giá bán từ Giá vốn:</span>
              <select
                v-model="muaHangBulkMarkup.direction"
                style="padding: 4px 8px; border-radius: 6px; font-size: 11.5px; font-weight: 700; width: auto; margin: 0;"
              >
                <option value="up">+ Tăng</option>
                <option value="down">- Giảm</option>
              </select>
              <select
                v-model="muaHangBulkMarkup.mode"
                style="padding: 4px 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; width: auto; margin: 0;"
              >
                <option value="percent">Theo %</option>
                <option value="amount">Theo Số tiền</option>
              </select>
              <div style="position: relative; width: 115px;">
                <FormattedInput
                  v-model="muaHangBulkMarkup.value"
                  :placeholder="muaHangBulkMarkup.mode === 'percent' ? 'VD: 15' : 'VD: 500.000'"
                  style="width: 100%; padding: 4px 22px 4px 8px; border-radius: 6px; font-size: 12px; font-weight: 700; margin: 0;"
                />
                <span style="position: absolute; right: 7px; top: 50%; transform: translateY(-50%); font-size: 11px; opacity: 0.7; font-weight: 700; pointer-events: none;">
                  {{ muaHangBulkMarkup.mode === 'percent' ? '%' : '₫' }}
                </span>
              </div>
              <button
                type="button"
                @click="applyMuaHangBulkMarkupToPendingItems"
                style="padding: 5px 10px; border-radius: 6px; border: none; background: #10b981; color: #ffffff !important; font-size: 11.5px; font-weight: 800; cursor: pointer; width: fit-content; margin: 0; white-space: nowrap;"
              >
                Áp dụng
              </button>
              <button
                v-if="lastMuaHangImportFile"
                type="button"
                @click="runAiMuaHangAnalysis(lastMuaHangImportFile)"
                style="padding: 5px 10px; border-radius: 6px; border: 1px solid rgba(139, 92, 246, 0.5); background: #7c3aed; color: #ffffff !important; font-size: 11.5px; font-weight: 700; cursor: pointer; width: fit-content; margin: 0; white-space: nowrap;"
                title="Phân tích lại file mua hàng bằng AI"
              >
                Phân tích lại bằng AI
              </button>
            </div>

            <!-- Batch Checkbox Controls -->
            <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
              <button
                type="button"
                class="import-batch-btn batch-new"
                @click="selectOnlyNewImportItems()"
              >
                Chỉ tích Hàng mới ({{ importConfirmStats.newCount }})
              </button>
              <button
                type="button"
                class="import-batch-btn"
                @click="toggleAllImportSave(true)"
              >
                Tích chọn tất cả
              </button>
              <button
                type="button"
                class="import-batch-btn"
                @click="toggleAllImportSave(false)"
              >
                Bỏ chọn tất cả
              </button>
            </div>
          </div>
        </div>

        <!-- MAIN WORKSPACE: 2-COLUMN SPLIT (CUSTOMER LEFT + PRODUCT TABLE RIGHT) -->
        <div
          class="import-confirm-workspace"
          :style="{
            flex: 1,
            minHeight: 0,
            overflow: 'hidden',
            padding: '18px 28px',
            display: 'grid',
            gridTemplateColumns: importConfirmMode === 'bao_gia' ? '360px minmax(0, 1fr)' : 'minmax(0, 1fr)',
            gap: '20px'
          }"
        >
          <!-- LEFT COLUMN: CUSTOMER INFO PANEL (ONLY IN BAO GIA MODE) -->
          <div
            v-if="importConfirmMode === 'bao_gia'"
            class="cust-group-box import-cust-panel"
            style="border-radius: 12px; padding: 16px 18px; display: flex; flex-direction: column; gap: 12px; min-height: 0; overflow-y: auto;"
          >
            <!-- Panel Header + Status Badge -->
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap;">
              <span class="import-panel-title" style="font-size: 12px; font-weight: 900; text-transform: uppercase; letter-spacing: 0.5px;">
                THÔNG TIN KHÁCH HÀNG
              </span>

              <span
                v-if="!isCustomerInDB && (khach.Ten_cong_ty || khach.Ten_khach_hang || khach.MST || maKHInput)"
                class="import-cust-badge badge-amber"
              >
                Khách hàng mới
              </span>
              <span
                v-else-if="isCustomerInDB && showSaveToDBBtn"
                class="import-cust-badge badge-blue"
              >
                Đã có trong DB — Có TT mới
              </span>
              <span
                v-else-if="isCustomerInDB"
                class="import-cust-badge badge-emerald"
              >
                Đã khớp DB ({{ maKHInput || khach.Ma_khach_hang }})
              </span>
              <span
                v-else
                class="import-cust-badge badge-slate"
              >
                Chưa có TT trong file
              </span>
            </div>

            <!-- Concise Status Note -->
            <div class="import-cust-note" style="font-size: 12px; line-height: 1.45; padding: 8px 10px; border-radius: 8px;">
              <template v-if="!isCustomerInDB && (khach.Ten_cong_ty || khach.Ten_khach_hang || khach.MST || maKHInput)">
                Khách hàng <strong>{{ khach.Ten_cong_ty || khach.Ten_khach_hang || maKHInput }}</strong> chưa có trong Database. Bạn có thể kiểm tra thông tin bên dưới hoặc bấm nút <strong>Chọn</strong> trong từng ô để gán KH có sẵn.
              </template>
              <template v-else-if="isCustomerInDB && showSaveToDBBtn">
                Khách hàng <strong>{{ khach.Ten_cong_ty || khach.Ten_khach_hang || maKHInput }}</strong> đã có trong DB nhưng thông tin từ file có cập nhật mới.
              </template>
              <template v-else-if="isCustomerInDB">
                Đã tự động nhận diện và khớp với khách hàng <strong>[{{ maKHInput || khach.Ma_khach_hang }}] {{ khach.Ten_khach_hang || khach.Ten_cong_ty }}</strong> trong Database.
              </template>
              <template v-else>
                File không chứa thông tin khách hàng. Bạn có thể bấm nút <strong>Chọn</strong> ở các ô bên dưới hoặc nhập mới.
              </template>
            </div>

            <!-- Quick Customer Header Actions -->
            <div style="display: flex; flex-wrap: wrap; gap: 6px;">
              <button
                type="button"
                class="import-cust-action-btn btn-emerald"
                @click="startNewCustomerInImportModal()"
              >
                + Tạo mã KH mới
              </button>
              <button
                type="button"
                class="import-cust-action-btn btn-slate"
                @click="showCustomerDetailModal = true"
              >
                Mở bảng KH đầy đủ
              </button>
              <button
                v-if="showSaveToDBBtn"
                type="button"
                class="import-cust-action-btn btn-save-now"
                :disabled="savingCustomer"
                @click="saveCustomerToDB(false)"
              >
                {{ savingCustomer ? 'Đang lưu...' : (isCustomerInDB ? 'Lưu cập nhật KH ngay' : 'Lưu KH vào DB ngay') }}
              </button>
            </div>

            <!-- Always-visible Structured Customer Inputs with Inline Picker Buttons -->
            <div style="display: flex; flex-direction: column; gap: 10px; flex: 1;">
              <div style="display: flex; flex-direction: column; gap: 4px;">
                <label class="import-field-label">Mã Khách Hàng *</label>
                <div class="input-with-picker">
                  <input
                    v-model="maKHInput"
                    placeholder="Tự tạo hoặc nhập mã KH..."
                    @change="fillCustomerByMa(maKHInput)"
                    style="width: 100%; padding: 8px 58px 8px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 700; margin: 0;"
                  />
                  <button type="button" class="inline-picker-btn inline-picker-btn-sm" @click="openCustomerPicker('ma_kh')">Chọn</button>
                </div>
              </div>

              <div style="display: flex; flex-direction: column; gap: 4px;">
                <label class="import-field-label">Người nhận (Tên KH)</label>
                <div class="input-with-picker">
                  <input
                    v-model="tenKHInput"
                    placeholder="Tên người nhận / liên hệ..."
                    @change="fillCustomerByTen(tenKHInput)"
                    style="width: 100%; padding: 8px 58px 8px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 600; margin: 0;"
                  />
                  <button type="button" class="inline-picker-btn inline-picker-btn-sm" @click="openCustomerPicker('ten_kh')">Chọn</button>
                </div>
              </div>

              <div style="display: flex; flex-direction: column; gap: 4px;">
                <label class="import-field-label">Tên Công ty</label>
                <div class="input-with-picker">
                  <input
                    v-model="khach.Ten_cong_ty"
                    placeholder="Tên công ty..."
                    @change="fillCustomerByCongTy(khach.Ten_cong_ty)"
                    style="width: 100%; padding: 8px 58px 8px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 700; margin: 0;"
                  />
                  <button type="button" class="inline-picker-btn inline-picker-btn-sm" @click="openCustomerPicker('ten_cong_ty')">Chọn</button>
                </div>
              </div>

              <div style="display: flex; flex-direction: column; gap: 4px;">
                <label class="import-field-label">Mã số thuế (MST)</label>
                <div class="input-with-picker">
                  <input
                    v-model="khach.MST"
                    placeholder="Mã số thuế..."
                    @change="onMSTChange"
                    style="width: 100%; padding: 8px 58px 8px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 600; margin: 0;"
                  />
                  <button type="button" class="inline-picker-btn inline-picker-btn-sm" @click="openCustomerPicker('mst')">Chọn</button>
                </div>
              </div>

              <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
                <div style="display: flex; flex-direction: column; gap: 4px;">
                  <label class="import-field-label">Số điện thoại</label>
                  <input
                    v-model="khach.So_dien_thoai_ca_nhan"
                    placeholder="SĐT liên hệ..."
                    style="width: 100%; padding: 8px 10px; border-radius: 7px; font-size: 12.5px; margin: 0;"
                  />
                </div>
                <div style="display: flex; flex-direction: column; gap: 4px;">
                  <label class="import-field-label">Email</label>
                  <input
                    v-model="khach.Email_ca_nhan"
                    placeholder="Email..."
                    style="width: 100%; padding: 8px 10px; border-radius: 7px; font-size: 12.5px; margin: 0;"
                  />
                </div>
              </div>

              <div style="display: flex; flex-direction: column; gap: 4px;">
                <label class="import-field-label">Địa chỉ công ty</label>
                <input
                  v-model="khach.Dia_chi_cong_ty"
                  placeholder="Địa chỉ công ty..."
                  style="width: 100%; padding: 8px 10px; border-radius: 7px; font-size: 12.5px; margin: 0;"
                />
              </div>
            </div>

            <!-- Auto-save Customer Checkbox -->
            <div
              v-if="showSaveToDBBtn && (khach.Ten_cong_ty || khach.Ten_khach_hang || khach.MST || maKHInput)"
              class="import-cust-autosave-box"
              style="margin-top: auto; padding: 10px 12px; border-radius: 8px;"
            >
              <label style="display: flex; align-items: flex-start; gap: 8px; font-size: 12px; cursor: pointer; font-weight: 700; margin: 0; line-height: 1.4;">
                <input
                  type="checkbox"
                  v-model="saveImportedCustomerOnConfirm"
                  style="width: 16px; height: 16px; margin-top: 1px; accent-color: #10b981; cursor: pointer; flex-shrink: 0;"
                />
                <span>
                  Tự động <strong>{{ isCustomerInDB ? 'cập nhật thông tin Khách hàng' : 'lưu Khách hàng mới này' }}</strong> vào Database khi xác nhận
                </span>
              </label>
            </div>
          </div>

          <!-- RIGHT COLUMN: FLAT EXCEL-STYLE PRODUCT COMPARISON TABLE -->
          <div
            class="cust-group-box import-table-panel"
            style="border-radius: 12px; padding: 0; display: flex; flex-direction: column; min-height: 0; overflow: hidden;"
          >
            <div style="flex: 1; min-height: 0; overflow: auto;">
              <table class="import-compare-table">
                <colgroup>
                  <col style="width: 48px;" />
                  <col style="width: 48px;" />
                  <col />
                  <col />
                  <col style="width: 90px;" />
                  <col style="width: 132px;" />
                  <col v-if="importConfirmMode === 'mua_hang'" style="width: 132px;" />
                  <col style="width: 195px;" />
                </colgroup>
                <thead>
                  <tr>
                    <th class="col-imp-check">Lưu</th>
                    <th class="col-imp-stt">STT</th>
                    <th class="col-imp-name">Mặt hàng Import</th>
                    <th class="col-imp-db-name">Mặt hàng trong DB</th>
                    <th class="col-imp-qty">SL</th>
                    <th class="col-imp-price">Đơn giá</th>
                    <th v-if="importConfirmMode === 'mua_hang'" class="col-imp-price">Giá vốn</th>
                    <th class="col-imp-status">Trạng thái DB</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-if="filteredPendingImportItems.length === 0">
                    <td :colspan="importConfirmMode === 'mua_hang' ? 8 : 7" style="padding: 42px 16px !important; text-align: center !important; font-weight: 600; opacity: 0.75;">
                      Không có mặt hàng nào trong bộ lọc này.
                    </td>
                  </tr>
                  <tr
                    v-for="{ it, originalIdx } in filteredPendingImportItems"
                    :key="it.uid || originalIdx"
                    class="import-compare-row"
                  >
                    <!-- COL 1: CHECKBOX -->
                    <td class="col-imp-check">
                      <input
                        type="checkbox"
                        v-model="it._saveToDb"
                        style="width: 16px; height: 16px; accent-color: #10b981; cursor: pointer; margin: 0; vertical-align: middle;"
                        title="Tích để lưu mặt hàng này vào Database"
                      />
                    </td>

                    <!-- COL 2: STT -->
                    <td class="col-imp-stt" style="font-weight: 700; opacity: 0.75;">
                      {{ originalIdx + 1 }}
                    </td>

                    <!-- COL 3: IMPORTED PRODUCT NAME & CODE (FROM FILE) -->
                    <td class="col-imp-name">
                      <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
                        <div style="min-width: 0; flex: 1;">
                          <div
                            style="font-weight: 700; font-size: 13px; line-height: 1.35; cursor: pointer;"
                            @click="it._saveToDb = !it._saveToDb"
                          >
                            {{ it._initialTenHang || it.Ten_hang }}
                          </div>
                          <div v-if="it._initialMaHang || it.Ma_hang" style="font-size: 11px; color: #0284c7; font-weight: 700; margin-top: 2px;">
                            Mã: {{ it._initialMaHang || it.Ma_hang }}
                          </div>
                        </div>

                        <button
                          v-if="it.Features"
                          type="button"
                          class="import-features-toggle-btn"
                          @click.stop="activeImportRowForDescPreview = it"
                        >
                          Xem mô tả
                        </button>
                      </div>
                    </td>

                    <!-- COL 4: MATCHED PRODUCT IN DB + PICKER BUTTON -->
                    <td class="col-imp-db-name">
                      <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
                        <div v-if="it._dbMatch?.exists && it._dbMatch?.dbProduct" style="min-width: 0; flex: 1;">
                          <div style="font-weight: 700; font-size: 13px; line-height: 1.35;">
                            {{ it._dbMatch.dbProduct.Ten_hang }}
                          </div>
                          <div v-if="it._dbMatch.dbProduct.Ma_hang" style="font-size: 11px; color: #10b981; font-weight: 700; margin-top: 2px;">
                            Mã DB: {{ it._dbMatch.dbProduct.Ma_hang }}
                          </div>
                        </div>
                        <div v-else style="min-width: 0; flex: 1; font-size: 12px; opacity: 0.6; font-style: italic;">
                          Chưa có trong DB
                        </div>

                        <button
                          type="button"
                          class="import-candidate-trigger-btn"
                          style="flex-shrink: 0;"
                          @click.stop="openImportRowDbPicker(it)"
                        >
                          {{ it._dbMatch?.exists ? 'Đổi SP' : 'Chọn SP khớp' }}
                        </button>
                      </div>
                    </td>

                    <!-- COL 5: QUANTITY & UNIT -->
                    <td class="col-imp-qty" style="font-weight: 600; font-size: 12.5px;">
                      {{ it.So_luong }} {{ it.DVT || '' }}
                    </td>

                    <!-- COL 6: UNIT PRICE (CLEAN IMPORTED PRICE ONLY) -->
                    <td class="col-imp-price">
                      <div style="font-size: 13px; font-weight: 800; color: #0284c7;">
                        {{ formatVND(it.Don_gia) }}
                      </div>
                    </td>

                    <!-- COL 7: COST PRICE (ONLY IN MUA HANG MODE) -->
                    <td v-if="importConfirmMode === 'mua_hang'" class="col-imp-price">
                      <div style="font-size: 13px; font-weight: 800; color: #d97706;">
                        {{ formatVND(it.Gia_tieu_chuan) }}
                      </div>
                    </td>

                    <!-- COL 8: DB STATUS BADGE + DB PRICE -->
                    <td class="col-imp-status">
                      <div style="display: flex; flex-direction: column; align-items: flex-start; gap: 3px; min-width: 0;">
                        <span
                          v-if="!it._dbMatch?.exists"
                          class="import-match-badge badge-new"
                        >
                          Hàng mới
                        </span>
                        <span
                          v-else-if="importConfirmMode === 'mua_hang' ? (it._dbMatch.isPriceMatch && it._dbMatch.isStandardPriceMatch) : it._dbMatch.isPriceMatch"
                          class="import-match-badge badge-existing"
                        >
                          Đã khớp DB
                        </span>
                        <span
                          v-else
                          class="import-match-badge badge-diff-warn"
                        >
                          Lệch giá DB
                        </span>

                        <div
                          v-if="it._dbMatch?.exists"
                          style="font-size: 11px; font-weight: 700; line-height: 1.25; white-space: nowrap;"
                          :style="{ color: it._dbMatch.isPriceMatch ? '#10b981' : '#d97706' }"
                        >
                          DB: {{ formatVND(it._dbMatch.dbUnitPrice) }}
                          <template v-if="!it._dbMatch.isPriceMatch">
                            ({{ it._dbMatch.priceDiff > 0 ? '+' : '' }}{{ formatVND(it._dbMatch.priceDiff) }})
                          </template>
                        </div>

                        <div
                          v-if="importConfirmMode === 'mua_hang' && it._dbMatch?.exists && !it._dbMatch?.isStandardPriceMatch"
                          style="font-size: 11px; font-weight: 700; color: #ef4444; line-height: 1.25; white-space: nowrap;"
                        >
                          Vốn DB: {{ formatVND(it._dbMatch.dbStandardPrice) }} ({{ it._dbMatch.standardPriceDiff > 0 ? '+' : '' }}{{ formatVND(it._dbMatch.standardPriceDiff) }})
                        </div>
                      </div>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <!-- FOOTER -->
        <div
          class="cust-modal-footer fullscreen-modal-footer"
          style="padding: 12px 28px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; flex-shrink: 0; border-radius: 0 !important;"
        >
          <div style="font-size: 12px; opacity: 0.85; flex: 1; min-width: 260px; line-height: 1.4;">
            <template v-if="importConfirmMode === 'mua_hang'">
              Mặc định chỉ tích lưu <strong>Hàng mới</strong> vào DB.
              {{
                selectedItems.length === 0
                  ? `Bảng báo giá đang trống: toàn bộ ${importConfirmStats.total} mặt hàng sẽ được thêm vào báo giá.`
                  : `Bảng báo giá đang có ${selectedItems.length} mặt hàng: hệ thống sẽ cập nhật giá cho các mặt hàng tương ứng.`
              }}
            </template>
            <template v-else>
              Mặc định chỉ tích lưu <strong>Hàng mới</strong> vào DB và bỏ qua hàng đã có sẵn. Toàn bộ <strong>{{ importConfirmStats.total }}</strong> mặt hàng vẫn được đưa vào bảng báo giá hiện tại.
            </template>
          </div>

          <div style="display: flex; gap: 10px; align-items: center; flex-wrap: wrap;">
            <button
              type="button"
              class="modal-btn-secondary"
              style="padding: 10px 20px; border-radius: 8px; font-weight: 700; font-size: 13px; cursor: pointer; width: fit-content; margin: 0;"
              @click="showImportConfirmModal = false; pendingImportItems = []"
            >
              Hủy bỏ
            </button>
            <button
              type="button"
              style="background: #2563eb; color: #ffffff !important; padding: 10px 18px; border: none; border-radius: 8px; font-weight: 800; font-size: 13px; cursor: pointer; width: fit-content; margin: 0;"
              @click="confirmImport(false)"
            >
              {{ importConfirmMode === 'mua_hang' && selectedItems.length > 0 ? 'Chỉ cập nhật giá Báo giá (Không lưu DB)' : 'Chỉ đưa vào Báo giá (Không lưu DB)' }}
            </button>
            <button
              type="button"
              class="primary action-success"
              style="background: linear-gradient(135deg, #10b981, #059669); color: #ffffff !important; padding: 10px 20px; border: none; border-radius: 8px; font-weight: 800; font-size: 13px; cursor: pointer; width: fit-content; margin: 0; box-shadow: 0 3px 10px rgba(16, 185, 129, 0.3);"
              @click="confirmImport(true)"
            >
              {{
                importConfirmMode === 'mua_hang' && selectedItems.length > 0
                  ? `Cập nhật Báo giá & Lưu ${importConfirmStats.selectedSaveCount} SP vào DB`
                  : `Đưa vào Báo giá & Lưu ${importConfirmStats.selectedSaveCount} SP${importConfirmMode === 'bao_gia' && saveImportedCustomerOnConfirm && showSaveToDBBtn ? ' + Khách hàng' : ''} vào DB`
              }}
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- POPUP CHỌN / ĐỔI SẢN PHẨM KHỚP TRONG DB CHO DÒNG IMPORT -->
    <div
      v-if="showImportConfirmModal && activeImportRowForDbPicker"
      class="modal"
      style="z-index: 10020;"
      @click.self="closeImportRowDbPicker()"
    >
      <div class="modal-card picker-modal-card" style="width: 720px; max-width: 94vw; height: 74vh; max-height: 660px; border-radius: 14px; display: flex; flex-direction: column; padding: 0; overflow: hidden;">
        <!-- HEADER -->
        <div class="modal-head" style="padding: 14px 20px; border-bottom: 1px solid rgba(255,255,255,0.08); position: relative; flex-shrink: 0;">
          <h3 style="margin: 0; font-size: 14.5px; font-weight: 800; color: #ffffff !important; letter-spacing: 0.4px; text-transform: uppercase;">
            CHỌN / ĐỔI SẢN PHẨM KHỚP TRONG DATABASE
          </h3>
          <button class="x" @click="closeImportRowDbPicker()">✕</button>
        </div>

        <!-- SUBHEADER: CURRENT IMPORTED ROW + SEARCH BAR -->
        <div class="cust-top-toolbar" style="padding: 12px 20px; border-bottom: 1px solid rgba(148,163,184,0.16); background: rgba(15,23,42,0.35); display: flex; flex-direction: column; gap: 10px; flex-shrink: 0;">
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; font-size: 12.5px;">
            <div style="min-width: 0; flex: 1;">
              <span style="opacity: 0.75; font-weight: 600;">Mặt hàng Import: </span>
              <strong style="color: #0284c7;" v-if="activeImportRowForDbPicker.Ma_hang">[{{ activeImportRowForDbPicker.Ma_hang }}] </strong>
              <strong>{{ activeImportRowForDbPicker.Ten_hang }}</strong>
            </div>
            <button
              type="button"
              style="padding: 6px 12px; border-radius: 7px; font-size: 11.5px; font-weight: 800; background: #10b981; color: #ffffff !important; border: none; cursor: pointer; width: fit-content; margin: 0; white-space: nowrap;"
              @click="selectRelatedDbProductForImportItem(activeImportRowForDbPicker, null)"
            >
              Đánh dấu là Hàng mới (Không khớp DB)
            </button>
          </div>

          <div style="display: flex; align-items: center; gap: 8px;">
            <input
              v-model="activeImportRowForDbPicker._relatedSearchQuery"
              type="text"
              placeholder="Tìm sản phẩm trong Database theo Mã hàng hoặc Tên hàng..."
              style="flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 13px; font-weight: 600; margin: 0;"
            />
            <button
              v-if="activeImportRowForDbPicker._relatedSearchQuery"
              type="button"
              @click="activeImportRowForDbPicker._relatedSearchQuery = ''"
              style="padding: 8px 12px; border-radius: 7px; font-size: 12px; font-weight: 700; background: #64748b; color: #ffffff !important; border: none; cursor: pointer; width: fit-content; margin: 0;"
            >
              Xóa
            </button>
          </div>
        </div>

        <!-- CANDIDATES LIST -->
        <div style="padding: 14px 20px; flex: 1; min-height: 0; overflow: hidden; display: flex; flex-direction: column;">
          <div class="picker-table-box" style="flex: 1; min-height: 0; overflow: auto; border-radius: 10px; border: 1px solid rgba(148,163,184,0.2);">
            <table class="picker-data-table" style="width: 100%; border-collapse: collapse; font-size: 12.5px;">
              <thead>
                <tr>
                  <th style="width: 48px; text-align: center;">STT</th>
                  <th style="text-align: left;">Sản phẩm trong Database</th>
                  <th style="width: 145px; text-align: right;">Đơn giá DB</th>
                  <th v-if="importConfirmMode === 'mua_hang'" style="width: 135px; text-align: right;">Giá vốn DB</th>
                  <th style="width: 96px; text-align: center;">Thao tác</th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="getFilteredRelatedCandidates(activeImportRowForDbPicker).length === 0">
                  <td :colspan="importConfirmMode === 'mua_hang' ? 5 : 4" style="padding: 36px 16px; text-align: center; font-weight: 600; opacity: 0.75;">
                    Không tìm thấy sản phẩm phù hợp trong Database. Bạn có thể gõ từ khóa khác hoặc bấm "Đánh dấu là Hàng mới".
                  </td>
                </tr>
                <tr
                  v-for="(cand, cIdx) in getFilteredRelatedCandidates(activeImportRowForDbPicker)"
                  :key="(cand.product.Ma_hang || '') + '_' + cIdx"
                  class="picker-row"
                  :class="{
                    'picker-row-selected':
                      activeImportRowForDbPicker._dbMatch?.exists &&
                      activeImportRowForDbPicker._dbMatch?.dbProduct?.Ma_hang === cand.product.Ma_hang &&
                      activeImportRowForDbPicker._dbMatch?.dbProduct?.Ten_hang === cand.product.Ten_hang
                  }"
                  @click="selectRelatedDbProductForImportItem(activeImportRowForDbPicker, cand)"
                >
                  <td style="text-align: center; font-weight: 700; opacity: 0.75;">{{ cIdx + 1 }}</td>
                  <td>
                    <div style="font-weight: 700; font-size: 13px;">
                      <span v-if="cand.product.Ma_hang" style="color: #0284c7; margin-right: 4px;">[{{ cand.product.Ma_hang }}]</span>
                      <span>{{ cand.product.Ten_hang }}</span>
                    </div>
                    <div style="font-size: 11px; opacity: 0.75; margin-top: 2px;">
                      {{ cand.matchReason }}
                    </div>
                  </td>
                  <td style="text-align: right; font-weight: 800; color: #0284c7; white-space: nowrap;">
                    {{ formatVND(cand.dbUnitPrice) }}
                  </td>
                  <td v-if="importConfirmMode === 'mua_hang'" style="text-align: right; font-weight: 700; color: #d97706; white-space: nowrap;">
                    {{ formatVND(cand.dbStandardPrice) }}
                  </td>
                  <td style="text-align: center;" @click.stop>
                    <button
                      type="button"
                      class="picker-select-action-btn"
                      @click="selectRelatedDbProductForImportItem(activeImportRowForDbPicker, cand)"
                    >
                      {{
                        activeImportRowForDbPicker._dbMatch?.exists &&
                        activeImportRowForDbPicker._dbMatch?.dbProduct?.Ma_hang === cand.product.Ma_hang &&
                        activeImportRowForDbPicker._dbMatch?.dbProduct?.Ten_hang === cand.product.Ten_hang
                          ? 'Đang chọn'
                          : 'Chọn'
                      }}
                    </button>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <!-- FOOTER -->
        <div class="cust-modal-footer" style="padding: 10px 20px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; justify-content: flex-end; align-items: center; gap: 10px; flex-shrink: 0;">
          <button
            type="button"
            class="modal-btn-secondary"
            @click="closeImportRowDbPicker()"
            style="padding: 8px 20px; border-radius: 8px; font-weight: 700; font-size: 13px; color: #fff; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); cursor: pointer; width: fit-content; margin: 0;"
          >
            Đóng
          </button>
        </div>
      </div>
    </div>

    <!-- POPUP XEM MÔ TẢ / THÔNG SỐ DÒNG IMPORT -->
    <div
      v-if="showImportConfirmModal && activeImportRowForDescPreview"
      class="modal"
      style="z-index: 10021;"
      @click.self="activeImportRowForDescPreview = null"
    >
      <div class="modal-card picker-modal-card" style="width: 600px; max-width: 92vw; max-height: 75vh; border-radius: 14px; display: flex; flex-direction: column; padding: 0; overflow: hidden;">
        <div class="modal-head" style="padding: 14px 20px; border-bottom: 1px solid rgba(255,255,255,0.08); position: relative; flex-shrink: 0;">
          <h3 style="margin: 0; font-size: 14px; font-weight: 800; color: #ffffff !important; letter-spacing: 0.4px; text-transform: uppercase;">
            MÔ TẢ / DIỄN GIẢI — {{ activeImportRowForDescPreview.Ten_hang }}
          </h3>
          <button class="x" @click="activeImportRowForDescPreview = null">✕</button>
        </div>
        <div style="padding: 18px 22px; overflow-y: auto; flex: 1; font-size: 13px; line-height: 1.55; white-space: pre-wrap;" v-html="activeImportRowForDescPreview.Features"></div>
        <div class="cust-modal-footer" style="padding: 10px 20px; border-top: 1px solid rgba(255,255,255,0.08); background: rgba(15, 23, 42, 0.95); display: flex; justify-content: flex-end; flex-shrink: 0;">
          <button
            type="button"
            class="modal-btn-secondary"
            @click="activeImportRowForDescPreview = null"
            style="padding: 8px 20px; border-radius: 8px; font-weight: 700; font-size: 13px; color: #fff; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); cursor: pointer; width: fit-content; margin: 0;"
          >
            Đóng
          </button>
        </div>
      </div>
    </div>

    <!-- AI PURCHASE FALLBACK PROMPT MODAL -->
    <div class="modal" v-if="aiMuaHangFallbackModal.show" style="z-index: 10010;" @click.self="aiMuaHangFallbackModal.show = false">
      <div class="modal-card" style="max-width: 480px; width: 92vw; padding: 24px;">
        <h3 style="display: flex; align-items: center; gap: 8px; color: #a78bfa; margin-bottom: 12px;">
          ✨ Không đọc được Giá vốn — Dùng AI phân tích?
        </h3>
        <p style="font-size: 13.5px; color: #cbd5e1; line-height: 1.55; margin-bottom: 12px;">
          {{ aiMuaHangFallbackModal.reason }}
        </p>
        <div style="padding: 12px; border-radius: 8px; background: rgba(139, 92, 246, 0.1); border: 1px solid rgba(139, 92, 246, 0.3); color: #e2e8f0; font-size: 13px; line-height: 1.5; margin-bottom: 18px;">
          Bạn có muốn dùng <strong>AI</strong> để phân tích nội dung file <strong style="color: #c4b5fd;">{{ aiMuaHangFallbackModal.file?.name }}</strong>, tự động nhận diện bảng hàng hóa và tính <strong>Giá vốn / Giá off hãng (sau thuế VAT)</strong> không?
        </div>
        <div style="display: flex; gap: 10px; justify-content: flex-end;">
          <button
            type="button"
            style="background: #475569; color: #fff; padding: 8px 16px; border: none; border-radius: 6px; cursor: pointer;"
            @click="aiMuaHangFallbackModal.show = false"
          >
            Đóng
          </button>
          <button
            type="button"
            style="background: linear-gradient(135deg, #8b5cf6, #6d28d9); color: #fff; padding: 8px 16px; border: none; border-radius: 6px; font-weight: 700; cursor: pointer;"
            @click="confirmAiMuaHangFallback"
          >
            ✨ Dùng AI phân tích ngay
          </button>
        </div>
      </div>
    </div>

    <!-- KASPERSKY IMAGE FULLSCREEN MODAL -->
    <div v-if="showKasperskyImageFullscreen && previewImageLink" class="modal-overlay" @click.self="showKasperskyImageFullscreen = false" style="z-index: 1000001; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.9); display: flex; align-items: center; justify-content: center; padding: 20px;">
      <div style="position: relative; max-width: 95vw; max-height: 95vh; display: flex; justify-content: center; align-items: center;">
        <button style="position: absolute; top: -40px; right: 0; background: none; border: none; color: #fff; cursor: pointer; font-size: 24px; z-index: 10;" @click="showKasperskyImageFullscreen = false" title="Đóng"><i class="fas fa-times"></i></button>
        <img :src="previewImageLink" style="max-width: 100%; max-height: 90vh; border-radius: 8px; box-shadow: 0 0 40px rgba(0,0,0,0.5);" />
      </div>
    </div>

    <!-- ================== MODAL BÁO GIÁ BẰNG GIỌNG NÓI ================== -->
    <div v-if="showVoiceQuoteModal" class="modal-overlay" @click.self="closeVoiceQuoteModal" style="z-index: 100020; position: fixed; inset: 0; background: rgba(0, 0, 0, 0.7); display: flex; align-items: center; justify-content: center; padding: 16px;">
      <div class="modal-content" style="width: 100%; max-width: 820px; max-height: 90vh; background: #1e293b; border: 1px solid #334155; border-radius: 12px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.5); display: flex; flex-direction: column; overflow: hidden; color: #f8fafc;">
        <!-- Header -->
        <div style="padding: 14px 20px; background: #0f172a; border-bottom: 1px solid #334155; display: flex; align-items: center; justify-content: space-between; gap: 12px;">
          <h3 style="margin: 0; font-size: 15px; font-weight: 700; color: #ffffff; display: flex; align-items: center; gap: 8px;">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"></path><path d="M19 10v2a7 7 0 0 1-14 0v-2"></path><line x1="12" x2="12" y1="19" y2="22"></line></svg>
            Báo giá bằng giọng nói
          </h3>
          <button @click="closeVoiceQuoteModal" style="background: none; border: none; color: #94a3b8; cursor: pointer; font-size: 16px; padding: 4px;" title="Đóng">✕</button>
        </div>

        <!-- Body -->
        <div style="padding: 20px; overflow-y: auto; -webkit-overflow-scrolling: touch; flex: 1; display: flex; flex-direction: column; gap: 16px;">
          <!-- Thông báo lỗi (nếu có) -->
          <div v-if="voiceErrorMsg" style="padding: 10px 14px; border-radius: 8px; background: rgba(245, 158, 11, 0.12); border: 1px solid rgba(245, 158, 11, 0.35); color: #fde68a; font-size: 12.5px; display: flex; align-items: center; justify-content: space-between; gap: 10px;">
            <span>{{ voiceErrorMsg }}</span>
            <button @click="voiceErrorMsg = ''" style="background: transparent; border: none; color: #fde68a; cursor: pointer; font-weight: 700;">✕</button>
          </div>

          <!-- BƯỚC 1: GHI ÂM & XÁC NHẬN VĂN BẢN -->
          <div v-if="voiceQuoteStep === 1" style="display: flex; flex-direction: column; gap: 16px;">
            <div style="padding: 16px; border-radius: 8px; background: #0f172a; border: 1px solid #334155; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;">
              <div style="display: flex; align-items: center; gap: 14px; flex: 1; min-width: 240px;">
                <button
                  type="button"
                  @click="toggleVoiceRecording"
                  :style="{
                    width: '46px',
                    height: '46px',
                    borderRadius: '8px',
                    border: 'none',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: '#fff',
                    flexShrink: 0,
                    background: isVoiceListening ? '#ef4444' : '#10b981',
                    boxShadow: isVoiceListening ? '0 0 0 4px rgba(239, 68, 68, 0.25)' : 'none',
                    transition: 'all 0.2s'
                  }"
                  :title="isVoiceListening ? 'Dừng thu âm' : 'Bắt đầu thu âm'"
                >
                  <svg v-if="!isVoiceListening" xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"></path><path d="M19 10v2a7 7 0 0 1-14 0v-2"></path><line x1="12" x2="12" y1="19" y2="22"></line><line x1="8" x2="16" y1="22" y2="22"></line></svg>
                  <svg v-else xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="#ffffff" stroke="#ffffff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="6" width="12" height="12" rx="2"></rect></svg>
                </button>
                <div>
                  <div style="font-size: 13.5px; font-weight: 600;" :style="{ color: isVoiceListening ? '#fca5a5' : '#f8fafc' }">
                    {{ isVoiceListening ? 'Đang nghe... Nhấn lần nữa để dừng' : 'Nhấn nút thu âm và đọc tên/mã hàng cần báo giá' }}
                  </div>
                  <div style="font-size: 12px; color: #94a3b8; margin-top: 2px;">
                    Ví dụ: "Báo giá cho tao XGS118 với XGS330"
                  </div>
                  <div v-if="voiceInterimText" style="margin-top: 6px; font-size: 12.5px; color: #38bdf8; font-style: italic;">
                    {{ voiceInterimText }}
                  </div>
                </div>
              </div>

              <div style="display: flex; gap: 8px; flex-wrap: wrap;">
                <button v-if="!isVoiceListening && voiceTranscript" type="button" @click="startVoiceRecording(false)" style="background: #1e293b; color: #cbd5e1; border: 1px solid #334155; padding: 7px 12px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer;">
                  Ghi âm lại
                </button>
                <button v-if="!isVoiceListening && voiceTranscript" type="button" @click="startVoiceRecording(true)" style="background: #1e293b; color: #38bdf8; border: 1px solid #334155; padding: 7px 12px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer;">
                  Nói thêm
                </button>
                <button v-if="isVoiceListening" type="button" @click="stopVoiceRecording" style="background: #ef4444; color: #fff; border: none; padding: 7px 12px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer;">
                  Dừng thu
                </button>
              </div>
            </div>

            <div style="display: flex; flex-direction: column; gap: 6px;">
              <label style="font-size: 12px; font-weight: 600; color: #cbd5e1;">
                Nội dung văn bản (có thể chỉnh sửa lại trước khi xác nhận):
              </label>
              <textarea
                v-model="voiceTranscript"
                rows="3"
                placeholder="Nội dung thu âm sẽ hiển thị tại đây, hoặc nhập trực tiếp..."
                style="width: 100%; padding: 10px 14px; border-radius: 8px; border: 1px solid #334155; background: #0f172a; color: #f8fafc; font-size: 13.5px; line-height: 1.5; outline: none; resize: vertical;"
              ></textarea>
            </div>
          </div>

          <!-- BƯỚC 2: ĐANG PHÂN TÍCH -->
          <div v-else-if="voiceQuoteStep === 2" style="padding: 36px 20px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 12px;">
            <div style="width: 36px; height: 36px; border: 3px solid #334155; border-top-color: #10b981; border-radius: 50%; animation: spin 0.8s linear infinite;"></div>
            <div style="font-size: 14px; font-weight: 600; color: #e2e8f0;">
              Đang phân tích mặt hàng và đối chiếu kho sản phẩm...
            </div>
            <div style="font-size: 12.5px; color: #94a3b8;">
              "{{ voiceTranscript }}"
            </div>
          </div>

          <!-- BƯỚC 3: XÁC NHẬN MẶT HÀNG & HÀNG LIÊN QUAN -->
          <div v-else-if="voiceQuoteStep === 3" style="display: flex; flex-direction: column; gap: 12px;">
            <div style="padding: 10px 14px; border-radius: 8px; background: #0f172a; border: 1px solid #334155; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px;">
              <div style="font-size: 12.5px; color: #cbd5e1;">
                <span style="color: #94a3b8;">Nội dung:</span> <strong style="color: #f8fafc;">"{{ voiceTranscript }}"</strong>
              </div>
              <div style="display: flex; gap: 8px; align-items: center;">
                <button type="button" @click="voiceQuoteStep = 1" style="background: #1e293b; color: #cbd5e1; border: 1px solid #334155; padding: 5px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer;">
                  Sửa văn bản
                </button>
                <button type="button" @click="addManualVoiceGroup" style="background: #1e293b; color: #38bdf8; border: 1px solid #334155; padding: 5px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer;">
                  + Thêm từ khóa
                </button>
              </div>
            </div>

            <div v-for="(group, gIdx) in voiceExtractedGroups" :key="group.id" style="border: 1px solid #334155; border-radius: 8px; background: #0f172a; overflow: hidden;">
              <!-- Thanh từ khóa tìm kiếm của từng mặt hàng -->
              <div style="padding: 8px 12px; background: rgba(30, 41, 59, 0.7); border-bottom: 1px solid #334155; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px;">
                <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap; flex: 1;">
                  <span style="font-size: 12px; font-weight: 700; color: #94a3b8;">
                    #{{ gIdx + 1 }}
                  </span>
                  <input
                    type="text"
                    v-model="group.searchKeyword"
                    @keyup.enter="refreshGroupCandidates(group)"
                    placeholder="Mã hoặc tên hàng..."
                    style="padding: 5px 10px; border-radius: 6px; border: 1px solid #334155; background: #0f172a; color: #f8fafc; font-size: 12.5px; font-weight: 600; min-width: 180px; outline: none;"
                  />
                  <div style="display: flex; align-items: center; gap: 4px; font-size: 12px; color: #94a3b8;">
                    <span>SL:</span>
                    <input
                      type="number"
                      min="1"
                      v-model.number="group.requestedQty"
                      @change="refreshGroupCandidates(group)"
                      style="width: 54px; padding: 4px 6px; border-radius: 6px; border: 1px solid #334155; background: #0f172a; color: #f8fafc; font-weight: 600; text-align: center; outline: none;"
                    />
                  </div>
