  margin-right: 0;
  vertical-align: 0;
}
.action-btn:hover {
  background: #27272a;
  border-color: #475569;
  color: #f8fafc;
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}
.action-btn:disabled {
  opacity: 0.4;
  transform: none !important;
  box-shadow: none !important;
}
.action-primary {
  background: linear-gradient(135deg, #3b82f6, #2563eb) !important;
  color: white !important;
  border-color: transparent !important;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25), 0 0 0 1px rgba(59,130,246,0.1);
}
.action-primary:hover {
  background: linear-gradient(135deg, #2563eb, #1d4ed8) !important;
  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.35), 0 0 20px rgba(59,130,246,0.1) !important;
  transform: translateY(-2px) !important;
}
.action-success {
  background: linear-gradient(135deg, #22c55e, #16a34a) !important;
  color: white !important;
  border-color: transparent !important;
  box-shadow: 0 4px 12px rgba(22, 163, 74, 0.25), 0 0 0 1px rgba(34,197,94,0.1);
}
.action-success:hover {
  background: linear-gradient(135deg, #16a34a, #15803d) !important;
  box-shadow: 0 8px 20px rgba(22, 163, 74, 0.35), 0 0 20px rgba(34,197,94,0.1) !important;
  transform: translateY(-2px) !important;
}
.action-danger {
  background: linear-gradient(135deg, #ef4444, #dc2626) !important;
  color: white !important;
  border-color: transparent !important;
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.25), 0 0 0 1px rgba(239,68,68,0.1);
}
.action-danger:hover {
  background: linear-gradient(135deg, #dc2626, #b91c1c) !important;
  box-shadow: 0 8px 20px rgba(220, 38, 38, 0.35), 0 0 20px rgba(239,68,68,0.1) !important;
  transform: translateY(-2px) !important;
}
.action-save {
  grid-column: 1 / -1;
  flex-direction: row !important;
  padding: 10px 16px !important;
  background: linear-gradient(135deg, #7c3aed, #6d28d9) !important;
  color: white !important;
  border-color: transparent !important;
  box-shadow: 0 4px 12px rgba(109, 40, 217, 0.25), 0 0 0 1px rgba(124,58,237,0.1);
}
.action-save:hover {
  background: linear-gradient(135deg, #6d28d9, #5b21b6) !important;
  box-shadow: 0 8px 20px rgba(109, 40, 217, 0.35), 0 0 20px rgba(124,58,237,0.1) !important;
  transform: translateY(-2px) !important;
}
.action-pipeline {
  grid-column: 1 / -1;
  flex-direction: row !important;
  padding: 10px 16px !important;
  background: linear-gradient(135deg, #3b82f6, #2563eb) !important;
  color: white !important;
  border-color: rgba(255,255,255,0.08) !important;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
}
.action-pipeline:hover {
  background: linear-gradient(135deg, #60a5fa, #3b82f6) !important;
  box-shadow: 0 8px 20px rgba(59, 130, 246, 0.4), 0 0 12px rgba(59, 130, 246, 0.1) !important;
  border-color: rgba(59, 130, 246, 0.15) !important;
  transform: translateY(-2px) !important;
}
.save-msg {
  font-size: 11.5px;
  color: #94a3b8;
  margin: 6px 0 0;
  padding: 6px 10px;
  background: rgba(15,23,42,.5);
  border-radius: 8px;
  border: 1px solid #1e293b;
}
.action-utils {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.util-btn {
  width: 100%;
  padding: 9px 14px !important;
  font-size: 12px !important;
  font-weight: 500;
  background: #18181b;
  color: #94a3b8;
  border: 1px solid #334155;
  border-radius: 8px !important;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s;
}
.util-btn [class^="lucide-"] {
  font-size: 14px;
  color: #64748b;
  margin-right: 0;
}
.util-btn:hover {
  background: #27272a;
  border-color: #475569;
  color: #f8fafc;
}
.util-btn:hover [class^="lucide-"] {
  color: #38bdf8;
}

.inline-adjust {
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  background: rgba(245, 158, 11, 0.16) !important;
  color: #fbbf24 !important;
  border: 1px solid rgba(245, 158, 11, 0.42) !important;
  border-radius: 6px !important;
  padding: 3px 9px !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  width: max-content !important;
  white-space: nowrap !important;
  transition: all 0.18s ease !important;
}
.inline-normal-edit {
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  background: rgba(59, 130, 246, 0.16) !important;
  color: #60a5fa !important;
  border: 1px solid rgba(59, 130, 246, 0.42) !important;
  border-radius: 6px !important;
  padding: 3px 9px !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  width: max-content !important;
  white-space: nowrap !important;
  transition: all 0.18s ease !important;
}
.inline-adjust i,
.inline-adjust [class^="lucide-"] {
  color: inherit !important;
  font-size: 12px !important;
}
.inline-normal-edit i,
.inline-normal-edit [class^="lucide-"] {
  color: inherit !important;
  font-size: 12px !important;
}
.inline-adjust:hover {
  background: rgba(245, 158, 11, 0.28) !important;
  border-color: #fbbf24 !important;
  color: #fde68a !important;
  transform: translateY(-1px);
}
.inline-normal-edit:hover {
  background: rgba(59, 130, 246, 0.28) !important;
  border-color: #60a5fa !important;
  color: #93c5fd !important;
  transform: translateY(-1px);
}
.inline-adjust:hover i,
.inline-adjust:hover [class^="lucide-"] {
  color: #fde68a !important;
}
.inline-normal-edit:hover i,
.inline-normal-edit:hover [class^="lucide-"] {
  color: #93c5fd !important;
}


/* ===== MODAL GROUPS ===== */
.modal-group {
  background: rgba(15,23,42,.5);
  border: 1px solid #1e293b;
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 16px;
}
.modal-group-title {
  font-size: 12px;
  font-weight: 700;
  color: #e2e8f0;
  margin-top: 0;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1px solid #1e293b;
  padding-bottom: 8px;
}
.modal-group-title [class^="lucide-"] {
  font-size: 14px;
  color: #3b82f6;
}
/* ===== OPEN TABS ===== */
.open-tab {
  position: fixed; top: 90px; z-index: 9991;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.08);
  background: linear-gradient(135deg, rgba(79,70,229,0.9) 0%, rgba(59,130,246,0.9) 100%);
  color: #fff;
  cursor: pointer;
  font-weight: 600; font-size: 12px;
  box-shadow: 0 4px 16px -2px rgba(79, 70, 229, 0.4), 0 0 20px rgba(79,70,229,0.1);
  width: auto;
  backdrop-filter: blur(8px);
}
.open-tab:hover { transform: translateY(-2px); box-shadow: 0 8px 24px -2px rgba(79, 70, 229, 0.5), 0 0 30px rgba(79,70,229,0.15); }
.open-tab.left { left: 12px; }
.open-tab.right { right: 12px; }

/* ===== CENTER COLUMN ===== */
.quote-center {
  flex: 1;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: stretch !important;
  gap: 12px;
  height: calc(100vh - 24px) !important;
  overflow: hidden !important;
  min-width: 0; /* KEY: prevents grid blowout */
}

/* ===== FORMS ===== */
label {
  display: block;
  font-size: 11.5px;
  font-weight: 600;
  color: #94a3b8;
  margin: 8px 0 3px;
  text-transform: uppercase;
  letter-spacing: .03em;
}
input, textarea, select {
  width: 100%;
  padding: 0.75rem 1rem;
  margin-bottom: 4px;
  font-size: 13px;
  font-family: inherit;
  border-radius: 10px;
  border: 1px solid #334155;
  background-color: #0f172a;
  color: #f8fafc;
  box-sizing: border-box;
  transition: all .2s;
}
input:focus, textarea:focus, select:focus {
  border-color: #38bdf8;
  background-color: #0f172a;
  box-shadow: 0 0 0 3px rgba(56,189,248,.15);
  outline: none;
}
textarea { min-height: 60px; resize: both; }

/* ===== BUTTONS ===== */
button {
  padding: 0.75rem 1.5rem;
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  margin-bottom: 6px;
  border-radius: 10px;
  border: none;
  background-color: #18181b;
  cursor: pointer;
  color: #e2e8f0;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  line-height: 1.4;
}
button:hover { background-color: #27272a; color: #f8fafc; }
button:active { transform: translateY(0); }
button:disabled { opacity: .7; cursor: not-allowed; }

button.primary {
  background: linear-gradient(135deg, #4f46e5 0%, #3b82f6 100%);
  color: white;
  box-shadow: 0 4px 12px -2px rgba(79, 70, 229, 0.3);
}
button.primary:hover { 
  background: linear-gradient(135deg, #4338ca 0%, #2563eb 100%);
  transform: translateY(-2px);
  box-shadow: 0 8px 16px -2px rgba(79, 70, 229, 0.4);
}

button.ghost {
  background-color: transparent;
  color: #94a3b8;
  border: 1px solid #334155;
}
button.ghost:hover { background-color: rgba(255,255,255,0.05); color: #f8fafc; }

hr { border: none; border-top: 1px solid #1e293b; margin: 12px 0; }

/* ===== TOP BAR ===== */
.top-bar {
  display: flex; flex-direction: column; gap: 6px; margin-bottom: 10px; flex-shrink: 0;
}
.sidebar-head-product {
  background: transparent;
  margin: -16px -16px 10px;
  padding: 12px 16px;
  border-radius: 20px 20px 0 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  position: relative;
}
.sidebar-head-product::after {
  content: '';
  position: absolute;
  bottom: -1px; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(56,189,248,0.5), transparent);
}
.sidebar-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sidebar-head-product h3 {
  font-size: 15px !important;
  font-weight: 800 !important;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #fff !important;
  background: linear-gradient(135deg, #fff, #7dd3fc) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  margin: 0;
}
.sidebar-head-product .icon-btn {
  color: #64748b;
  border-radius: 50%;
  background: rgba(15,23,42,0.4);
  border: 1px solid rgba(255,255,255,0.05);
}
.sidebar-head-product .icon-btn:hover {
  background: rgba(239, 68, 68, 0.15);
  color: #ef4444;
  border-color: rgba(239, 68, 68, 0.3);
  transform: rotate(90deg);
}
.product-count {
  background: rgba(14, 165, 233, 0.15);
  color: #38bdf8;
  border: 1px solid rgba(14, 165, 233, 0.3);
  box-shadow: 0 0 10px rgba(14, 165, 233, 0.1);
  font-size: 10.5px;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.5px;
}
.btn-manual-circle {
  width: 30px !important;
  height: 30px !important;
  border-radius: 50% !important;
  background: linear-gradient(135deg, #3b82f6, #2563eb) !important;
  color: #ffffff !important;
  font-size: 24px !important;
  font-weight: 800 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border: none !important;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(59, 130, 246, 0.4);
  transition: all 0.25s !important;
  padding: 0 !important;
  margin: 0 0 0 4px !important;
  line-height: 1 !important;
}
.btn-manual-circle:hover {
  transform: translateY(-50%) scale(1.1) rotate(90deg) !important;
  background: linear-gradient(135deg, #60a5fa, #3b82f6) !important;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.6) !important;
}
.search-wrap {
  position: relative;
}
.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  stroke: #ffffff !important;
  stroke-width: 3px !important;
  fill: none !important;
  pointer-events: none;
  z-index: 10;
}
.search-input {
  padding-left: 40px !important;
  background: rgba(15, 23, 42, 0.6) !important;
  border: 1px solid #065f46 !important;
  border-radius: 30px !important;
  color: #f8fafc !important;
  font-size: 13.5px !important;
  font-weight: 700 !important;
  padding-top: 10px !important;
  padding-bottom: 10px !important;
}
.search-input::placeholder {
  color: rgba(255, 255, 255, 0.8) !important;
  font-weight: 700 !important;
}
.search-input:focus {
  background: rgba(15, 23, 42, 0.8) !important;
  border-color: #10b981 !important;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.2) !important;
}
.filter-select {
  font-size: 12.5px;
  color: #94a3b8 !important;
  background: rgba(15, 23, 42, 0.6) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 10px !important;
  padding-top: 10px !important;
  padding-bottom: 10px !important;
}
.filter-select:focus {
  background: rgba(15, 23, 42, 0.8) !important;
  border-color: rgba(56, 189, 248, 0.5) !important;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15) !important;
}

/* ===== PRODUCT GRID ===== */
.product-grid {
  display: flex; flex-direction: column; gap: 8px;
  overflow-y: auto; flex: 1; 
  margin: -6px -8px -6px -10px;
  padding: 6px 10px 12px 10px;
}
.product-grid::-webkit-scrollbar { width: 4px; }
.product-grid::-webkit-scrollbar-track { background: transparent; }
.product-grid::-webkit-scrollbar-thumb { background: rgba(56,189,248,0.15); border-radius: 4px; }
.product-grid::-webkit-scrollbar-thumb:hover { background: rgba(56,189,248,0.3); }

/* ===== SKELETON LOADING CARDS ===== */
.skeleton-card {
  background: rgba(15,23,42,0.6);
  border: 1px solid rgba(255,255,255,0.04);
  border-radius: 14px;
  padding: 16px;
  animation: skeleton-fade-in 0.3s ease-out;
}
.skeleton-badges {
  display: flex;
  gap: 6px;
  margin-bottom: 4px;
}
.skeleton-line {
  background: linear-gradient(90deg,
    rgba(255,255,255,0.04) 0%,
    rgba(255,255,255,0.08) 40%,
    rgba(255,255,255,0.04) 80%
  );
  background-size: 200% 100%;
  border-radius: 4px;
  animation: skeleton-shimmer 1.5s ease-in-out infinite;
}
.skeleton-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid rgba(255,255,255,0.04);
}
@keyframes skeleton-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@keyframes skeleton-fade-in {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* ═══════════════════════════════════════════════════
   PREMIUM HORIZONTAL CARD — VIP Design System
   ═══════════════════════════════════════════════════ */

.card {
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-left: 3px solid #10b981;
  border-radius: 12px;
  background: linear-gradient(160deg, rgba(30,41,59,0.78) 0%, rgba(15,23,42,0.92) 100%);
  cursor: pointer;
  display: flex; flex-direction: column;
  padding: 9px 12px;
  transition: all 0.25s cubic-bezier(0.2, 0.8, 0.2, 1);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(16, 185, 129, 0.1);
  overflow: hidden;
  position: relative;
  gap: 6px;
  flex-shrink: 0;
}
.card::before { display: none; }
.card::after { display: none; }
.card:hover {
  border-color: rgba(255, 255, 255, 0.14);
  border-left-color: #34d399;
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.3),
    0 0 16px rgba(16, 185, 129, 0.18);
  transform: translateY(-2px);
  background: linear-gradient(160deg, rgba(30,41,59,0.9) 0%, rgba(15,23,42,1) 100%);
}

/* ── Left: Image (full bleed with rounded left side) ── */
.card-left {
  width: 42%; min-width: 42%;
  display: flex; align-items: stretch;
  padding: 0;
  flex-shrink: 0;
}
.card-img-wrap {
  position: relative;
  width: 100%; height: 100%;
  border-radius: 0;
  overflow: hidden;
  background: linear-gradient(135deg, #1a2332, #111827);
  padding: 0; flex-shrink: 0;
  box-shadow: none;
}
.card-img-overlay { display: none; }
.card-img-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  border-radius: 0;
  display: block;
  transition: transform 0.45s cubic-bezier(0.4, 0, 0.2, 1), filter 0.35s ease;
  filter: brightness(0.95);
  min-height: 100%;
}
.card:hover .card-img-wrap img {
  transform: scale(1.06);
  filter: brightness(1.05);
}

/* ── Badges row ── */
.card-badges {
  display: flex; align-items: center; gap: 5px;
  flex-wrap: wrap;
  margin-bottom: 2px;
}
.card-ncc-badge {
  position: static;
  display: inline-block;
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  font-size: 7.5px; font-weight: 700;
  padding: 2px 7px; border-radius: 4px;
  letter-spacing: 0.4px; text-transform: uppercase;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  border: none; max-width: 100px;
}
.card-vat-badge-img {
  position: static;
  display: inline-block;
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
  font-size: 7.5px; font-weight: 800;
  padding: 2px 7px; border-radius: 4px;
  letter-spacing: 0.3px;
  box-shadow: none; text-transform: uppercase;
}

/* ── Right: Content ── */
.card-right {
  flex: 1; display: flex; flex-direction: column;
  min-width: 0; padding: 12px 14px 10px 12px;
  justify-content: space-between;
  position: relative;
}
.card-body {
  display: flex; flex-direction: column;
  gap: 2px; padding: 0;
}
.card h4 {
  margin: 0; font-size: 12px; font-weight: 700;
  color: #f8fafc; line-height: 1.35; letter-spacing: -0.01em;
}
.clamp2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.clamp1 { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.card-license { font-size: 10px; color: #64748b; margin: 0; font-style: normal; font-weight: 600; }
.card-desc { font-size: 10.5px; color: #94a3b8; margin: 0; line-height: 1.3; }
.card-bottom-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 5px;
  border-top: 1px solid rgba(51, 65, 85, 0.3);
}
.card-price-col {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}
.card-price-row {
  display: flex; align-items: baseline;
  gap: 4px; margin-top: 0; flex-wrap: wrap;
}
.price {
  font-weight: 800; font-size: 13.5px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  margin: 0; letter-spacing: -0.02em;
  color: #10b981;
  -webkit-text-fill-color: unset;
  background: none; -webkit-background-clip: unset; background-clip: unset;
}
.price-unit { font-size: 9.5px; color: #94a3b8; font-weight: 500; }
.card-orig-price { font-size: 9px; color: #94a3b8; margin: 1px 0 0; }
.card-vat-badge {
  display: inline-block; width: fit-content;
  background: rgba(16, 185, 129, 0.15); color: #34d399;
  font-size: 10px; font-weight: 700; padding: 2px 8px;
  border-radius: 6px; border: none; margin-top: 2px;
}
.muted { color: #64748b; font-size: 11.5px; margin: 0; }
.small { font-size: 11px; }

/* ── Footer: Qty + Add (inline compact) ── */
.card-footer {
  display: flex; flex-direction: row;
  align-items: center; gap: 6px;
  padding: 0;
  margin-top: 0;
  border-top: none;
  flex-shrink: 0;
  position: relative; z-index: 1;
}
.qty {
  display: flex; align-items: center; gap: 4px;
  justify-content: center;
  border: none; overflow: visible;
  height: auto; background: transparent;
  box-shadow: none; border-radius: 0;
}
.qty button {
  width: 24px !important; height: 24px !important; padding: 0 !important; margin: 0 !important;
  border-radius: 6px;
  background: rgba(51, 65, 85, 0.55);
  border: 1px solid rgba(71, 85, 105, 0.45);
  font-size: 13px; color: #cbd5e1;
  min-width: 24px !important; box-shadow: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.2s ease; font-weight: 700; line-height: 1;
}
.qty button:hover {
  background: rgba(99, 102, 241, 0.2); color: #c7d2fe;
  border-color: rgba(99, 102, 241, 0.35);
}
.qty button:active {
  background: rgba(99, 102, 241, 0.3); transform: scale(0.94);
}
.qty button:last-child {
  background: rgba(16, 185, 129, 0.2);
  border-color: rgba(16, 185, 129, 0.45);
  color: #34d399;
}
.qty button:last-child:hover {
  background: #10b981;
  border-color: #10b981;
  color: #fff;
}
.qty span {
  width: 20px; font-weight: 800; font-size: 12.5px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  text-align: center; border: none; background: transparent;
  display: flex; align-items: center; justify-content: center;
  color: #f1f5f9;
}
.btn-add {
  width: auto !important;
  min-width: 64px;
  margin: 0 !important;
  background: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
  color: white !important; font-weight: 800;
  padding: 0 10px !important; font-size: 10.5px !important;
  border-radius: 7px !important; border: 1px solid rgba(255,255,255,0.1);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.25);
  letter-spacing: 0.3px; text-transform: uppercase;
  height: 26px; position: relative; overflow: hidden;
}
.btn-add::after { display: none; }
.btn-add:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.45), 0 0 20px rgba(16,185,129,0.2), inset 0 1px 0 rgba(255,255,255,0.3);
  background: linear-gradient(135deg, #34d399 0%, #10b981 100%) !important;
}
.btn-add:active {
  transform: translateY(0);
  box-shadow: 0 1px 3px rgba(16, 185, 129, 0.15);
}
.btn-add-icon { font-size: 12px; font-weight: 800; }

.btn-del {
  width: 28px; height: 28px; padding: 0;
  background: #ef4444; color: #ffffff;
  border: none; border-radius: 6px;
  transition: all .2s; min-width: 28px;
  box-shadow: none;
  font-weight: bold;
  font-size: 14px;
}
.btn-del:hover { background: #dc2626; color: #ffffff; transform: none; }

/* ===== TABLE WRAPPER ===== */
.quote-table-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: linear-gradient(160deg, rgba(0, 61, 77, 0.25) 0%, rgba(15, 23, 34, 0.75) 100%);
  border-radius: 20px;
  box-shadow:
    0 20px 40px -10px rgba(0,0,0,0.6),
    inset 0 1px 0 rgba(255,255,255,0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 0;
  min-height: 0;
  min-width: 0;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  transition: all 0.35s ease;
  overflow: hidden;
}
.quote-table-container:hover {
  border-color: rgba(56, 189, 248, 0.12);
  box-shadow:
    0 20px 50px -10px rgba(0,0,0,0.7),
    0 0 30px rgba(56,189,248,0.04),
    inset 0 1px 0 rgba(255,255,255,0.06);
}
.quote-table-wrap {
  flex: 1;
  overflow: auto;
  display: flex;
  flex-direction: column;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-y: contain;
  will-change: scroll-position;
}
.table-header-box {
  padding: 10px 16px;
  background: rgba(9,9,11,0.92);
  backdrop-filter: blur(12px);
  z-index: 3;
  margin-bottom: 0;
  position: relative;
}
.table-header-box::after {
  content: '';
  position: absolute;
  bottom: 0; left: 16px; right: 16px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(56,189,248,0.25), transparent);
}
.table-header-box h3 {
  font-size: 14.5px;
  font-weight: 700;
  letter-spacing: -0.01em;
  background: linear-gradient(135deg, #f8fafc, #38bdf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.table-header-box .hint, .hint {
  font-size: 11.5px; color: #64748b; font-weight: 400;
}
.header-contract-info {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0;
}
.unified-contract-pill {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 4px 12px;
  min-height: 28px;
  box-sizing: border-box;
}
.contract-seg {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
}
.contract-seg b {
  color: #10b981;
  font-weight: 700;
}
.contract-sep {
  color: rgba(148, 163, 184, 0.35);
  font-size: 11px;
  user-select: none;
}
.contract-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: rgba(15,23,42,0.6);
  color: #94a3b8;
  padding: 4px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.3px;
  border: 1px solid rgba(255,255,255,0.06);
  backdrop-filter: blur(8px);
}
.contract-badge b {
  color: #10b981;
  font-weight: 700;
}

/* ===== TABLE ===== */
table {
  width: 100%;
  min-width: 1200px;
  border-collapse: collapse;
  font-size: 12.5px;
  table-layout: fixed; /* KEY: fixed layout for predictable column widths */
}
th, td {
  padding: 12px 10px;
  vertical-align: top;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  white-space: normal;
  word-break: break-word;
  line-height: 1.45;
}
td { color: #cbd5e1; }

/* Description column: allow wrap but clamp height */
td.desc {
  white-space: normal;
  overflow: hidden;
  color: #94a3b8;
  font-size: 11.5px;
  line-height: 1.5;
  max-height: 72px; /* ~4 lines max */
  position: relative;
}
td.desc .preline {
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
  white-space: pre-line;
  font-size: 11.5px;
  line-height: 1.5;
}
td.desc .preline > div { margin-bottom: 2px; }

thead th {
  position: sticky; top: 0; z-index: 10;
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  font-weight: 800;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-bottom: 1px solid #047857;
  z-index: 2;
  white-space: normal;
  line-height: 1.3;
  vertical-align: middle;
  padding: 10px;
}

tfoot td {
  position: sticky; bottom: 0;
  background: linear-gradient(180deg, #0f172a 0%, #1e293b 100%);
  color: #f8fafc;
  border-top: 2px solid #10b981;
  border-bottom: none;
  z-index: 5;
  box-shadow: 0 -4px 16px rgba(0, 0, 0, 0.45);
  vertical-align: middle;
}

/* Zebra + Hover */
tbody tr.quote-item-row:nth-child(odd) { background: rgba(30, 41, 59, 0.5); }
tbody tr.quote-item-row:nth-child(even) { background: rgba(15, 23, 42, 0.3); }
tbody tr.quote-item-row { cursor: pointer; transition: background .1s; }
tbody tr.quote-item-row:hover td { background-color: rgba(56,189,248,0.1) !important; }

.right {
  text-align: right;
  font-size: 12px;
  font-weight: 700;
  color: #f8fafc;
}
.center {
  text-align: center;
  font-size: 12px;
}
.nowrap { white-space: normal; }
td.dvt { font-family: inherit; white-space: normal; }

/* ===== GROUP ROW ===== */
.group-row td {
  background: linear-gradient(90deg, rgba(16, 185, 129, 0.18) 0%, rgba(15, 23, 42, 0.85) 100%) !important;
  border-top: 1px solid rgba(16, 185, 129, 0.28) !important;
  border-bottom: 1px solid rgba(16, 185, 129, 0.28) !important;
  font-weight: 800;
  color: #ffffff;
  font-size: 15px;
  vertical-align: middle;
}
.group-row td:first-child {
  border-left: 4px solid #10b981 !important;
}
.group-stt {
  text-align: center;
  color: #34d399 !important;
}
.group-title {
  padding-left: 12px;
  padding-right: 12px;
  text-align: left;
  color: #ffffff !important;
}
.group-title-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
}
.group-title-text {
  font-weight: 800;
  color: inherit;
  letter-spacing: 0.2px;
}
.group-row-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  flex-shrink: 0;
}

/* ===== COLUMN WIDTHS (table-layout: fixed) ===== */
.col-stt  { width: 36px; text-align: center; }
.col-pn   { width: 80px; }
.col-pn-cell {
  max-width: 80px;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.col-desc-cell {
  max-width: 280px;
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
  vertical-align: top;
}
.col-desc-cell .preline {
  display: block;
  white-space: pre-wrap;
  line-height: 1.45;
}
.col-desc-cell .preline > div {
  display: block;
}
.col-hang-cell {
  max-width: 70px;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}
.col-dvt-cell {
  max-width: 55px;
  font-size: 9px;
  text-align: center;
  word-break: break-word;
}
.col-name { width: 130px; }
.col-desc { width: 220px; } /* wider for description */
.col-hang { width: 70px; }
.col-sl   { width: 36px; text-align: center; }
.col-dvt  { width: 55px; }
.col-dg   { width: 100px; text-align: right; }
.col-tt   { width: 105px; text-align: right; }
.col-vat  { width: 85px; text-align: right; }
.col-loi  { width: 110px; text-align: right; color: #059669; }
.col-del  { width: 36px; text-align: center; }

/* Cell Input */
.quote-center {
  display: flex;
  flex-direction: row;
}
.quote-table-wrap {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}
.quote-table-wrap table {
  height: 100%;
}
.spacer-row {
  height: 100%;
}

.cell-input {
  width: 100%; padding: 5px 7px;
  border-radius: 6px; border: 1px solid #334155;
  font-size: 12px;
  margin: 0; box-sizing: border-box; background: #0f172a; color: #f8fafc;
}
.cell-input:focus { border-color: #38bdf8; box-shadow: 0 0 0 3px rgba(56,189,248,.15); }

/* ===== TOTALS (LEFT SIDEBAR BOTTOM DOCK - CÁCH B: DARK SLATE + VIỀN XANH NGỌC) ===== */
.bottom-totals.left-sidebar-dock {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: calc(100% + 32px);
  min-width: 0;
  max-width: none;
  flex-shrink: 0;
  height: auto;
  overflow: visible;
  margin: 6px -16px -16px -16px;
  padding: 12px 14px 14px 14px;
  background: linear-gradient(180deg, #0f172a 0%, #1e293b 100%);
  border-top: 2px solid #10b981;
  border-radius: 0 0 20px 20px;
  box-shadow: 0 -6px 20px rgba(0, 0, 0, 0.45);
  z-index: 5;
}
.sidebar-dock-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.dock-tab-btn {
  width: 100% !important;
  min-width: 0 !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 6px 8px !important;
  border-radius: 8px !important;
  font-size: 11.5px !important;
  font-weight: 700 !important;
  background: rgba(9, 13, 22, 0.65) !important;
  color: #94a3b8 !important;
  border: 1px solid rgba(51, 65, 85, 0.75) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  cursor: pointer;
  transition: all 0.18s ease !important;
  line-height: 1.2 !important;
}
.dock-tab-btn:hover {
  background: rgba(30, 41, 59, 0.9) !important;
  color: #f8fafc !important;
  border-color: rgba(16, 185, 129, 0.4) !important;
}
.dock-tab-btn.active {
  background: rgba(16, 185, 129, 0.18) !important;
  color: #34d399 !important;
  border-color: #10b981 !important;
  box-shadow: 0 0 10px rgba(16, 185, 129, 0.15) !important;
}
.dock-tab-panel {
  display: none;
}
.dock-tab-panel.dock-tab-active {
  display: block;
}
.bottom-totals.left-sidebar-dock .totals-box.dock-tab-panel {
  background: rgba(9, 13, 22, 0.55);
  border-radius: 10px;
  border: 1px solid rgba(16, 185, 129, 0.25);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
.totals-box {
  background: linear-gradient(160deg, rgba(0, 61, 77, 0.35) 0%, rgba(15, 23, 34, 0.8) 100%);
  border-radius: 14px;
  overflow: hidden;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow:
    0 12px 28px -8px rgba(0,0,0,0.55),
    inset 0 1px 0 rgba(255,255,255,0.04);
  transition: all 0.3s ease;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}
.totals-box:hover {
  box-shadow:
    0 16px 36px -8px rgba(0,0,0,0.65),
    0 0 24px rgba(56,189,248,0.06),
    inset 0 1px 2px rgba(255,255,255,0.06);
  border-color: rgba(56, 189, 248, 0.15);
}
.totals-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  background: linear-gradient(135deg, rgba(51,65,85,0.5), rgba(30,41,59,0.7));
  color: #f1f5f9;
  font-size: 12px;
  font-weight: 700;
  font-family: 'Plus Jakarta Sans', sans-serif;
  letter-spacing: 0.3px;
  border-bottom: 1px solid rgba(56,189,248,0.08);
  position: relative;
}
.totals-header::after {
  content: '';
  position: absolute;
  bottom: 0; left: 12px; right: 12px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(56,189,248,0.25), transparent);
}
.totals-header-primary {
  background: linear-gradient(135deg, rgba(30,58,95,0.6), rgba(12,74,110,0.7));
}
.totals-header-primary::after {
  background: linear-gradient(90deg, transparent, rgba(56,189,248,0.35), transparent) !important;
}
.totals-icon {
  font-size: 14px;
  line-height: 1;
}
.totals-body {
  padding: 2px 0;
}
.totals-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 12px;
  font-size: 12px;
  transition: background 0.15s ease;
  border-bottom: 1px solid rgba(255,255,255,0.03);
}
.totals-row:last-child {
  border-bottom: none;
}
.totals-row:hover {
  background: rgba(56,189,248,0.05);
}
.totals-label {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 500;
  font-size: 12px;
  color: #ffffff;
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(0,0,0,0.5);
}
.totals-value {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 600;
  font-size: 13px;
  color: #f8fafc;
  text-align: right;
  letter-spacing: 0.2px;
}
.totals-value small {
  font-weight: 400;
  font-size: 11px;
  color: #64748b;
  margin-left: 4px;
}
.totals-value.text-warn {
  color: #fbbf24;
  text-shadow: 0 0 10px rgba(251,191,36,0.2);
}
/* Highlighted total rows */
.totals-highlight {
  background: rgba(245,158,11,0.1);
  border-bottom: none !important;
  margin-top: 2px;
  border-top: 1px dashed rgba(245,158,11,0.3);
}
.totals-highlight .totals-label {
  font-weight: 700;
  color: #fbbf24;
  font-size: 12.5px;
}
.totals-highlight .totals-value {
  font-weight: 700;
  color: #f59e0b;
  font-size: 14px;
}
.totals-highlight-blue {
  background: rgba(56,189,248,0.08);
  border-bottom: none !important;
  margin-top: 2px;
  border-top: 1px dashed rgba(56,189,248,0.3);
}
.totals-highlight-blue .totals-label {
  font-weight: 700;
  color: #38bdf8;
  font-size: 12.5px;
}
.totals-highlight-blue .totals-value {
  font-weight: 700;
  color: #38bdf8;
  font-size: 14px;
}
.totals-highlight-green {
  background: rgba(16,185,129,0.08);
  border-bottom: none !important;
}
.totals-highlight-green .totals-label {
  font-weight: 700;
  color: #34d399;
  font-size: 12.5px;
}
.totals-highlight-green .totals-value {
  font-weight: 700;
  color: #10b981;
  font-size: 14px;
}

/* ===== MODAL ===== */
.modal {
  position: fixed; inset: 0;
  background: rgba(2,6,23,.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex; align-items: center; justify-content: center;
  z-index: 9999; padding: 20px;
  animation: fadeIn .2s ease forwards;
}
@keyframes fadeIn { from { opacity: 0 } to { opacity: 1 } }
.modal-card {
  background: #020617; color: #f8fafc;
  padding: 24px; width: 580px;
  max-height: 90vh; overflow: auto;
  border-radius: 20px;
  border: 1px solid rgba(255,255,255,0.06);
  border-top: 1px solid rgba(255,255,255,0.12);
  box-shadow:
    0 25px 60px rgba(0,0,0,.6),
    0 0 40px rgba(56,189,248,0.03),
    inset 0 1px 0 rgba(255,255,255,0.04);
  animation: slideUp 0.3s cubic-bezier(.16,1,.3,1) forwards;
}
@keyframes slideUp {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
}
.modal-card.modal-wide { width: min(1200px, 96vw); }
.modal-head {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid #1e293b;
}
.modal-head h3 { margin: 0; font-size: 16px; font-weight: 700; color: #f8fafc; }
.modal-head .x {
  width: 32px; height: 32px;
  border-radius: 50%; background: #ef4444 !important;
  border: none !important; font-size: 14px; padding: 0;
  color: #ffffff !important;
  display: flex; align-items: center; justify-content: center;
}
.modal-head .x:hover { background: #dc2626 !important; color: #ffffff !important; transform: rotate(90deg); }

/* Áp dụng chung cho tất cả các nút đóng modal khác (nếu có class khác) */
.export-vip-close, .history-modal-header .x, .modal-close, button.x {
  background: #ef4444 !important;
  color: #ffffff !important;
  border: none !important;
}
.export-vip-close:hover, .history-modal-header .x:hover, .modal-close:hover, button.x:hover {
  background: #dc2626 !important;
  color: #ffffff !important;
}

.preview {
  width: 100%; height: 200px; object-fit: contain;
  background: #0f172a; border-radius: 12px;
  border: 1px solid #1e293b; margin-bottom: 12px;
}

.modal-actions {
  display: flex; justify-content: flex-end; gap: 10px;
  margin-top: 20px; padding-top: 16px;
  border-top: 1px solid #1e293b;
}
.modal-actions button { width: auto; }

.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.grid3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1100px) {
  .main-grid { grid-template-columns: 1fr; }
  .product-sidebar { position: relative; height: auto; top: 0; max-height: 50vh; }
  .quote-center { height: auto !important; }
  .sidebar-left.closed, .sidebar-right.closed { display: none; }
  .open-tab { top: auto; bottom: 20px; }
}

/* ==============================================================
   CSS RIÊNG CHO IN ẤN (PDF)
============================================================== */
.print-only {
  display: none;
}

@media print {
  /* ẨN TOÀN BỘ GIAO DIỆN APP */
  .page > *:not(.main-grid) { display: none !important; }
  .main-grid > *:not(.quote-center) { display: none !important; }
  .quote-center > *:not(.print-only) { display: none !important; }
  
  /* Cài đặt trang A4 */
  @page {
    size: A4 portrait;
    margin: 10mm;
  }

  body, html {
    margin: 0;
    padding: 0;
    background: #fff;
    color: #000;
  }

  /* HIỂN THỊ VÙNG IN */
  .print-only {
    display: block !important;
    font-family: "Times New Roman", Times, serif;
    font-size: 11pt; /* Giảm font size để vừa 9 cột */
    line-height: 1.3;
    width: 100%;
  }

  /* Bảng Báo Giá PDF */
  .pdf-table {
    width: 100%;
    table-layout: fixed; /* Cố định width theo % để full trang A4 */
    border-collapse: collapse;
    margin-bottom: 20px;
    word-wrap: break-word;
  }
  .pdf-table th, .pdf-table td {
    border: 1px solid #000;
    padding: 6px 4px;
    vertical-align: middle;
  }
  .pdf-table th {
    background-color: #CCFFCC !important; /* Xanh lá giống Excel */
    -webkit-print-color-adjust: exact;
    text-align: center;
    font-weight: bold;
    font-size: 10pt;
  }
  .pdf-group-row td {
    background-color: #FFFF00 !important; /* Vàng giống Excel */
    -webkit-print-color-adjust: exact;
  }
  .pdf-total-row td {
    background-color: #FFFF00 !important; /* Vàng giống Excel */
    -webkit-print-color-adjust: exact;
  }
  
  /* Tiện ích text */
  .text-center { text-align: center; }
  .text-left { text-align: left; }
  .text-right { text-align: right; }
}

.term-preview {
  margin-top: 10px;
  background: rgba(15,23,42,.5);
  border: 1px solid #1e293b;
  border-radius: 8px;
  padding: 12px;
}

.term-preview label {
  font-weight: 600;
  color: #f8fafc;
  margin-bottom: 8px;
  display: block;
}



.history-icon {
  margin-left: 6px;
  cursor: pointer;
  font-size: 15px;
  display: inline-flex;
  align-items: center;
  transition: opacity 0.2s, transform 0.2s;
  vertical-align: middle;
  opacity: 0.7;
}
.history-icon:hover {
  opacity: 1;
  transform: scale(1.15);
}

/* ===== HISTORY MODAL ===== */
.history-modal-card {
  width: min(1200px, 96vw) !important;
  padding: 0 !important;
  overflow: hidden;
}
.history-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  background: linear-gradient(135deg, #1e293b 0%, #334155 100%);
  color: white;
}
.history-modal-header .x {
  background: rgba(255, 255, 255, 0.12) !important;
  color: #e2e8f0 !important;
  border: none;
}
.history-modal-header .x:hover {
  background: rgba(255, 255, 255, 0.25) !important;
  color: #fff !important;
}
.history-modal-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.history-modal-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(56, 189, 248, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #38bdf8;
  flex-shrink: 0;
}
.history-modal-title {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: 0.2px;
}
.history-modal-subtitle {
  margin: 3px 0 0;
  font-size: 13px;
  color: #ffffff;
  font-weight: 500;
}

/* Summary Stats */
.history-summary {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 12px;
  padding: 16px 24px;
  background: #0f172a;
  border-bottom: 1px solid #1e293b;
}
.history-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 8px;
  background: #1e293b;
  border-radius: 10px;
  border: 1px solid #334155;
}
.history-stat-label {
  font-size: 11px;
  font-weight: 600;
  color: #ffffff;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.history-stat-value {
  font-size: 14px;
  font-weight: 700;
  color: #f8fafc;
  font-family: 'JetBrains Mono', monospace;
}

/* Table Wrap */
.history-table-wrap {
  max-height: 420px;
  overflow-y: auto;
  padding: 0;
}

/* Table */
.history-table {
  width: 100%;
  border-collapse: collapse;
  margin: 0;
  table-layout: fixed;
  min-width: auto !important;
}
.history-table th {
  position: sticky;
  top: 0;
  background: #0f172a !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  font-size: 11px !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 10px 12px !important;
  border-bottom: 1px solid #1e293b !important;
  border-top: none !important;
  border-left: none !important;
  border-right: none !important;
  z-index: 2;
}
.history-table td {
  padding: 10px 12px !important;
  border: none !important;
  border-bottom: 1px solid #1e293b !important;
  font-size: 13px;
  vertical-align: middle !important;
  color: #cbd5e1;
}
.history-row {
  transition: background 0.15s ease;
}
.history-row:hover td {
  background: rgba(56,189,248,0.05) !important;
}
.history-row:nth-child(even) td {
  background: rgba(15,23,42,0.3);
}

/* Time badge */
.history-time-badge {
  display: inline-block;
  background: #1e293b;
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
  white-space: nowrap;
  border-radius: 6px;
  font-family: 'JetBrains Mono', monospace;
  letter-spacing: 0.3px;
  border: 1px solid #334155;
}

/* Old value */
.history-old-val {
  color: #ef4444;
  font-size: 13px;
  font-weight: 500;
  font-family: 'Plus Jakarta Sans', sans-serif;
}

/* Arrow indicators */
.history-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
}
.arrow-up {
  background: #ecfdf5;
  color: #059669;
}
.arrow-down {
  background: #fef2f2;
  color: #dc2626;
}
.arrow-same {
  background: #f1f5f9;
  color: #94a3b8;
}

/* New value */
.history-new-val {
  font-size: 14px;
  font-weight: 700;
  color: #f8fafc;
  font-family: 'JetBrains Mono', monospace;
}
.val-up { color: #059669; }
.val-down { color: #dc2626; }

/* Difference */
.history-diff {
  font-size: 12px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 6px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  display: inline-block;
}
.diff-up {
  background: #ecfdf5;
  color: #059669;
}
.diff-down {
  background: #fef2f2;
  color: #dc2626;
}

/* Empty state */
.history-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
}
.history-empty-icon {
  font-size: 40px;
  margin-bottom: 12px;
  opacity: 0.6;
}
.history-empty-title {
  font-size: 16px;
  font-weight: 700;
  color: #e2e8f0;
  margin: 0 0 6px;
}
.history-empty-desc {
  font-size: 13px;
  color: #94a3b8;
  margin: 0;
  max-width: 280px;
  line-height: 1.5;
}

/* Footer */
.history-modal-footer {
  padding: 14px 24px;
  border-top: 1px solid #1e293b;
  display: flex;
  justify-content: flex-end;
  background: #0f172a;
}
.history-modal-footer button {
  width: auto !important;
  padding: 8px 20px !important;
}
@keyframes highlightRowPulse {
  0% { background-color: rgba(16, 185, 129, 0.4); }
  50% { background-color: rgba(16, 185, 129, 0.15); }
  100% { background-color: transparent; }
}
.highlight-pulse td {
  animation: highlightRowPulse 0.8s ease-out;
}
.ghost-group {
  opacity: 0.5;
  background-color: rgba(56, 189, 248, 0.1);
}
@keyframes vipPulseGhost {
  0% { background-color: rgba(56, 189, 248, 0.05); border-color: rgba(56, 189, 248, 0.4); }
  50% { background-color: rgba(56, 189, 248, 0.15); border-color: rgba(56, 189, 248, 0.8); }
  100% { background-color: rgba(56, 189, 248, 0.05); border-color: rgba(56, 189, 248, 0.4); }
}
@keyframes vipFloatGlow {
  0% { box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5), 0 0 15px rgba(56, 189, 248, 0.4); }
  50% { box-shadow: 0 25px 45px rgba(0, 0, 0, 0.6), 0 0 30px rgba(56, 189, 248, 0.7); }
  100% { box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5), 0 0 15px rgba(56, 189, 248, 0.4); }
}

.ghost-item {
  opacity: 0.4 !important;
}
.ghost-item td {
  border-top: 2px dashed #38bdf8 !important;
  border-bottom: 2px dashed #38bdf8 !important;
  animation: vipPulseGhost 1.5s infinite;
}
.ghost-item td:first-child {
  border-left: 2px dashed #38bdf8 !important;
  border-top-left-radius: 8px;
  border-bottom-left-radius: 8px;
}
.ghost-item td:last-child {
  border-right: 2px dashed #38bdf8 !important;
  border-top-right-radius: 8px;
  border-bottom-right-radius: 8px;
}

.hidden-drag-preview {
  opacity: 0 !important;
  pointer-events: none !important;
}

.drag-item {
  opacity: 0 !important;
  background: transparent !important;
  backdrop-filter: none !important;
  z-index: 9999 !important;
}
.drag-item td {
  border-top: 1px solid #38bdf8 !important;
  border-bottom: 1px solid #38bdf8 !important;
  animation: vipFloatGlow 2s infinite ease-in-out;
}
.drag-item td:first-child {
  border-left: 1px solid #38bdf8 !important;
}
.drag-item td:last-child {
  border-right: 1px solid #38bdf8 !important;
}

.chosen-item {
  background-color: rgba(16, 185, 129, 0.15) !important;
}
.chosen-item td {
  border-top: 1px solid #10b981 !important;
  border-bottom: 1px solid #10b981 !important;
  box-shadow: inset 0 0 25px rgba(16, 185, 129, 0.25) !important;
}
.group-drag-handle:hover, .item-drag-handle:hover {
  color: #38bdf8;
}

/* ==============================================================
   VIP MODAL (MANUAL ENTRY)
============================================================== */
.vip-modal-overlay {
  background: rgba(10, 15, 30, 0.75) !important;
  backdrop-filter: blur(10px) !important;
}
.vip-modal-card {
  background: rgba(15, 23, 42, 0.85) !important;
  backdrop-filter: blur(25px) !important;
  border: 1px solid rgba(56, 189, 248, 0.3) !important;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), inset 0 0 40px rgba(56, 189, 248, 0.05) !important;
  border-radius: 16px !important;
  overflow: hidden;
  padding: 0 !important;
}
.vip-modal-card .modal-head {
  background: linear-gradient(90deg, rgba(56, 189, 248, 0.1), transparent) !important;
  border-bottom: 1px solid rgba(56, 189, 248, 0.2) !important;
  padding: 20px 24px !important;
}
.vip-modal-card .modal-head h3 {
  background: linear-gradient(to right, #38bdf8, #818cf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-weight: 800;
  letter-spacing: 0.5px;
  font-size: 18px;
}
.vip-modal-card .modal-group {
  background: rgba(255, 255, 255, 0.02) !important;
  border: 1px solid rgba(255, 255, 255, 0.05) !important;
  border-radius: 12px;
  padding: 24px;
  margin: 24px;
  transition: all 0.3s ease;
}
.vip-modal-card .modal-group:hover {
  background: rgba(255, 255, 255, 0.04) !important;
  border-color: rgba(56, 189, 248, 0.3) !important;
  box-shadow: 0 10px 30px -10px rgba(0,0,0,0.5);
}
.vip-modal-card .modal-group-title {
  color: #38bdf8 !important;
  font-size: 14px;
  letter-spacing: 1px;
  text-transform: uppercase;
  font-weight: 700;
}
.vip-modal-card input, .vip-modal-card textarea, .vip-modal-card select {
  background: rgba(0, 0, 0, 0.2) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  color: #f8fafc !important;
  transition: all 0.3s ease;
  border-radius: 8px;
}
.vip-modal-card input:focus, .vip-modal-card textarea:focus {
  border-color: #38bdf8 !important;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2) !important;
  background: rgba(0, 0, 0, 0.4) !important;
}
.vip-modal-card .modal-actions {
  background: rgba(0, 0, 0, 0.2) !important;
  border-top: 1px solid rgba(255, 255, 255, 0.05) !important;
  padding: 16px 24px !important;
  border-bottom-left-radius: 16px;
  border-bottom-right-radius: 16px;
}
.vip-modal-card .primary {
  background: linear-gradient(135deg, #0ea5e9, #3b82f6) !important;
  border: none !important;
  box-shadow: 0 4px 15px rgba(14, 165, 233, 0.4) !important;
  font-weight: 700;
  letter-spacing: 0.5px;
}
.vip-modal-card .primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(14, 165, 233, 0.6) !important;
}

/* ═══ ASYNC RESULT MODAL — VIP PREMIUM ═══ */
.async-overlay {
  position: fixed;
  inset: 0;
  z-index: 10050;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(12px) saturate(1.2);
}
.async-card {
  background: linear-gradient(160deg, rgba(30,41,59,0.95), rgba(15,23,42,0.98));
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 24px;
  padding: 48px 56px 40px;
  text-align: center;
  min-width: 340px;
  max-width: 440px;
  box-shadow:
    0 32px 100px rgba(0,0,0,0.6),
    0 0 0 1px rgba(255,255,255,0.04),
    inset 0 1px 0 rgba(255,255,255,0.06);
  position: relative;
  overflow: hidden;
}
.async-card::before {
  content: '';
  position: absolute;
  top: -2px; left: -2px; right: -2px; bottom: -2px;
  border-radius: 26px;
  background: conic-gradient(from 0deg, transparent 0%, rgba(56,189,248,0.3) 25%, transparent 50%, rgba(16,185,129,0.3) 75%, transparent 100%);
  z-index: -1;
  animation: async-border-spin 4s linear infinite;
  opacity: 0.5;
}
.async-loading .async-card::before { opacity: 1; }
@keyframes async-border-spin {
  to { transform: rotate(360deg); }
}
.async-title {
  font-size: 20px;
  font-weight: 800;
  color: #f8fafc;
  margin-top: 20px;
  letter-spacing: 0.4px;
  line-height: 1.4;
}
.async-subtitle {
  font-size: 13.5px;
  color: #94a3b8;
  margin-top: 10px;
  line-height: 1.6;
  white-space: pre-line;
}

/* ═══ PREMIUM SPINNER ═══ */
.async-spinner-wrap {
  display: flex;
  justify-content: center;
  position: relative;
  width: 80px;
  height: 80px;
  margin: 0 auto;
}
.async-spinner {
  width: 80px;
  height: 80px;
  animation: async-spin 1.2s cubic-bezier(0.5, 0, 0.5, 1) infinite;
  filter: drop-shadow(0 0 8px rgba(56,189,248,0.4));
}
.async-spinner circle {
  stroke: url(#async-gradient);
  stroke-dasharray: 80, 200;
  stroke-dashoffset: 0;
  animation: async-dash 1.5s ease-in-out infinite;
}
@keyframes async-spin {
  to { transform: rotate(360deg); }
}
@keyframes async-dash {
  0% { stroke-dasharray: 1, 200; stroke-dashoffset: 0; }
  50% { stroke-dasharray: 80, 200; stroke-dashoffset: -30; }
  100% { stroke-dasharray: 80, 200; stroke-dashoffset: -120; }
}
/* Orbiting dots */
.async-spinner-wrap::before,
.async-spinner-wrap::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  top: 50%; left: 50%;
  margin: -4px 0 0 -4px;
}
.async-spinner-wrap::before {
  background: #38bdf8;
  box-shadow: 0 0 12px rgba(56,189,248,0.6);
  animation: async-orbit 2s linear infinite;
}
.async-spinner-wrap::after {
  background: #a78bfa;
  box-shadow: 0 0 12px rgba(167,139,250,0.6);
  animation: async-orbit 2s linear infinite reverse;
  animation-delay: -1s;
}
@keyframes async-orbit {
  0% { transform: rotate(0deg) translateX(44px) rotate(0deg) scale(1); }
  50% { transform: rotate(180deg) translateX(44px) rotate(-180deg) scale(0.6); }
  100% { transform: rotate(360deg) translateX(44px) rotate(-360deg) scale(1); }
}

/* Pulse ring under spinner */
.async-spinner-wrap .async-spinner {
  position: relative;
  z-index: 2;
}

/* ═══ SUCCESS CHECKMARK — PREMIUM ═══ */
.async-icon-wrap {
  display: flex;
  justify-content: center;
  position: relative;
  width: 80px;
  height: 80px;
  margin: 0 auto;
}
.async-checkmark {
  width: 80px;
  height: 80px;
  position: relative;
  z-index: 2;
}
.async-checkmark circle {
  stroke: #10b981;
  stroke-width: 2.5;
  stroke-dasharray: 166;
  stroke-dashoffset: 166;
  animation: async-circle-draw 0.7s cubic-bezier(0.65, 0, 0.45, 1) forwards;
  filter: drop-shadow(0 0 6px rgba(16,185,129,0.5));
}
.async-checkmark path {
  stroke: #34d399;
  stroke-width: 3.5;
  stroke-dasharray: 48;
  stroke-dashoffset: 48;
  animation: async-check-draw 0.5s 0.5s cubic-bezier(0.65, 0, 0.45, 1) forwards;
  filter: drop-shadow(0 0 4px rgba(52,211,153,0.6));
}
@keyframes async-circle-draw {
  to { stroke-dashoffset: 0; }
}
@keyframes async-check-draw {
  to { stroke-dashoffset: 0; }
}
/* Success glow ring burst */
.async-icon-success {
  animation: async-pop 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.async-icon-success::before {
  content: '';
  position: absolute;
  inset: -12px;
  border-radius: 50%;
  border: 2px solid rgba(16,185,129,0.3);
  animation: async-ring-burst 0.8s 0.3s ease-out forwards;
  opacity: 0;
}
.async-icon-success::after {
  content: '';
  position: absolute;
  inset: -24px;
  border-radius: 50%;
  border: 1px solid rgba(16,185,129,0.15);
  animation: async-ring-burst 1s 0.5s ease-out forwards;
  opacity: 0;
}
@keyframes async-ring-burst {
  0% { transform: scale(0.5); opacity: 1; }
  100% { transform: scale(1.5); opacity: 0; }
}

/* ═══ ERROR X-MARK — PREMIUM ═══ */
.async-xmark {
  width: 80px;
  height: 80px;
  position: relative;
  z-index: 2;
}
.async-xmark circle {
  stroke: #ef4444;
  stroke-width: 2.5;
  stroke-dasharray: 166;
  stroke-dashoffset: 166;
  animation: async-circle-draw 0.7s cubic-bezier(0.65, 0, 0.45, 1) forwards;
  filter: drop-shadow(0 0 6px rgba(239,68,68,0.5));
}
.async-xmark path {
  stroke: #f87171;
  stroke-width: 3.5;
  stroke-dasharray: 56;
  stroke-dashoffset: 56;
  animation: async-check-draw 0.4s 0.5s cubic-bezier(0.65, 0, 0.45, 1) forwards;
  filter: drop-shadow(0 0 4px rgba(248,113,113,0.6));
}
.async-icon-error {
  animation: async-shake-vip 0.6s 0.4s cubic-bezier(0.36, 0.07, 0.19, 0.97);
}
.async-icon-error::before {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(239,68,68,0.15) 0%, transparent 70%);
  animation: async-error-pulse 1.5s 0.5s ease-in-out infinite;
}
@keyframes async-shake-vip {
  0%, 100% { transform: translateX(0) rotate(0deg); }
  15% { transform: translateX(-10px) rotate(-2deg); }
  30% { transform: translateX(10px) rotate(2deg); }
  45% { transform: translateX(-7px) rotate(-1deg); }
  60% { transform: translateX(7px) rotate(1deg); }
  75% { transform: translateX(-3px); }
  90% { transform: translateX(3px); }
}
@keyframes async-error-pulse {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.15); }
}
@keyframes async-pop {
  0% { transform: scale(0); opacity: 0; }
  50% { transform: scale(1.15); }
  70% { transform: scale(0.95); }
  100% { transform: scale(1); opacity: 1; }
}

/* ═══ CLOSE BUTTON — PREMIUM ═══ */
.async-close-btn {
  margin-top: 24px;
  padding: 12px 36px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(239,68,68,0.15), rgba(239,68,68,0.08));
  border: 1px solid rgba(239,68,68,0.25);
  color: #f87171;
  font-weight: 700;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  letter-spacing: 0.3px;
}
.async-close-btn:hover {
  background: linear-gradient(135deg, rgba(239,68,68,0.25), rgba(239,68,68,0.15));
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(239,68,68,0.2);
}

/* ═══ TRANSITION — PREMIUM ═══ */
.async-modal-enter-active {
  animation: async-modal-in 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.async-modal-leave-active {
