  background: rgba(59,130,246,0.2) !important;
  transform: scale(1.05) translateY(-2px) !important;
}

/* -- Image Button -- */
.export-vip-btn-image {
  border-color: rgba(236,72,153,0.15) !important;
}
.export-vip-btn-image::before {
  background: linear-gradient(135deg, rgba(236,72,153,0.08) 0%, rgba(244,114,182,0.02) 100%);
}
.export-vip-btn-image .export-vip-btn-icon {
  background: rgba(236,72,153,0.1) !important;
  color: #ec4899 !important;
}
.export-vip-btn-image .export-vip-btn-label { color: #ec4899 !important; }
.export-vip-btn-image .export-vip-btn-desc { color: #f472b6 !important; }
.export-vip-btn-image .export-vip-btn-arrow { color: #ec4899 !important; }
.export-vip-btn-image:hover {
  border-color: rgba(236,72,153,0.4) !important;
  box-shadow: 0 12px 30px rgba(236,72,153,0.12) !important;
}
.export-vip-btn-image:hover .export-vip-btn-icon {
  background: rgba(236,72,153,0.2) !important;
  transform: scale(1.05) translateY(-2px) !important;
}

/* ── Responsive: Stack columns on small screens ── */
@media (max-width: 580px) {
  .export-vip-body {
    grid-template-columns: 1fr;
  }
  .export-vip-col-upload {
    border-right: none;
    border-bottom: 1px solid rgba(16, 185, 129, 0.15);
  }
  .export-tpl-dropzone {
    padding: 20px 14px;
  }
}
/* ================== MOBILE 3-SCREEN FLOW (KHO SP -> BÁO GIÁ -> TỔNG KẾT -> MODAL KHÁCH HÀNG) ================== */
.mobile-progress-wrapper,
.mobile-top-util-btn,
.mobile-screen1-cart-bar,
.mobile-back-to-store-btn,
.mobile-quote-customer-card,
.mobile-quote-empty-card,
.mobile-quote-item-cell,
.mobile-quote-summary-card,
.mobile-screen2-action-bar,
.card-mobile-top-meta,
.cust-mobile-mini-actions,
.cust-import-btn .mb-lbl,
.mobile-cust-accordion-btn,
.export-tpl-radio-dot,
.export-tpl-mb-badge,
.export-tpl-setup-btn .mb-lbl,
.export-tpl-change-btn .mb-lbl,
.export-multi-setup-mobile-btn,
.export-multi-mobile-tabs,
.export-multi-head-title .mb-lbl,
.export-zoom-title-wrap .mb-lbl,
.pv-mode-toggle-btn .mb-lbl,
.pv-reset-btn .mb-lbl {
  display: none !important;
}

@media (max-width: 1100px) {
