    box-shadow: none !important;
  }

  /* QUAN TRỌNG: Tắt backdrop-filter/transform trên các vùng cuộn cha để thanh position: fixed không bị kẹt bên trong container */
  .sidebar-left,
  .product-sidebar,
  .quote-center,
  .quote-table-container {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    transform: none !important;
    filter: none !important;
  }

  /* LOGIC 3 MÀN HÌNH: SCREEN 1 (KHO SẢN PHẨM), SCREEN 2 (BÁO GIÁ), SCREEN 3 (TỔNG KẾT) */
  .main-grid.mobile-step-1 .quote-center {
    display: none !important;
  }
  .main-grid.mobile-step-1 .sidebar-left {
    display: flex !important;
    flex-direction: column !important;
    max-height: unset !important;
    margin-left: 0 !important;
    opacity: 1 !important;
    pointer-events: auto !important;
  }

  .main-grid:not(.mobile-step-1) .sidebar-left {
    display: none !important;
  }
  .main-grid:not(.mobile-step-1) .quote-center {
    display: flex !important;
    flex-direction: column !important;
  }
  .main-grid:not(.mobile-step-1) .quote-table-container {
    display: flex !important;
    flex-direction: column !important;
  }

  /* Screen 2: Chỉ hiện danh sách sản phẩm trong báo giá, ẩn phần Tổng kết */
  .main-grid.mobile-step-2 .quote-table-wrap {
    display: block !important;
  }
  .main-grid.mobile-step-2 .mobile-quote-summary-card {
    display: none !important;
  }

  /* Screen 3: Trang Tổng Kết (Chỉ hiện Chiết khấu + Tài chính, ẩn danh sách sản phẩm) */
  .main-grid.mobile-step-3 .quote-table-wrap {
    display: none !important;
  }
  .main-grid.mobile-step-3 .mobile-quote-summary-card {
    display: block !important;
  }

  /* ================= NATIVE APP MOBILE LAYOUT ================= */
  html, body {
    overflow-x: clip !important;
    overflow-y: auto !important;
    width: 100% !important;
    max-width: 100% !important;
  }

  .page {
    padding: 0 !important;
    margin: 0 !important;
