.quote-workspace-topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.96) 0%, rgba(9, 9, 11, 0.96) 100%);
  border-bottom: 1px solid rgba(56, 189, 248, 0.18);
  flex-shrink: 0;
  z-index: 36;
  min-width: 0;
}

.btn-add-quote-tab-circle {
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  min-height: 28px !important;
  max-width: 28px !important;
  max-height: 28px !important;
  border-radius: 50% !important;
  background: #10b981 !important;
  background-image: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
  color: #ffffff !important;
  border: 1px solid rgba(52, 211, 153, 0.5) !important;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.35) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  flex-shrink: 0 !important;
  flex-grow: 0 !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 1 !important;
}

.btn-add-quote-tab-circle:hover {
  background: #059669 !important;
  background-image: linear-gradient(135deg, #059669 0%, #047857 100%) !important;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.55) !important;
  transform: scale(1.08) !important;
}

.btn-add-quote-tab-circle:active {
  transform: scale(0.95) !important;
  box-shadow: 0 1px 4px rgba(16, 185, 129, 0.4) !important;
}

.quote-tabs-scroll {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  overflow-y: hidden;
  flex: 1;
  min-width: 0;
  padding-bottom: 2px;
  scrollbar-width: thin;
}

.quote-tabs-scroll::-webkit-scrollbar {
  height: 4px;
}

.quote-tabs-scroll::-webkit-scrollbar-thumb {
  background: rgba(100, 116, 139, 0.4);
  border-radius: 4px;
}

.quote-tab-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px 6px 12px;
  border-radius: 8px;
  background: rgba(30, 41, 59, 0.65);
  border: 1px solid rgba(51, 65, 85, 0.8);
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  flex-shrink: 0;
  transition: all 0.18s ease;
  position: relative;
}

.quote-tab-item:hover {
  background: rgba(30, 41, 59, 0.95);
  border-color: rgba(100, 116, 139, 0.8);
  color: #e2e8f0;
}

.quote-tab-item.active {
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.98) 0%, rgba(30, 41, 59, 0.98) 100%);
  border-color: #10b981;
  color: #ffffff;
  font-weight: 700;
  box-shadow: 0 2px 10px rgba(16, 185, 129, 0.18), inset 0 2px 0 #10b981;
}

.quote-tab-item.editing.active {
  border-color: #38bdf8;
  box-shadow: 0 2px 10px rgba(56, 189, 248, 0.2), inset 0 2px 0 #38bdf8;
}

.quote-tab-icon {
  flex-shrink: 0;
  color: #64748b;
  transition: color 0.18s ease;
}

.quote-tab-item.active .quote-tab-icon {
  color: #10b981;
}

.quote-tab-item.editing.active .quote-tab-icon {
  color: #38bdf8;
}

.quote-tab-title {
  max-width: 210px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.3;
}

.quote-tab-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  background: rgba(148, 163, 184, 0.16);
  color: #cbd5e1;
  border: 1px solid rgba(148, 163, 184, 0.25);
  line-height: 1.3;
}

.quote-tab-item.active .quote-tab-badge {
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.4);
  cursor: pointer;
  transition: all 0.15s ease;
}

.quote-tab-item.active .quote-tab-badge:hover {
  background: rgba(16, 185, 129, 0.32);
  color: #ffffff;
  border-color: #10b981;
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.35);
}

.quote-tab-close {
  width: 20px !important;
  min-width: 20px !important;
  height: 20px !important;
  padding: 0 !important;
  margin: 0 0 0 2px !important;
  border-radius: 5px !important;
  border: none !important;
  background: transparent !important;
  color: #64748b !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer;
  transition: all 0.15s ease !important;
  box-shadow: none !important;
}

.quote-tab-close:hover {
  background: rgba(239, 68, 68, 0.2) !important;
  color: #f87171 !important;
  transform: none !important;
}

/* ═══════════════════════════════════════════════════════════════════════════
   LIGHT MODE: TEMPLATE XANH DƯƠNG – TRẮNG (.page.theme-light-blue)
   ═══════════════════════════════════════════════════════════════════════════ */
.page.theme-light-blue {
  background: linear-gradient(180deg, #eef4fb 0%, #e2ecf8 100%) !important;
  color: #0f172a !important;
}

/* 1. Khối Kho sản phẩm bên trái */
.page.theme-light-blue .product-sidebar {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.07) !important;
}

.page.theme-light-blue .sidebar-head-product {
  border-bottom: 1px solid #e2e8f0 !important;
}

.page.theme-light-blue .sidebar-head-product::after {
  background: linear-gradient(90deg, transparent, rgba(37, 99, 235, 0.3), transparent) !important;
}

.page.theme-light-blue .sidebar-head-product button {
  background: #f1f5f9 !important;
  color: #334155 !important;
  border: 1px solid #cbd5e1 !important;
}

.page.theme-light-blue .sidebar-head-product button:hover {
  background: #e2e8f0 !important;
  color: #0f172a !important;
}

.page.theme-light-blue .sidebar-head-product label,
.page.theme-light-blue .sidebar-head-product div {
  color: #475569 !important;
}

.page.theme-light-blue .search-icon {
  stroke: #2563eb !important;
}

.page.theme-light-blue .product-sidebar .search-input {
  background: #f8fafc !important;
  border: 1px solid #93c5fd !important;
  color: #0f172a !important;
}

.page.theme-light-blue .product-sidebar .search-input::placeholder {
  color: #64748b !important;
}

.page.theme-light-blue .product-sidebar .search-input:focus {
  background: #ffffff !important;
  border-color: #2563eb !important;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15) !important;
}

/* Card sản phẩm */
.page.theme-light-blue .card {
  background: #ffffff !important;
  border: 1px solid #e2e8f0 !important;
  border-left: 3px solid #2563eb !important;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.04) !important;
}

.page.theme-light-blue .card:hover {
  background: #f8fbff !important;
  border-color: #93c5fd !important;
  border-left-color: #1d4ed8 !important;
  box-shadow: 0 6px 16px rgba(37, 99, 235, 0.12) !important;
}

.page.theme-light-blue .card h4 {
  color: #0f172a !important;
}

.page.theme-light-blue .card-license {
  color: #475569 !important;
}

.page.theme-light-blue .card-bottom-row {
  border-top: 1px solid #f1f5f9 !important;
}

.page.theme-light-blue .card-price-row span,
.page.theme-light-blue .card .price,
.page.theme-light-blue .card-orig-price {
  color: #059669 !important;
}

.page.theme-light-blue .card .price-unit {
  color: #64748b !important;
}

.page.theme-light-blue .qty button {
  background: #f1f5f9 !important;
  border: 1px solid #cbd5e1 !important;
  color: #334155 !important;
}

.page.theme-light-blue .qty button:hover {
  background: #e2e8f0 !important;
  color: #0f172a !important;
}

.page.theme-light-blue .qty button:last-child {
  background: #eff6ff !important;
  border-color: #93c5fd !important;
  color: #2563eb !important;
}

.page.theme-light-blue .qty button:last-child:hover {
  background: #2563eb !important;
  border-color: #2563eb !important;
  color: #ffffff !important;
}

.page.theme-light-blue .qty span {
  color: #0f172a !important;
}

.page.theme-light-blue .btn-add {
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%) !important;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.25) !important;
}

.page.theme-light-blue .btn-add:hover {
  background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%) !important;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35) !important;
}

/* 2. Cụm Dock bên dưới Kho sản phẩm (Khách hàng | Chiết khấu | Tài chính + Nút) */
.page.theme-light-blue .bottom-totals.left-sidebar-dock {
  background: linear-gradient(180deg, #f0f7ff 0%, #e0ecff 100%) !important;
  border-top: 2px solid #2563eb !important;
  box-shadow: 0 -6px 20px rgba(30, 64, 175, 0.08) !important;
}

.page.theme-light-blue .dock-tab-btn {
  background: #ffffff !important;
  color: #475569 !important;
  border: 1px solid #cbd5e1 !important;
}

.page.theme-light-blue .dock-tab-btn:hover {
  background: #eff6ff !important;
  color: #1d4ed8 !important;
  border-color: #93c5fd !important;
}

.page.theme-light-blue .dock-tab-btn.active {
  background: #2563eb !important;
  color: #ffffff !important;
  border-color: #1d4ed8 !important;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.25) !important;
}

.page.theme-light-blue .bottom-totals.left-sidebar-dock .totals-box.dock-tab-panel {
  background: #ffffff !important;
  border: 1px solid #bfdbfe !important;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04) !important;
}

.page.theme-light-blue .step-customer .totals-header {
  background: #eff6ff !important;
  border-bottom: 1px solid #bfdbfe !important;
}

.page.theme-light-blue .step-customer .totals-header span,
.page.theme-light-blue .step-customer .totals-header .totals-icon {
  color: #1d4ed8 !important;
}

.page.theme-light-blue .step-customer .totals-body div {
  color: #334155 !important;
}

.page.theme-light-blue .step-customer .cell-input {
  background: #f8fafc !important;
  border: 1px solid #cbd5e1 !important;
  color: #0f172a !important;
}

.page.theme-light-blue .step-customer .cell-input:focus {
  background: #ffffff !important;
  border-color: #2563eb !important;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15) !important;
}

.page.theme-light-blue .totals-row {
  border-bottom: 1px solid #f1f5f9 !important;
}

.page.theme-light-blue .totals-row:hover {
  background: #f8fafc !important;
}

.page.theme-light-blue .totals-label {
  color: #334155 !important;
  text-shadow: none !important;
}

.page.theme-light-blue .totals-value {
  color: #0f172a !important;
}

.page.theme-light-blue .totals-value.text-warn {
  color: #d97706 !important;
  text-shadow: none !important;
}

.page.theme-light-blue .totals-highlight {
  background: #fffbeb !important;
  border-top: 1px dashed #f59e0b !important;
}

.page.theme-light-blue .totals-highlight .totals-label {
  color: #b45309 !important;
}

.page.theme-light-blue .totals-highlight .totals-value {
  color: #d97706 !important;
}

.page.theme-light-blue .totals-highlight-blue {
  background: #eff6ff !important;
  border-top: 1px dashed #60a5fa !important;
}

.page.theme-light-blue .totals-highlight-blue .totals-label {
  color: #1d4ed8 !important;
}

.page.theme-light-blue .totals-highlight-blue .totals-value {
  color: #2563eb !important;
}

.page.theme-light-blue .step-actions button:not(.action-save) {
  background: #ffffff !important;
  border: 1px solid #93c5fd !important;
  color: #2563eb !important;
}

.page.theme-light-blue .step-actions button:not(.action-save):hover {
  background: #eff6ff !important;
  border-color: #2563eb !important;
}

/* 3. Khối Bảng báo giá chi tiết bên phải */
.page.theme-light-blue .quote-table-container {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.07) !important;
}

.page.theme-light-blue .quote-workspace-topbar {
  background: #f8fafc !important;
  border-bottom: 1px solid #e2e8f0 !important;
}

.page.theme-light-blue .quote-tab-item {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  color: #475569 !important;
}

.page.theme-light-blue .quote-tab-item:hover {
  background: #f1f5f9 !important;
  border-color: #94a3b8 !important;
  color: #0f172a !important;
}

.page.theme-light-blue .quote-tab-item.active {
  background: #eff6ff !important;
  border-color: #2563eb !important;
  color: #1e3a8a !important;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.14), inset 0 2px 0 #2563eb !important;
}

.page.theme-light-blue .quote-tab-item.active .quote-tab-icon {
  color: #2563eb !important;
}

.page.theme-light-blue .quote-tab-badge {
  background: #f1f5f9 !important;
  color: #475569 !important;
  border-color: #cbd5e1 !important;
}

.page.theme-light-blue .quote-tab-item.active .quote-tab-badge {
  background: #dbeafe !important;
  color: #1d4ed8 !important;
  border-color: #93c5fd !important;
}

.page.theme-light-blue .quote-tab-item.active .quote-tab-badge:hover {
  background: #2563eb !important;
  color: #ffffff !important;
  border-color: #1d4ed8 !important;
}

.page.theme-light-blue .table-header-box {
  background: #ffffff !important;
  border-bottom: 1px solid #e2e8f0 !important;
}

.page.theme-light-blue .table-header-box::after {
  background: linear-gradient(90deg, transparent, rgba(37, 99, 235, 0.25), transparent) !important;
}

.page.theme-light-blue .table-header-box h3 {
  color: #1d4ed8 !important;
  -webkit-text-fill-color: #1d4ed8 !important;
}

.page.theme-light-blue .table-header-box button[title*="Ghi âm giọng nói"] {
  background: #f8fafc !important;
  color: #1e293b !important;
  border: 1px solid #cbd5e1 !important;
}

.page.theme-light-blue .table-header-box button[title*="Ghi âm giọng nói"]:hover {
  background: #eff6ff !important;
  border-color: #93c5fd !important;
  color: #1d4ed8 !important;
}

.page.theme-light-blue .contract-badge,
.page.theme-light-blue .unified-contract-pill {
  background: #f1f5f9 !important;
  color: #475569 !important;
  border: 1px solid #cbd5e1 !important;
}

.page.theme-light-blue .contract-seg {
  color: #475569 !important;
}

.page.theme-light-blue .contract-sep {
  color: #cbd5e1 !important;
}

.page.theme-light-blue .contract-badge b,
.page.theme-light-blue .contract-seg b {
  color: #1d4ed8 !important;
}

.page.theme-light-blue .vip-currency-switch {
  background: #e2e8f0 !important;
  border: 1px solid #cbd5e1 !important;
  box-shadow: inset 0 1px 3px rgba(15, 23, 42, 0.1) !important;
}

/* Header, Dòng nhóm danh mục, Dòng sản phẩm & Footer của Bảng báo giá */
.page.theme-light-blue thead th {
  background: linear-gradient(135deg, #1d4ed8 0%, #2563eb 100%) !important;
  color: #ffffff !important;
  border-bottom: 1px solid #1e40af !important;
}

.page.theme-light-blue .group-row td {
  background: linear-gradient(90deg, #dbeafe 0%, #eff6ff 100%) !important;
  color: #1e3a8a !important;
  border-top: 1px solid #bfdbfe !important;
  border-bottom: 1px solid #93c5fd !important;
}
.page.theme-light-blue .group-row td:first-child {
  border-left: 4px solid #2563eb !important;
}
.page.theme-light-blue .group-stt,
.page.theme-light-blue .group-title {
  color: #1e3a8a !important;
}
.page.theme-light-blue .inline-normal-edit {
  background: #eff6ff !important;
  color: #1d4ed8 !important;
  border: 1px solid #93c5fd !important;
}
.page.theme-light-blue .inline-normal-edit:hover {
  background: #dbeafe !important;
  border-color: #3b82f6 !important;
  color: #1e40af !important;
}
.page.theme-light-blue .inline-adjust {
  background: #fffbeb !important;
  color: #b45309 !important;
  border: 1px solid #fcd34d !important;
}
.page.theme-light-blue .inline-adjust:hover {
  background: #fef3c7 !important;
  border-color: #f59e0b !important;
  color: #92400e !important;
}

.page.theme-light-blue tbody tr.quote-item-row:nth-child(odd) {
  background: #ffffff !important;
}

.page.theme-light-blue tbody tr.quote-item-row:nth-child(even) {
  background: #f8fafc !important;
}

.page.theme-light-blue tbody tr.quote-item-row:hover td {
  background-color: #eff6ff !important;
}

.page.theme-light-blue tbody tr.quote-item-row td {
  border-bottom: 1px solid #e2e8f0 !important;
  color: #0f172a !important;
}

.page.theme-light-blue tbody tr.quote-item-row td[data-label="SKU Code"] {
  color: #0284c7 !important;
}

.page.theme-light-blue tbody tr.quote-item-row td[data-label="Description"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="Diễn giải"] {
  color: #334155 !important;
}

.page.theme-light-blue tbody tr.quote-item-row td[data-label="Giá vốn / Giá off hãng"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="List Price"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="Đơn giá (KH)"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="TT trước thuế"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="VAT"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="TT sau thuế"] {
  color: #059669 !important;
}

.page.theme-light-blue tbody tr.quote-item-row td[data-label="VAT"] .muted {
  color: #059669 !important;
}

.page.theme-light-blue tbody tr.quote-item-row td[data-label="Giá nhập"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="Mức off"],
.page.theme-light-blue tbody tr.quote-item-row td[data-label="Mức off"] .muted {
  color: #dc2626 !important;
}

.page.theme-light-blue tfoot td,
.page.theme-light-blue tfoot tr.table-footer-sticky {
  background: linear-gradient(180deg, #f0f7ff 0%, #e0ecff 100%) !important;
  color: #0f172a !important;
  border-top: 2px solid #2563eb !important;
  box-shadow: 0 -4px 14px rgba(37, 99, 235, 0.08) !important;
}

.page.theme-light-blue tfoot tr.table-footer-sticky td.center:first-child {
  color: #1e40af !important;
}

.page.theme-light-blue tfoot tr.table-footer-sticky [data-tooltip="Tổng Mức OFF"] {
  color: #dc2626 !important;
}

.page.theme-light-blue tfoot tr.table-footer-sticky [data-tooltip="Tổng TT trước thuế"] {
  color: #0f172a !important;
}

.page.theme-light-blue tfoot tr.table-footer-sticky [data-tooltip="Tổng VAT"] {
  color: #0284c7 !important;
}

.page.theme-light-blue tfoot tr.table-footer-sticky [data-tooltip="Tổng TT sau thuế"] {
  color: #1d4ed8 !important;
}

@media (max-width: 1100px) {
  .page.theme-light-blue .product-sidebar,
  .page.theme-light-blue .quote-table-container {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }
  .page.theme-light-blue .quote-table-wrap tr.group-row {
    background: linear-gradient(90deg, #dbeafe 0%, #eff6ff 100%) !important;
    border: 1px solid #93c5fd !important;
    border-left: 3px solid #2563eb !important;
  }
  .page.theme-light-blue .quote-table-wrap tr.group-row td,
  .page.theme-light-blue .quote-table-wrap tr.group-row td:first-child {
    background: transparent !important;
    border: none !important;
    color: #1e3a8a !important;
  }
  .page.theme-light-blue tbody tr.quote-item-row,
  .page.theme-light-blue tbody tr.quote-item-row:nth-child(odd),
  .page.theme-light-blue tbody tr.quote-item-row:nth-child(even),
  .page.theme-light-blue tbody tr.quote-item-row:hover td,
  .page.theme-light-blue tbody tr.quote-item-row td.mobile-quote-item-cell {
    background: transparent !important;
    border: none !important;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   MODAL FULLSCREEN: CHI TIẾT HÀNG, CHỈNH SỬA HÀNG, NẠP/XUẤT DỮ LIỆU, LỊCH SỬ, XEM BÁO GIÁ GỐC
   ═══════════════════════════════════════════════════════════════════════════ */
.modal.modal-fullscreen-overlay {
  padding: 0 !important;
}

.modal-card.modal-fullscreen-card,
.modal .modal-card.export-vip-modal.modal-fullscreen-card,
.modal .modal-card.load-invoice-modal.modal-fullscreen-card,
.modal .modal-card.history-modal-card.modal-fullscreen-card {
  width: 100vw !important;
  max-width: 100vw !important;
  height: 100vh !important;
  max-height: 100vh !important;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 0 !important;
  border: none !important;
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
}

.export-vip-modal.modal-fullscreen-card .export-vip-head {
  flex-shrink: 0 !important;
}

.export-vip-modal.modal-fullscreen-card .export-vip-body {
