/* Inline Picker Button inside Input (replaces native datalist dropdown arrow) */
.input-with-picker {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
}

.inline-picker-btn {
  position: absolute !important;
  right: 6px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  padding: 5px 10px !important;
  border-radius: 6px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.3px !important;
  background: rgba(2, 132, 199, 0.22) !important;
  color: #38bdf8 !important;
  border: 1px solid rgba(56, 189, 248, 0.45) !important;
  cursor: pointer !important;
  width: fit-content !important;
  height: auto !important;
  margin: 0 !important;
  line-height: 1.1 !important;
  z-index: 3 !important;
  transition: all 0.15s ease !important;
}

.inline-picker-btn:hover {
  background: #0284c7 !important;
  color: #ffffff !important;
  border-color: #0284c7 !important;
}

.inline-picker-btn.inline-picker-btn-sm {
  right: 4px !important;
  padding: 3px 7px !important;
  font-size: 10px !important;
  border-radius: 5px !important;
}

.page.theme-light-blue .inline-picker-btn {
  background: #e0f2fe !important;
  color: #0369a1 !important;
  border: 1px solid #7dd3fc !important;
}

.page.theme-light-blue .inline-picker-btn:hover {
  background: #0284c7 !important;
  color: #ffffff !important;
  border-color: #0284c7 !important;
}

/* Picker Modals (Customer & Product) */
.picker-table-box {
  background: rgba(15, 23, 42, 0.45);
}

.picker-data-table {
  width: 100% !important;
  min-width: 0 !important;
  table-layout: fixed !important;
  border-collapse: collapse !important;
}

.picker-data-table thead th,
.picker-data-table th {
  position: sticky !important;
  top: 0 !important;
  z-index: 2 !important;
  background: #1e293b !important;
  color: #94a3b8 !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.4px !important;
  padding: 11px 12px !important;
  border-bottom: 1px solid rgba(148, 163, 184, 0.22) !important;
  vertical-align: middle !important;
  box-sizing: border-box !important;
}

.picker-data-table tbody td,
.picker-data-table td {
  padding: 10px 12px !important;
  border-bottom: 1px solid rgba(148, 163, 184, 0.12) !important;
  color: #f1f5f9;
  vertical-align: middle !important;
  box-sizing: border-box !important;
}

.picker-row {
  cursor: pointer;
  transition: background 0.12s ease;
}

.picker-row:hover {
  background: rgba(56, 189, 248, 0.1);
}

.picker-row-selected {
  background: rgba(16, 185, 129, 0.14) !important;
}

.picker-select-action-btn {
  padding: 5px 12px !important;
  border-radius: 6px !important;
  font-size: 11.5px !important;
  font-weight: 800 !important;
  background: #0284c7 !important;
  color: #ffffff !important;
  border: none !important;
  cursor: pointer !important;
  width: fit-content !important;
  margin: 0 auto !important;
  transition: all 0.15s ease !important;
}

.picker-select-action-btn:hover {
  background: #0369a1 !important;
}

